window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0212", [{"word":"encryption","ipa_uk":"/ɪnˈkrɪpʃn/","ipa_us":"/ɪnˈkrɪpʃən/","definition_zh":"加密；把可读信息转成只有持钥匙者才能还原的编码形式的过程","definition_en":"the process of turning readable information into a coded form that only the holder of the key can turn back","core_image":"一封写好的信被锁进铁盒，盒面只剩谁也读不懂的乱码，钥匙挂在大门看守人的腰上","scene":"机房里的灯一直亮着，操作员把钥匙插进读卡器，屏幕上滚过一串谁也读不懂的字符。Before sending the file, she switched on encryption so that anyone intercepting it would see only random characters.","sceneCN":"这里 encryption 指把可读信息转成密文的过程（第 1 个义项：把明文变成密文的动作）；句意：发送文件之前她开启了加密，中途截获的人只会看到乱码。","pos":[{"tag":"n.","zh":"加密；密文化过程；加密方式"}],"collocations":[{"phrase":"encryption key","zh":"加密密钥"},{"phrase":"data encryption","zh":"数据加密"},{"phrase":"end-to-end encryption","zh":"端到端加密"},{"phrase":"strong encryption","zh":"高强度加密"},{"phrase":"encryption algorithm","zh":"加密算法"},{"phrase":"encryption standard","zh":"加密标准"},{"phrase":"turn on encryption","zh":"开启加密"}],"forms":[{"label":"复数","form":"encryptions"}],"derivatives":[{"word":"encrypt","pos":"v.","zh":"加密；把明文变成密文"},{"word":"encrypted","pos":"adj.","zh":"已加密的"},{"word":"encryptionist","pos":"n.","zh":"加密技术的主张者（罕用）"}],"senses":[{"no":"01","title":"The act of turning plain text into code","titleCN":"把明文变成密文的动作","definition":"the act of converting readable information into a coded form by a fixed procedure","definitionCN":"用固定程序把可读信息转换成编码形式的动作","example":"Encryption takes place before the message leaves the phone.","exampleCN":"消息离开手机之前就完成了加密。","why":"the -tion ending names an action and its result, so the word first denotes the doing of the transformation itself.","whyCN":"词尾表示动作及其结果，因此这个词首先指「做转换」这件事本身。"},{"no":"02","title":"The coded output itself","titleCN":"加密后得到的密文","definition":"the unreadable text or data produced by the transformation","definitionCN":"由转换产生、无法直接读懂的文字或数据","example":"The intercepted file was pure encryption and told them nothing.","exampleCN":"截获的文件全是密文，他们什么也看不出。","why":"the same action noun came to stand for the thing the action leaves behind, the way a building can name the act of building.","whyCN":"同一个动作名词也指动作留下的东西，就像「建筑」既可指建造也可指楼房。"},{"no":"03","title":"The field of study and practice","titleCN":"密码学中的加密分支","definition":"the branch of cryptography that designs and applies such transformations","definitionCN":"密码学中设计并使用这类转换的分支","example":"She teaches encryption alongside authentication and key exchange.","exampleCN":"她把加密与身份认证、密钥交换放在一起讲授。","why":"a repeated practice becomes a named discipline, and the action noun is reused for the whole field.","whyCN":"反复进行的实践会变成一个有名目的学科，动作名词就被用来指整个领域。"},{"no":"04","title":"Protection of stored data","titleCN":"对静态数据的保护","definition":"the encoding of files or disks so that a lost device does not expose its contents","definitionCN":"对文件或磁盘进行编码，使设备丢失时内容不外泄","example":"Full-disk encryption saved the company when a laptop was stolen.","exampleCN":"一台笔记本被盗时，全盘加密救了这家公司。","why":"data that sits still has no channel to protect, so the word shifted from sending to keeping.","whyCN":"静止的数据没有传输通道可保护，于是这个词从「发送」转向「保存」。"},{"no":"05","title":"Protection of a live connection","titleCN":"对传输中连接的加密","definition":"the encoding of traffic while it travels between two parties or devices","definitionCN":"数据在两方或两台设备之间传输时进行的编码","example":"The chat app applies encryption to every message in transit.","exampleCN":"这款聊天应用对传输中的每条消息都进行加密。","why":"the oldest use of secret writing was to guard a message on the road, and networks repeat that situation exactly.","whyCN":"秘密书写最古老的用途就是在路上保护消息，网络只是原样重演了这个场景。"},{"no":"06","title":"Secret writing in history","titleCN":"历史上的密文书写","definition":"the old practice of hiding a written message by substitution or transposition","definitionCN":"用替换或换位把书面消息藏起来的古老做法","example":"Court letters relied on encryption long before electric machines.","exampleCN":"早在电气机器出现之前，宫廷信件就依赖密文书写。","why":"the modern noun inherits a centuries-old craft, so historical ciphers are still called encryption.","whyCN":"现代名词继承了一门数百年的手艺，因此历史密码也仍被称为加密。"},{"no":"07","title":"The mechanism of key and algorithm","titleCN":"密钥与算法的机制","definition":"the paired rule and secret value that make the transformation reversible","definitionCN":"使这种转换可以逆转的成对规则与秘密数值","example":"Weak encryption here means a short key, not a short message.","exampleCN":"这里说的加密强度不足，指的是密钥太短，而不是消息太短。","why":"people speak of the machinery by the name of its effect, so a strong key is praised as strong encryption.","whyCN":"人们习惯用效果之名来指机器本身，于是强密钥被称赞为强加密。"},{"no":"08","title":"Deliberate obscurity of meaning","titleCN":"有意让表达晦涩","definition":"the figurative use for language made needlessly hard to understand","definitionCN":"转指被人为弄得难以理解的语言","example":"The report's encryption of plain facts fooled nobody.","exampleCN":"那份报告把简单事实写得晦涩，谁也没被唬住。","why":"coded writing is unreadable by design, and dull prose that hides its meaning borrows the same image.","whyCN":"密文因设计而不可读，故意掩盖意思的晦涩文章便借用了同一个意象。"}],"etymology":{"intro":{"en":"Encryption joins an English prefix and a Greek root: en-, into, plus kryptos, hidden. The noun ending came through Latin. The machine age gave the old idea of secret writing a technical name.","cn":"encryption 由英语前缀与希腊词根拼成：en- 表示「进入」，kryptos 表示「隐藏」，名词词尾经拉丁语而来。机器时代给古老的秘密书写取了一个技术名称。"},"items":[{"era":"GREEK KRYPTOS","en":"Greek kryptos meant hidden or covered, from kryptein, to hide. It described a thing put out of sight, not yet a method of writing.","cn":"希腊语 kryptos 意为「隐藏的、被遮盖的」，来自动词 kryptein「隐藏」。它描述的是被藏起来的东西，还不是一种书写方法。"},{"era":"LATIN CRYPTA","en":"Latin crypta, borrowed from Greek, named a covered vault or underground chamber. English crypt still means such a chamber.","cn":"拉丁语 crypta 借自希腊语，指有顶的地下室或拱形地窖。英语 crypt 至今仍指这种地窖。"},{"era":"ENGLISH CRYPT AND CRYPTIC","en":"English took crypt for a vault and cryptic for something deliberately obscure, keeping the sense of concealment without any computing meaning.","cn":"英语以 crypt 指地窖，以 cryptic 指故意晦涩的事物，保留了「藏」的意思，与计算毫无关系。"},{"era":"EN- PLUS -TION","en":"The verb encrypt puts en-, into, before the old root, and the noun adds the Latin ending -tion, so the word literally says putting something into hiding.","cn":"动词 encrypt 在旧词根前加 en-「进入」，名词再加拉丁词尾 -tion，字面意思就是「把东西放进隐藏状态」。"},{"era":"MODERN CRYPTOGRAPHY","en":"From the twentieth century the word settled on mathematical transformation with a key, first in military signalling and later in computing.","cn":"二十世纪起，这个词固定指使用密钥的数学变换，先用于军事通信，后来进入计算机领域。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of Greek kryptein is not settled, and the older forms sometimes compared with it are reconstructions rather than attested words.","cn":"来源不确定：希腊语 kryptein 更早的来源没有定论，常被拿来比较的更古形式属于重构形式，而非有记载的词。"}]},"similar":{"note":{"en":"The first group shares the hidden-root; the second group names neighbouring ways of protecting information.","cn":"第一组共享「隐藏」这一词根；第二组是与保护信息相邻的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"encrypt","ipa":"/ɪnˈkrɪpt/","tag":"the verb behind the noun","definition":"The action itself: to turn readable text into code. Encryption is the name of that action or of its result.","definitionCN":"指动作本身：把可读文本变成代码。encryption 则是这个动作或其结果的名称。"},{"word":"decryption","ipa":"/diːˈkrɪpʃn/","tag":"the reverse action","definition":"The same root with the reversing prefix: the act of turning the code back into readable form.","definitionCN":"同一词根加表示反向的前缀：把代码还原成可读形式的行为。"},{"word":"cryptic","ipa":"/ˈkrɪptɪk/","tag":"same root, adjective","definition":"Hidden in meaning rather than in code; a cryptic remark puzzles the listener without any cipher.","definitionCN":"指意思难解，而不是被编码；cryptic 的话让人费解，却并没有使用密码。"},{"word":"crypt","ipa":"/krɪpt/","tag":"same root, place","definition":"The old concrete sense of the root: a covered underground room, especially beneath a church.","definitionCN":"词根古老的实体义：有顶的地下室，尤指教堂地下墓室。"}]},{"heading":"NEAR MEANING","entries":[{"word":"encoding","ipa":"/ɪnˈkəʊdɪŋ/","tag":"conversion without secrecy","definition":"Changing data into another representation that anyone with the rule can read; secrecy is not required.","definitionCN":"把数据换成另一种表示，任何人知道规则都能读，并不要求保密。"},{"word":"cipher","ipa":"/ˈsaɪfə/","tag":"the old word for the method","definition":"A rule for substituting symbols; encryption is the modern technical name for applying such a rule with a key.","definitionCN":"替换符号的规则；encryption 是用密钥执行这类规则的现代技术名称。"},{"word":"hashing","ipa":"/ˈhæʃɪŋ/","tag":"one-way, not reversible","definition":"Turning data into a fixed-length fingerprint that cannot be turned back; it checks integrity rather than hiding content for later reading.","definitionCN":"把数据变成定长指纹且不可逆，用于校验完整性，而不是隐藏内容供日后阅读。"},{"word":"concealment","ipa":"/kənˈsiːlmənt/","tag":"the general idea","definition":"The broad act of keeping something out of sight; encryption is concealment carried out by a mathematical rule.","definitionCN":"把东西藏起来的泛称；encryption 是用数学规则完成的隐藏。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek pieces, the real family and the real fixed phrases.","cn":"正常联想：真实的希腊语构件、真实的同族词与真实的固定搭配。"},"normal":[{"en":"kryptos means hidden, so encryption is literally a putting-into-hiding.","cn":"kryptos 意为「隐藏」，encryption 字面上就是「放进隐藏状态」。"},{"en":"The family lines up neatly: encrypt, encrypted, encryption, decryption.","cn":"同族词排列整齐：encrypt、encrypted、encryption、decryption。"},{"en":"Fixed phrases locate the word: encryption key, data encryption, end-to-end encryption.","cn":"固定搭配给它定位：加密密钥、数据加密、端到端加密。"},{"en":"The ending marks a process noun, like protection and inspection.","cn":"词尾标记过程名词，与 protection、inspection 同类。"},{"en":"Encryption hides the message; decryption brings it back with the key.","cn":"加密把消息藏起来，解密用钥匙把它带回来。"}],"abstract":[{"en":"Picture a letter locked in a box whose lid is carved with random grooves, and the grooves are the letter.","cn":"想象一封信锁进盒子，盒盖刻满看似随机的沟槽，而那些沟槽就是信本身。"},{"en":"Picture a key that is also a sentence, and only the reader who knows the sentence can read the door.","cn":"想象一把钥匙同时也是一句话，只有知道这句话的人才能读懂那扇门。"},{"en":"Picture noise on a wire that is perfectly orderly if you stand at the right end of it.","cn":"想象线路上的噪声乱作一团，可只要站在正确的一端，它其实井然有序。"}]},"examples":[{"en":"Modern encryption depends on keys that are hard to guess and easy to replace.","cn":"现代加密依赖难以猜测、又便于更换的密钥。"},{"en":"The archive keeps its files under encryption so that a lost disk reveals nothing.","cn":"档案馆把文件加密保存，磁盘丢失也不会泄露内容。"},{"en":"Without encryption, a public network is simply a room with no walls.","cn":"没有加密，公共网络就是一间没有墙的房间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因（en）刻（cry）扑（pt）」——把内容刻进乱码里扑住，就是加密","word":"encryption"},"root":"希腊 kryptos「隐藏的」← kryptein「隐藏」→ 拉丁 crypta「地窖」→ 英语 crypt / cryptic；加前缀 en-「进入」与拉丁词尾 -tion 构成 encryption，二十世纪固定为密钥变换的术语。","sensesIntro":{"en":"Eight senses follow one line: readable text is put out of sight, then the hidden text, the trade, the stored copy, the travelling message, the old craft, the key mechanism and finally the obscure style.","cn":"八个义项沿一条线展开：可读文本先被藏起来，接着是被藏起来的文本、这门行业、静止的副本、传输中的消息、古老手艺、密钥机制，最后是晦涩的文风。"},"semanticMap":{"core":{"en":"CORE IMAGE: a written sheet locked in a box whose lid carries meaningless grooves, with one key in the world able to open it.","cn":"核心意象：一张写满字的纸锁在盒里，盒盖刻着无意义的沟槽，世上只有一把钥匙能打开。"},"chain":["READABLE TEXT","TRANSFORMATION","CODED OUTPUT","SECRECY","KEY AND RULE","PROTECTED DATA"],"branches":[{"senses":"01 · 02","en":"ACT AND PRODUCT: the doing of the conversion and the unreadable result it leaves behind.","cn":"动作与成品：转换这件事本身，以及它留下的不可读结果。"},{"senses":"03 · 07","en":"DISCIPLINE AND MECHANISM: the field that studies the method, and the rule-and-key pair that carries it out.","cn":"学科与机制：研究这套方法的领域，以及执行它的规则与密钥。"},{"senses":"04 · 05","en":"TWO SITUATIONS: data standing still on a disk, and data moving along a connection.","cn":"两种场景：静止在磁盘上的数据，以及沿连接传输中的数据。"},{"senses":"06","en":"OLD CRAFT: substitution and transposition by hand, the ancestor of the technical procedure.","cn":"古老手艺：手工的替换与换位，是这套技术程序的前身。"},{"senses":"08","en":"FIGURATIVE OBSCURITY: language made hard to read without any cipher at all.","cn":"比喻性的晦涩：并没有使用密码，却把语言写得难以读懂。"}]},"affixes":{"intro":{"en":"Encryption is assembled from an English prefix, a Greek root and a Latin noun ending; English later added -ed and -ing forms to the verb.","cn":"encryption 由英语前缀、希腊词根与拉丁名词词尾拼成；英语后来又给动词加了 -ed、-ing 形式。"},"latinIntro":{"en":"The Latin contribution is the ending -tion, from -tionem, which turns an action verb into a noun of action; crypta is a Greek loan in Latin.","cn":"拉丁语的贡献是词尾 -tion（来自 -tionem），把动作动词变成动作名词；crypta 则是拉丁语中的希腊借词。"},"items":[{"word":"en-","structure":"en- (English prefix from Latin in-)","meaning":"into, put into","meaningCN":"进入；使处于","example":"The prefix says the message is put into a hidden state.","exampleCN":"这个前缀表示消息被放进隐藏状态。"},{"word":"kryptos","structure":"kryptos (Greek adjective)","meaning":"hidden, covered","meaningCN":"隐藏的；被遮盖的","example":"The adjective describes what cannot be seen.","exampleCN":"这个形容词描述看不见的东西。"},{"word":"kryptein","structure":"kryptein (Greek verb)","meaning":"to hide, to cover","meaningCN":"隐藏；遮盖","example":"The verb is the action behind the whole family.","exampleCN":"这个动词是整个词族背后的动作。"},{"word":"crypta","structure":"crypta (Latin noun from Greek)","meaning":"a covered vault or chamber","meaningCN":"有顶的地窖或密室","example":"Latin kept the covered-place sense and passed it to English.","exampleCN":"拉丁语保留了「有顶之处」的意思，并传给英语。"},{"word":"-tion","structure":"-tion (Latin noun ending, from -tionem)","meaning":"the act or result of","meaningCN":"……的动作或结果","example":"The ending makes the verb into a name for a process.","exampleCN":"这个词尾把动词变成过程的名字。"},{"word":"encrypt","structure":"en- plus Greek kryptos","meaning":"to put into code","meaningCN":"把内容编成密码","example":"The verb is the base from which the noun is formed.","exampleCN":"动词是构成该名词的基础。"},{"word":"-ed","structure":"-ed (English participle ending)","meaning":"having been","meaningCN":"已经被……的","example":"An encrypted file has already gone through the steps.","exampleCN":"已加密的文件已经走完了这些步骤。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"Encrypting names the work while it is being done.","exampleCN":"encrypting 指正在进行的工作。"},{"word":"de-","structure":"de- (Latin prefix)","meaning":"undoing, reversal","meaningCN":"反向；解除","example":"The same root with de- names the way back.","exampleCN":"同一词根加 de- 指回去的路。"}],"latinEntries":[{"word":"crypta","structure":"crypta, cryptae (n., first declension)","meaning":"a covered passage or vault","meaningCN":"有顶的通道或拱室"}],"derivatives":[{"word":"encrypt","pos":"v.","zh":"加密"},{"word":"encrypted","pos":"adj.","zh":"加密的"},{"word":"decryption","pos":"n.","zh":"解密"},{"word":"cryptic","pos":"adj.","zh":"晦涩的；隐秘的"}]}},{"word":"encrypt","ipa_uk":"/ɪnˈkrɪpt/","ipa_us":"/ɪnˈkrɪpt/","definition_zh":"加密；把明文转换成只有持钥匙者才能读懂的密文","definition_en":"to convert readable information into a coded form that only the key holder can read","core_image":"一个人把摊开的信纸一行行卷进一只带锁的圆筒，纸上原本的字迹在筒口消失","scene":"值班员把摊在桌上的文件一行行扫进带锁的圆筒，筒口之外只剩乱码。The clerk used a short passphrase to encrypt every report before it left the office.","sceneCN":"这里 encrypt 指把明文转成密文的动作（第 1 个义项：对文本执行加密）；句意：职员用一句简短口令把每份报告都加密后才送出办公室。","pos":[{"tag":"v.","zh":"加密；把……编成密码"}],"collocations":[{"phrase":"encrypt a file","zh":"加密文件"},{"phrase":"encrypt data","zh":"加密数据"},{"phrase":"encrypt a message","zh":"加密消息"},{"phrase":"encrypt traffic","zh":"加密流量"},{"phrase":"encrypt with a key","zh":"用密钥加密"},{"phrase":"encrypt on the device","zh":"在设备上加密"}],"forms":[{"label":"第三人称单数","form":"encrypts"},{"label":"过去式","form":"encrypted"},{"label":"过去分词","form":"encrypted"},{"label":"现在分词","form":"encrypting"}],"derivatives":[{"word":"encryption","pos":"n.","zh":"加密"},{"word":"encrypted","pos":"adj.","zh":"加密的"},{"word":"encryptor","pos":"n.","zh":"加密装置（罕用）"}],"senses":[{"no":"01","title":"To turn text into code","titleCN":"把文本变成代码","definition":"to apply a fixed transformation that makes a message unreadable without the key","definitionCN":"用固定变换让消息在没有钥匙时无法读懂","example":"They encrypt the draft before it crosses the network.","exampleCN":"文件还在网络里穿行之前，他们就把它加密了。","why":"the verb is the direct action of the noun encryption; the object is whatever text is being changed.","whyCN":"这个动词就是名词 encryption 所指动作本身，宾语是被改变的任何文本。"},{"no":"02","title":"To hide a message from eavesdroppers","titleCN":"让窃听者读不到消息","definition":"to scramble a message so that an intercepting party gains nothing","definitionCN":"把消息打乱，使截获的一方什么也得不到","example":"A courier who cannot read the packet is the point of encrypting it.","exampleCN":"让送信人读不懂包裹，正是加密它的目的。","why":"the purpose of the action is built into the verb, so the verb is used even when the method is left unstated.","whyCN":"动作的目的已含在动词里，因此即使不说方法，人们也直接用这个动词。"},{"no":"03","title":"To protect stored files","titleCN":"给存档文件加保护","definition":"to encode files or a whole disk so that physical theft does not expose them","definitionCN":"对文件或整块磁盘编码，使实物被盗也不会泄露内容","example":"The team encrypts laptops before handing them to field staff.","exampleCN":"团队先给笔记本加密，再交给外勤人员。","why":"the same verb covers any data that must stay unreadable, whether it moves or rests.","whyCN":"同一个动词涵盖一切必须保持不可读的数据，无论它在传输还是静止。"},{"no":"04","title":"To secure a channel","titleCN":"给通信通道加密","definition":"to apply coding to traffic between two machines or two people","definitionCN":"对两台机器或两个人之间的流量施加编码","example":"The browser encrypts the session as soon as the handshake ends.","exampleCN":"握手一结束，浏览器就对这次会话加密。","why":"a connection is protected by protecting what runs through it, so the verb takes a channel as its object.","whyCN":"保护连接就是保护在其中流动的内容，因此动词可以接「通道」作宾语。"},{"no":"05","title":"To write in historical cipher","titleCN":"用历史密码书写","definition":"to write by hand with a substitution or transposition of letters","definitionCN":"用手工替换或换位字母的方式书写","example":"The envoys encrypted their dispatches with a shifting alphabet.","exampleCN":"使节们用一种移动字母表加密公文。","why":"the verb inherits the centuries-old craft before it inherits the machine.","whyCN":"这个动词先继承了数百年历史的手艺，之后才继承机器。"},{"no":"06","title":"To put a file in a sealed envelope","titleCN":"把文件封进数字信封","definition":"to make one particular item readable only to its intended receiver","definitionCN":"使某一份内容只对指定接收者可读","example":"She encrypts the attachment to a single colleague.","exampleCN":"她把附件加密，只允许一位同事打开。","why":"public-key methods let one item be sealed for one reader, and the old verb covers that everyday act.","whyCN":"公钥方法能让一份内容只对一个读者封存，旧动词便用来指这个日常动作。"},{"no":"07","title":"To meet a legal duty","titleCN":"履行合规要求的加密","definition":"to render personal or business data unreadable as a rule or regulation requires","definitionCN":"按规则或法规要求把个人或业务数据变得不可读","example":"Clinics must encrypt records they keep beyond the visit.","exampleCN":"诊所必须对就诊后仍保存的记录进行加密。","why":"when a law names an action, the verb of that action becomes a duty and gains a fixed administrative use.","whyCN":"当法规点名某个动作，这个动作的动词就成了义务，并获得固定的行政用法。"},{"no":"08","title":"To make speech needlessly obscure","titleCN":"把话故意说得晦涩","definition":"to express something in language so indirect that it works like a code","definitionCN":"用极其间接的语言表达，效果如同密码","example":"He encrypted a simple refusal inside three paragraphs of praise.","exampleCN":"他把一句简单的拒绝藏进三段赞美之中。","why":"unreadable-by-design writing is the shared image, so the verb stretches from ciphers to evasive prose.","whyCN":"「故意写得读不懂」是共同意象，于是动词从密码延伸到躲闪的文风。"}],"etymology":{"intro":{"en":"Encrypt is a modern English verb made by adding the prefix en- to the Greek root kryptos, hidden. It borrowed the shape of older French verbs but the meaning of a technical craft.","cn":"encrypt 是近代英语动词，在希腊词根 kryptos「隐藏」前加 en- 构成。它借用了古法语动词的形式，装进去的却是技术手艺的含义。"},"items":[{"era":"GREEK KRYPTOS","en":"Greek kryptos, hidden, came from kryptein, to hide. The root named anything covered or kept out of sight.","cn":"希腊语 kryptos「隐藏的」来自 kryptein「隐藏」。这个词根指任何被遮盖、被藏起来的东西。"},{"era":"LATIN CRYPTA","en":"Latin took crypta for a covered vault and used it for underground chambers, giving English the place word crypt.","cn":"拉丁语以 crypta 指有顶的拱室，多用于地下空间，并给英语留下了表示地窖的 crypt。"},{"era":"FRENCH VERB SHAPE","en":"Verbs beginning with en- were common in French, and English built new ones on that pattern rather than borrowing this verb whole.","cn":"法语中以 en- 开头的动词很常见，英语是按这个模式自造新词，而不是整体借入这个动词。"},{"era":"ENGLISH FORMATION","en":"The verb pairs en-, into, with the hidden root, so it says to put something into hiding. It is recorded in English only in the modern period.","cn":"这个动词把 en-「进入」与「隐藏」词根配在一起，意思是把某物放进隐藏状态。它在英语中的记载只见于近代。"},{"era":"SIGNALLING AND COMPUTING","en":"Military signalling gave the verb its technical sense, and computing made it an everyday word for protecting files and traffic.","cn":"军事通信给了它技术含义，计算机则让它成为保护文件与流量的日常词。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper pre-Greek origin of kryptein is not settled; compared forms are reconstructions, so no single ancestral root is claimed.","cn":"来源不确定：kryptein 在希腊语之前更早的来源没有定论，被比较的形式属于重构形式，因此不主张单一祖根。"}]},"similar":{"note":{"en":"The first group is the same hidden-root in its other parts of speech; the second group is the neighbouring technical actions.","cn":"第一组是「隐藏」词根的其他词性形式；第二组是相邻的技术动作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"encryption","ipa":"/ɪnˈkrɪpʃn/","tag":"the noun of the action","definition":"The process or the result; the verb names what a person does, the noun names what is done.","definitionCN":"指过程或结果；动词说人做了什么，名词说被做成了什么。"},{"word":"decrypt","ipa":"/diːˈkrɪpt/","tag":"the reverse verb","definition":"To turn the code back into readable text; it names the journey home, not the outward trip.","definitionCN":"把代码还原成可读文本；它指回程，而不是去程。"},{"word":"encrypted","ipa":"/ɪnˈkrɪptɪd/","tag":"participle and adjective","definition":"The state of having been put into code, as in an encrypted disk.","definitionCN":"指已经处于编码状态，如「已加密的磁盘」。"},{"word":"cryptic","ipa":"/ˈkrɪptɪk/","tag":"bare root, adjective","definition":"Puzzling by intention; no key is involved, only a manner of speaking.","definitionCN":"指故意让人费解；不涉及密钥，只是一种说话方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"encode","ipa":"/ɪnˈkəʊd/","tag":"conversion, no secrecy","definition":"To change form so that a system can store or send it; nothing is hidden, and anyone with the rule can read it.","definitionCN":"改变形式以便系统存储或发送；并不隐藏，懂规则的人都能读。"},{"word":"scramble","ipa":"/ˈskræmbl/","tag":"informal mixing","definition":"To mix something so its order is lost; it describes the visible effect, while encrypt names the deliberate method.","definitionCN":"把内容打乱到失去顺序；它描述可见的效果，encrypt 则指有意采用的方法。"},{"word":"cipher","ipa":"/ˈsaɪfə/","tag":"the rule, not the act","definition":"A system of symbol substitution; one ciphers a message by applying a cipher to it.","definitionCN":"符号替换的体系；人们把密码体系施于消息，从而加密消息。"},{"word":"conceal","ipa":"/kənˈsiːl/","tag":"general hiding","definition":"To keep something from being seen or known; the everyday word behind the technical one.","definitionCN":"使某物不被看见或知道；是技术词背后那个日常说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations built on the real pieces and the real verb family.","cn":"正常联想，建立在真实构件与真实动词词族之上。"},"normal":[{"en":"en- means into, kryptos means hidden: to encrypt is to put into hiding.","cn":"en- 表示「进入」，kryptos 表示「隐藏」：encrypt 就是把东西放进隐藏状态。"},{"en":"The four verb forms are regular: encrypts, encrypted, encrypted, encrypting.","cn":"四个动词形式都规则：encrypts、encrypted、encrypted、encrypting。"},{"en":"Objects tell the story: encrypt a file, a message, traffic, a disk.","cn":"看宾语就知道用法：加密文件、消息、流量、磁盘。"},{"en":"Pair it with its reverse: encrypt on the way out, decrypt on the way back.","cn":"与反义词成对记：出去时 encrypt，回来时 decrypt。"},{"en":"The preposition is with: encrypt with a key, never encrypt by a key.","cn":"介词用 with：encrypt with a key，而不是 encrypt by a key。"}],"abstract":[{"en":"Picture a hand pushing a written page into a cylinder and the page coming out as gravel.","cn":"想象一只手把写满字的纸推进圆筒，出来的却是一把碎石。"},{"en":"Picture a lock that changes its own shape every time the key turns.","cn":"想象一把锁，每次钥匙转动，锁孔就自己换一个形状。"},{"en":"Picture a whisper that only one ear in a crowded hall can decode.","cn":"想象满厅人群里的一句低语，只有一只耳朵能解出来。"}]},"examples":[{"en":"Banks encrypt customer records as a matter of routine.","cn":"银行把加密客户记录当作日常操作。"},{"en":"The app encrypts each photo before uploading it.","cn":"这款应用在上传前会把每张照片加密。"},{"en":"You can encrypt the whole drive without slowing daily work much.","cn":"你可以加密整个硬盘，而不太影响日常使用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因（en）刻入（crypt）」——把内容刻进去藏起来，就是加密","word":"encrypt"},"root":"希腊 kryptos「隐藏的」← kryptein「隐藏」→ 拉丁 crypta「拱室」→ 英语 crypt；英语以 en-「进入」+ 该词根构成动词 encrypt，近代才见于记载。","sensesIntro":{"en":"Eight senses run from the plain technical act to its protective purposes, then to the old craft, the sealed item, the legal duty and the evasive style.","cn":"八个义项从单纯的技术动作出发，走向各种保护目的，再到古老手艺、封存单品、法律义务与躲闪文风。"},"semanticMap":{"core":{"en":"CORE IMAGE: a written page rolled into a locked cylinder, its letters vanishing at the mouth.","cn":"核心意象：写满字的纸被卷进带锁的圆筒，字迹在筒口消失。"},"chain":["READABLE TEXT","FIXED TRANSFORMATION","UNREADABLE OUTPUT","SECRECY","KEY HOLDER","PROTECTED ITEM"],"branches":[{"senses":"01 · 08","en":"MAKING UNREADABLE: the plain act, and the figurative act of writing prose that hides its meaning.","cn":"使之不可读：既指本义动作，也指把文章写得意在藏意的比喻用法。"},{"senses":"02 · 06","en":"KEEPING FROM A READER: hiding a message from eavesdroppers, or sealing one item for one receiver.","cn":"对读者设限：既让窃听者读不到，也为单一接收者封存一份内容。"},{"senses":"03","en":"DATA AT REST: files and disks encoded so that theft of the object yields nothing.","cn":"静态数据：文件与磁盘被编码，实物被盗也得不到内容。"},{"senses":"04","en":"DATA IN MOTION: the same action applied to a live connection or session.","cn":"传输数据：同一动作施于正在运行的连接或会话。"},{"senses":"05 · 07","en":"OLD CRAFT AND NEW DUTY: hand ciphers on one side, a regulated obligation on the other.","cn":"旧手艺与新义务：一边是手工密码，一边是被规章规定的义务。"}]},"affixes":{"intro":{"en":"Encrypt is a prefix plus a Greek root with no Latin element in its core; the surrounding forms add English and Latin endings.","cn":"encrypt 是一个前缀加一个希腊词根，核心部分没有拉丁成分；周边形式再加英语与拉丁词尾。"},"latinIntro":{"en":"Latin contributes the prefix shape in- behind English en- and the noun ending -tion used by encryption; the root itself is Greek.","cn":"拉丁语提供了英语 en- 背后的 in- 前缀形式，以及 encryption 所用的名词词尾 -tion；词根本身来自希腊语。"},"items":[{"word":"en-","structure":"en- (English prefix)","meaning":"into, cause to be","meaningCN":"进入；使成为","example":"It moves the root from a state to an action.","exampleCN":"它把词根从状态变成动作。"},{"word":"in-","structure":"in- (Latin prefix)","meaning":"in, into","meaningCN":"在内；进入","example":"The Latin prefix is the older shape behind English en-.","exampleCN":"这个拉丁前缀是英语 en- 背后的更早形式。"},{"word":"kryptos","structure":"kryptos (Greek adjective)","meaning":"hidden","meaningCN":"隐藏的","example":"The adjective gives the family its core meaning.","exampleCN":"这个形容词给整个词族提供核心含义。"},{"word":"kryptein","structure":"kryptein (Greek verb)","meaning":"to hide","meaningCN":"隐藏","example":"The verb names the original act of covering.","exampleCN":"这个动词指最初的遮盖动作。"},{"word":"-ed","structure":"-ed (English participle ending)","meaning":"having been","meaningCN":"已经被……的","example":"An encrypted file is one that has been through the process.","exampleCN":"已加密的文件就是走完了流程的文件。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"Encrypting is the work, not the finished state.","exampleCN":"encrypting 指工作过程，不是完成状态。"},{"word":"-tion","structure":"-tion (Latin noun ending)","meaning":"action or result","meaningCN":"动作或结果","example":"The ending turns the verb into the name of a process.","exampleCN":"这个词尾把动词变成过程之名。"},{"word":"de-","structure":"de- (Latin prefix)","meaning":"reversal","meaningCN":"反向","example":"The prefix marks the journey back out of code.","exampleCN":"这个前缀标记从代码里出来的回程。"},{"word":"en- + -ed","structure":"en- prefix with English participle","meaning":"the finished state","meaningCN":"完成后的状态","example":"The two endings together describe a sealed item.","exampleCN":"两个词尾合起来描述一件已封存的内容。"}],"latinEntries":[{"word":"crypta","structure":"crypta, cryptae (n., first declension)","meaning":"covered vault, hidden chamber","meaningCN":"有顶的拱室、隐蔽的空间"}],"derivatives":[{"word":"encryption","pos":"n.","zh":"加密"},{"word":"encrypted","pos":"adj.","zh":"加密的"},{"word":"decrypt","pos":"v.","zh":"解密"},{"word":"cryptic","pos":"adj.","zh":"晦涩的"}]}},{"word":"decryption","ipa_uk":"/diːˈkrɪpʃn/","ipa_us":"/diːˈkrɪpʃən/","definition_zh":"解密；把密文还原为可读内容的过程","definition_en":"the process of turning coded information back into readable form","core_image":"一只带锁的圆筒被打开，卷在里面的信纸展开，原本的字迹一行行重新出现","scene":"档案馆里，管理员转动钥匙，屏幕上那团乱码渐渐还原成一封完整的旧信。With the right key, decryption restored the letter to plain words in a few seconds.","sceneCN":"这里 decryption 指把密文还原成可读内容的过程（第 1 个义项：还原这一动作）；句意：用对了钥匙，解密在几秒内就把那封信恢复成明白的话。","pos":[{"tag":"n.","zh":"解密；密文还原；解密过程"}],"collocations":[{"phrase":"decryption key","zh":"解密密钥"},{"phrase":"data decryption","zh":"数据解密"},{"phrase":"automatic decryption","zh":"自动解密"},{"phrase":"decryption process","zh":"解密过程"},{"phrase":"decryption algorithm","zh":"解密算法"},{"phrase":"fail at decryption","zh":"解密失败"}],"forms":[{"label":"复数","form":"decryptions"}],"derivatives":[{"word":"decrypt","pos":"v.","zh":"解密"},{"word":"decrypted","pos":"adj.","zh":"已解密的"},{"word":"decrypter","pos":"n.","zh":"解密装置（罕用）"}],"senses":[{"no":"01","title":"The act of restoring plain text","titleCN":"把密文还原成明文的动作","definition":"the act of applying the reversing procedure that turns code back into readable text","definitionCN":"执行逆向程序、把代码变回可读文本的动作","example":"Decryption happens inside the phone, not on the server.","exampleCN":"解密发生在手机内部，而不是服务器上。","why":"the noun names the action first, the way construction names both the act and the thing built.","whyCN":"这个名词首先指动作，正如 construction 同时指建造与建筑。"},{"no":"02","title":"The recovered message","titleCN":"还原出来的内容","definition":"the readable text produced once the code is undone","definitionCN":"代码被解除后得到的可读文本","example":"The decryption was a single line of ordinary invoice text.","exampleCN":"解密出来的内容只有一行普通的发票文字。","why":"the same action noun stands for its product, so one can hold the decryption in one's hand.","whyCN":"同一个动作名词也指其产物，所以可以说「拿到解密出来的内容」。"},{"no":"03","title":"The technical discipline","titleCN":"解密这一技术分支","definition":"the part of cryptography concerned with reversing transformations and proving they work","definitionCN":"密码学中负责逆转变换并验证其有效性的部分","example":"Their paper compares decryption costs across three schemes.","exampleCN":"他们的论文比较了三种方案下的解密开销。","why":"a repeated technical operation is studied as a subject, and the process noun becomes its name.","whyCN":"反复进行的技术操作会被当作学科研究，过程名词就成了它的名称。"},{"no":"04","title":"Authorised access to stored data","titleCN":"对存档数据的授权读取","definition":"the routine unfolding of protected files for a user who holds the key","definitionCN":"持钥匙的用户把受保护文件照常展开","example":"Decryption of the archive is logged every time an archivist opens it.","exampleCN":"档案员每次打开档案，解密操作都会被记录。","why":"protection at rest would be useless without a legal path back, and that path is named by this word.","whyCN":"静态保护若没有合法的回路就毫无意义，这个词就是那条回路的名称。"},{"no":"05","title":"Reading intercepted traffic","titleCN":"解读截获的通信","definition":"the successful restoration of a message that was captured in transit","definitionCN":"把传输中被截获的消息成功还原","example":"Their decryption of the signal exposed a planned shipment.","exampleCN":"他们对信号的解密暴露了一批计划中的货运。","why":"the word is neutral about who holds the key, so it also names the eavesdropper's success.","whyCN":"这个词对持钥匙者是谁保持中立，因此也指窃听者的成功。"},{"no":"06","title":"Historical reading of old ciphers","titleCN":"对历史密码的解读","definition":"the scholarly recovery of hand-written cipher text from the past","definitionCN":"学界对古代手写密文的还原","example":"The decryption of the royal letters took two scholars a decade.","exampleCN":"两位学者花了十年才解开那批王室信件。","why":"old documents still wait for keys, and historians use the modern noun for that labour.","whyCN":"旧文献仍在等钥匙，历史学者便用这个现代名词来称这项工作。"},{"no":"07","title":"The key mechanism in reverse","titleCN":"反向运转的密钥机制","definition":"the paired rule and secret value that allow the transformation to be undone","definitionCN":"使变换得以撤销的成对规则与秘密数值","example":"Symmetric decryption uses the same key that sealed the file.","exampleCN":"对称解密使用封存文件时的同一把钥匙。","why":"people name the machinery by its effect, so the reverse effect names the reverse machinery.","whyCN":"人们按效果命名机器，反向的效果就命名了反向的机器。"},{"no":"08","title":"Figurative clarification","titleCN":"比喻意义上的「解开」","definition":"the figurative act of making an obscure statement plain again","definitionCN":"把晦涩的说法重新讲明白的比喻用法","example":"Her footnote was a quiet decryption of the chairman's speech.","exampleCN":"她的脚注是对主席讲话的一次悄然解读。","why":"once code is undone, obscurity becomes sense, and any puzzling statement can borrow the image.","whyCN":"代码一旦解掉，晦涩就变回意义，任何难解的说法都能借用这个意象。"}],"etymology":{"intro":{"en":"Decryption is the mirror of encryption: the Latin prefix de-, meaning reversal, placed before the Greek hidden root and closed with the Latin action ending.","cn":"decryption 是 encryption 的镜像：拉丁前缀 de- 表示反向，放在希腊「隐藏」词根之前，再以拉丁动作词尾收束。"},"items":[{"era":"GREEK KRYPTOS","en":"Greek kryptos, hidden, and kryptein, to hide, supplied the root that all these words share.","cn":"希腊语 kryptos「隐藏的」与 kryptein「隐藏」提供了这一族词共享的词根。"},{"era":"LATIN CRYPTA","en":"Latin crypta named a covered vault, and its English descendant crypt still means an underground room.","cn":"拉丁语 crypta 指有顶的拱室，其英语后裔 crypt 至今仍指地下空间。"},{"era":"LATIN DE-","en":"Latin de- meant down from or away, and in verbs it came to mark undoing, so it is the natural prefix for opening what was closed.","cn":"拉丁语 de- 表示「向下、离开」，在动词中逐渐表示「撤销」，因此天然适合表示「把封上的东西打开」。"},{"era":"ENGLISH PAIR","en":"English built encrypt and then decrypt on the same root, so the two verbs stand as a matched pair of opposite actions.","cn":"英语在同一词根上先后造出 encrypt 与 decrypt，两个动词构成一对相反动作。"},{"era":"MODERN USE","en":"Twentieth-century signalling and computing fixed the noun decryption for the reverse operation, parallel to encryption.","cn":"二十世纪的通信与计算把名词 decryption 固定指反向操作，与 encryption 平行。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the earliest history of the Greek root is unsettled, and the forms sometimes compared with it are reconstructions.","cn":"来源不确定：这个希腊词根最早的历史没有定论，常被比较的形式属于重构形式。"}]},"similar":{"note":{"en":"The first group is the same root in its other shapes; the second group is the neighbouring ways of making something readable.","cn":"第一组是同一词根的其他形式；第二组是使内容变得可读的相邻说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decrypt","ipa":"/diːˈkrɪpt/","tag":"the verb","definition":"To carry out the reversal; the noun names the process or its result.","definitionCN":"指执行还原动作；名词指过程或其结果。"},{"word":"encryption","ipa":"/ɪnˈkrɪpʃn/","tag":"the opposite process","definition":"The outward journey into code; decryption is the homeward journey.","definitionCN":"指进入代码的去程；decryption 是回程。"},{"word":"decoded","ipa":"/diːˈkəʊdɪd/","tag":"result state","definition":"Having been converted back to a readable form, used of messages and signals.","definitionCN":"指已被还原成可读形式，多用于消息与信号。"},{"word":"cryptic","ipa":"/ˈkrɪptɪk/","tag":"bare root, adjective","definition":"Deliberately obscure in meaning, with no key involved.","definitionCN":"指故意晦涩难解，不涉及密钥。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decoding","ipa":"/diːˈkəʊdɪŋ/","tag":"conversion, no secrecy","definition":"Turning a representation back into ordinary form by a public rule; no secret key is needed.","definitionCN":"按公开规则把某种表示换回普通形式，不需要秘密密钥。"},{"word":"deciphering","ipa":"/dɪˈsaɪfərɪŋ/","tag":"solving an unknown code","definition":"Working out a cipher without being told the rule; decryption usually assumes the key is known.","definitionCN":"在不知规则的情况下破译密码；decryption 通常假定钥匙已知。"},{"word":"unlocking","ipa":"/ʌnˈlɒkɪŋ/","tag":"the physical image","definition":"Opening a lock; the everyday image behind the technical operation.","definitionCN":"打开锁；是这一技术操作背后的日常意象。"},{"word":"interpretation","ipa":"/ˌɪntəˈprɪteɪʃn/","tag":"meaning, not code","definition":"Explaining what a statement means; it works on ambiguity rather than on symbols.","definitionCN":"解释某句话的意思；处理的是歧义，而不是符号。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real prefix, the real pair and the real phrases.","cn":"正常联想：来自真实前缀、真实对立词与真实搭配。"},"normal":[{"en":"de- marks reversal, so decryption is encryption run backwards.","cn":"de- 表示反向，因此 decryption 就是倒着跑的 encryption。"},{"en":"The pair is fixed: encryption key to lock, decryption key to open.","cn":"这一对固定成套：加密密钥上锁，解密密钥开锁。"},{"en":"The verb is regular: decrypts, decrypted, decrypted, decrypting.","cn":"动词变化规则：decrypts、decrypted、decrypted、decrypting。"},{"en":"Fixed phrases: decryption key, decryption process, decryption algorithm.","cn":"固定搭配：解密密钥、解密过程、解密算法。"},{"en":"If the key is lost, decryption is impossible even with the file in hand.","cn":"钥匙一旦丢失，即使文件在手也无法解密。"}],"abstract":[{"en":"Picture a sealed cylinder opening and the page inside remembering how to be a page.","cn":"想象封住的圆筒打开，里面的纸想起自己该怎么当一张纸。"},{"en":"Picture gravel slowly reassembling into handwriting on a table.","cn":"想象桌上的碎石慢慢重组成手写的字迹。"},{"en":"Picture a door that only opens for the person who remembers the word it was built with.","cn":"想象一扇门，只为记得它被造出时那句话的人打开。"}]},"examples":[{"en":"Decryption of the backup took less than a minute.","cn":"备份的解密用了不到一分钟。"},{"en":"The service performs decryption on the user's own device.","cn":"这项服务在用户自己的设备上完成解密。"},{"en":"Without the second key, decryption of the archive remains out of reach.","cn":"没有第二把钥匙，档案的解密始终遥不可及。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「敌（de）刻入扑（cryption）」——把敌人刻进去的乱码扑开，就是解密","word":"decryption"},"root":"希腊 kryptos「隐藏的」→ 拉丁 crypta「拱室」→ 英语 crypt；加拉丁前缀 de-「反向」与 -tion 构成 decryption，与 encryption 构成一对相反过程。","sensesIntro":{"en":"Eight senses move from the plain reversal to its product, its discipline, its lawful use, its unlawful use, the historical craft, the key mechanism and the figurative reading.","cn":"八个义项从单纯的还原动作出发，走向产物、学科、合法用途、非授权用途、历史技艺、密钥机制与比喻性解读。"},"semanticMap":{"core":{"en":"CORE IMAGE: a locked cylinder opened, the page inside unfolding as its letters return.","cn":"核心意象：带锁的圆筒被打开，里面的纸展开，字迹重新回来。"},"chain":["CODED INPUT","REVERSING RULE","READABLE TEXT","AUTHORISED READER","RECOVERED MESSAGE","RESTORED MEANING"],"branches":[{"senses":"01 · 02","en":"ACT AND PRODUCT: the reversal performed, and the readable text it yields.","cn":"动作与产物：执行的还原动作，以及它产出的可读文本。"},{"senses":"03 · 07","en":"DISCIPLINE AND MECHANISM: the studied branch of cryptography, and the key rule that permits reversal.","cn":"学科与机制：被研究的密码学分支，以及允许逆转的密钥规则。"},{"senses":"04","en":"LAWFUL USE: daily opening of protected archives by the person who holds the key.","cn":"合法用途：持钥匙者日常打开受保护的档案。"},{"senses":"05 · 06","en":"OTHER HANDS: intercepted traffic read by an outsider, and old ciphers read by scholars.","cn":"他人之手：外人解读截获的通信，学者解读古代密码。"},{"senses":"08","en":"FIGURATIVE CLARITY: an obscure public statement made plain again.","cn":"比喻性的澄清：把晦涩的公开说法重新讲明白。"}]},"affixes":{"intro":{"en":"Decryption combines a Latin reversing prefix, a Greek hidden root and a Latin action ending, with English participles attached to the verb.","cn":"decryption 由拉丁反向前缀、希腊「隐藏」词根与拉丁动作词尾组合而成，动词另带英语分词词尾。"},"latinIntro":{"en":"Two Latin pieces are at work: de-, marking reversal, and -tion, marking an action noun; the root crypt- itself came to Latin from Greek.","cn":"这里有两个拉丁成分：de- 表示反向，-tion 表示动作名词；而 crypt- 词根本身是从希腊语进入拉丁语的。"},"items":[{"word":"de-","structure":"de- (Latin prefix)","meaning":"down from, away; undoing","meaningCN":"向下、离开；撤销","example":"The prefix turns the outward action into its reverse.","exampleCN":"这个前缀把向外的动作变成反向动作。"},{"word":"kryptos","structure":"kryptos (Greek adjective)","meaning":"hidden","meaningCN":"隐藏的","example":"The adjective is the shared core of the family.","exampleCN":"这个形容词是整个词族共享的核心。"},{"word":"kryptein","structure":"kryptein (Greek verb)","meaning":"to hide","meaningCN":"隐藏","example":"The verb names the covering act that the code performs.","exampleCN":"这个动词指代码所执行的遮盖动作。"},{"word":"crypta","structure":"crypta (Latin noun from Greek)","meaning":"covered vault","meaningCN":"有顶的拱室","example":"Latin passed the hidden-place image to English.","exampleCN":"拉丁语把「隐蔽之处」的意象传给英语。"},{"word":"-tion","structure":"-tion (Latin noun ending)","meaning":"action or result","meaningCN":"动作或结果","example":"The ending names the reversal as a process.","exampleCN":"这个词尾把还原动作命名为过程。"},{"word":"decrypt","structure":"de- plus Greek kryptos","meaning":"to undo the code","meaningCN":"解除代码","example":"The verb carries the action that the noun names.","exampleCN":"动词承载名词所指的动作。"},{"word":"-ed","structure":"-ed (English participle ending)","meaning":"having been","meaningCN":"已经被……的","example":"A decrypted file has already been opened.","exampleCN":"已解密的文件已经被打开了。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"Decrypting is the work in progress.","exampleCN":"decrypting 指正在进行的工作。"},{"word":"-er","structure":"-er (English agent ending)","meaning":"one who or that which does","meaningCN":"做……的人或物","example":"The ending marks a person or a device that performs it.","exampleCN":"这个词尾标记执行该动作的人或装置。"}],"latinEntries":[{"word":"crypta","structure":"crypta, cryptae (n., first declension)","meaning":"covered vault, hidden chamber","meaningCN":"有顶的拱室、隐蔽空间"}],"derivatives":[{"word":"decrypt","pos":"v.","zh":"解密"},{"word":"decrypted","pos":"adj.","zh":"已解密的"},{"word":"encryption","pos":"n.","zh":"加密"},{"word":"cryptic","pos":"adj.","zh":"晦涩的"}]}},{"word":"decrypt","ipa_uk":"/diːˈkrɪpt/","ipa_us":"/diːˈkrɪpt/","definition_zh":"解密；把密文还原成可读的文字","definition_en":"to turn coded information back into readable form","core_image":"一双手把卷紧的信纸从铁筒里抽出来，压平，字迹重新清晰","scene":"机房里，工程师把钥匙插进读卡器，屏幕上那串乱码一行行变回普通文字。The technician needed the second key to decrypt the archived report.","sceneCN":"这里 decrypt 指把密文还原成可读文字的动作（第 1 个义项：对密文执行还原）；句意：技术员需要第二把钥匙才能解密那份存档报告。","pos":[{"tag":"v.","zh":"解密；解读（密文）"}],"collocations":[{"phrase":"decrypt a file","zh":"解密文件"},{"phrase":"decrypt a message","zh":"解密消息"},{"phrase":"decrypt the data","zh":"解密数据"},{"phrase":"decrypt with a key","zh":"用密钥解密"},{"phrase":"decrypt the signal","zh":"解译信号"},{"phrase":"decrypt on the fly","zh":"即时解密"}],"forms":[{"label":"第三人称单数","form":"decrypts"},{"label":"过去式","form":"decrypted"},{"label":"过去分词","form":"decrypted"},{"label":"现在分词","form":"decrypting"}],"derivatives":[{"word":"decryption","pos":"n.","zh":"解密"},{"word":"decrypted","pos":"adj.","zh":"已解密的"},{"word":"decrypter","pos":"n.","zh":"解密程序（罕用）"}],"senses":[{"no":"01","title":"To restore plain text from code","titleCN":"把代码还原成明文","definition":"to reverse a coding procedure so that readable content appears again","definitionCN":"逆转编码程序，使可读内容重新出现","example":"The program can decrypt the record only when the key matches.","exampleCN":"只有钥匙匹配时，程序才能解密这条记录。","why":"the verb is the direct counterpart of encrypt, and de- marks the reversal from the start.","whyCN":"这个动词与 encrypt 直接相对，de- 从一开始就标记反向。"},{"no":"02","title":"To open an item for one reader","titleCN":"为指定读者打开一份内容","definition":"to make a sealed message readable for the person it was meant for","definitionCN":"使封存的消息对原定接收者变得可读","example":"Only her laptop can decrypt the weekly brief.","exampleCN":"只有她的笔记本能解开每周简报。","why":"sealing is pointless without a permitted opener, so the verb names that permitted act.","whyCN":"封存若没有获准的开启者就毫无意义，因此动词也指这个获准的动作。"},{"no":"03","title":"To read protected stored data","titleCN":"读取受保护的存档数据","definition":"to unfold encrypted files or a disk for normal work","definitionCN":"把加密的文件或磁盘展开以便正常工作","example":"The system decrypts the drive at startup, not at shutdown.","exampleCN":"系统在启动时解密硬盘，而不是在关机时。","why":"the everyday counterpart of disk encryption is simply the same verb on the way back.","whyCN":"磁盘加密的日常对立面，就是同一动词的回程用法。"},{"no":"04","title":"To read intercepted traffic","titleCN":"解读截获的通信","definition":"to succeed in reading a message that was captured without permission","definitionCN":"成功读懂在未获许可情况下截获的消息","example":"They could not decrypt the burst of the new radio.","exampleCN":"他们无法解译那台新电台发出的突发信号。","why":"the verb says nothing about permission, so it covers both the lawful and the unlawful opener.","whyCN":"这个动词对许可与否不加限定，因此既指合法也指非法的开启者。"},{"no":"05","title":"To solve an old cipher","titleCN":"破解古代密码","definition":"to work out the meaning of a hand-written message whose rule was lost","definitionCN":"弄明白一份规则已失传的手写消息","example":"Historians decrypted the merchant's ledger after finding his notebook.","exampleCN":"历史学家找到商人的笔记本后破解了他的账册。","why":"old writings are still called encrypted, so their recovery keeps the same simple verb.","whyCN":"旧文献仍被称为加密文本，因此它们的还原沿用同一个简单动词。"},{"no":"06","title":"To decode a technical signal","titleCN":"解译技术信号","definition":"to convert a scrambled transmission into its original instructions or data","definitionCN":"把被打乱的传输内容还原成原始指令或数据","example":"The receiver decrypts the frame before passing it upward.","exampleCN":"接收端先解译数据帧，再向上层传递。","why":"a link that encrypts in hardware must decrypt in hardware, and the verb follows the signal.","whyCN":"在硬件里加密的链路也必须在硬件里解密，动词随信号走。"},{"no":"07","title":"To meet a compliance requirement","titleCN":"满足合规要求的解密","definition":"to reverse protection in a logged, authorised way for audit or legal access","definitionCN":"为审计或合法调取，以留痕、获授权的方式解除保护","example":"The auditor asked the firm to decrypt three years of invoices.","exampleCN":"审计人要求公司解密三年的发票记录。","why":"rules about access turn the action into a duty with a documented procedure.","whyCN":"关于调取的规则把这一动作变成有记录程序的义务。"},{"no":"08","title":"To make an obscure statement clear","titleCN":"把晦涩的话讲明白","definition":"to work out what someone meant by evasive or heavily coded language","definitionCN":"弄懂躲闪或高度编码式语言到底在说什么","example":"A good editor can decrypt a paragraph of official vagueness.","exampleCN":"好编辑能把一段官样含糊话读明白。","why":"undoing code and undoing obscurity are the same mental move, so the verb stretches into style.","whyCN":"解代码与解晦涩是同一个思维动作，因此动词延伸到文风领域。"}],"etymology":{"intro":{"en":"Decrypt is encrypt with a reversing prefix. The Latin de- carries the sense of undoing, and the Greek root still carries the sense of hiding.","cn":"decrypt 就是在 encrypt 前加反向前缀。拉丁 de- 带来「撤销」的含义，希腊词根仍带「隐藏」的含义。"},"items":[{"era":"GREEK KRYPTOS","en":"Greek kryptos, hidden, gave the family its root; the idea is concealment rather than secrecy of state.","cn":"希腊语 kryptos「隐藏的」给这一族提供词根；核心是「藏」而不是「机密」。"},{"era":"LATIN CRYPTA","en":"Latin crypta, a covered vault, carried the root into European learned vocabulary, and English crypt preserves the place sense.","cn":"拉丁语 crypta 指有顶的拱室，把这个词根带入欧洲学术词汇；英语 crypt 保留了空间义。"},{"era":"LATIN DE-","en":"The prefix de- marked movement down or away and, in verbs, undoing; it is the regular Latin way to say the opposite of an action.","cn":"前缀 de- 表示向下或离开，在动词中表示撤销；这是拉丁语表达动作相反面的常规方式。"},{"era":"ENGLISH FORMATION","en":"English formed decrypt on the model of encrypt, so the pair share a root and differ only in the prefix.","cn":"英语仿照 encrypt 造出 decrypt，两者同根，只在前缀上不同。"},{"era":"MODERN USE","en":"Signalling and computing made the pair routine: one side encrypts, the other decrypts, and neither word needs a longer phrase.","cn":"通信与计算让这一对成为常规：一方加密，另一方解密，两个词都不需要更长的说法。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the pre-Greek history of the root is not established; the older forms cited in handbooks are reconstructions.","cn":"来源不确定：该词根在希腊语之前的历史尚无定论；手册中引用的更古形式属于重构形式。"}]},"similar":{"note":{"en":"The first group is the same root in other shapes; the second group is what people actually do to make code readable.","cn":"第一组是同一词根的其他形式；第二组是人们把代码变可读时实际使用的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decryption","ipa":"/diːˈkrɪpʃn/","tag":"the noun","definition":"The process or its result; the verb names the doing.","definitionCN":"指过程或其结果；动词指做的动作。"},{"word":"encrypt","ipa":"/ɪnˈkrɪpt/","tag":"the opposite verb","definition":"To put text into code; decrypt takes it out again.","definitionCN":"把文本编成代码；decrypt 再把它取出来。"},{"word":"decrypted","ipa":"/diːˈkrɪptɪd/","tag":"participle and adjective","definition":"The state of having been restored, as in a decrypted copy.","definitionCN":"指已还原的状态，如「已解密的副本」。"},{"word":"cryptic","ipa":"/ˈkrɪptɪk/","tag":"bare root, adjective","definition":"Obscure on purpose; it describes the style that decryption removes.","definitionCN":"指故意晦涩；描述的是解密要去掉的那种风格。"}]},{"heading":"NEAR MEANING","entries":[{"word":"decode","ipa":"/diːˈkəʊd/","tag":"public rule","definition":"To convert a representation back by a published rule; no secret key is involved.","definitionCN":"按公开规则把某种表示换回；不涉及秘密密钥。"},{"word":"decipher","ipa":"/dɪˈsaɪfə/","tag":"finding the rule","definition":"To work out an unknown cipher; it stresses discovery, where decrypt usually implies a known key.","definitionCN":"破解未知密码；它强调「发现规则」，而 decrypt 通常意味着钥匙已知。"},{"word":"unlock","ipa":"/ʌnˈlɒk/","tag":"physical image","definition":"To open a lock with a key; the plain image behind the technical verb.","definitionCN":"用钥匙开锁；是技术动词背后的朴素意象。"},{"word":"crack","ipa":"/kræk/","tag":"breaking protection","definition":"To break a system by force or cleverness; decrypt merely uses the permitted key.","definitionCN":"用暴力或巧思攻破系统；decrypt 只是使用获准的钥匙。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the genuine prefix and the genuine pair.","cn":"正常联想：来自真实前缀与真实对立词。"},"normal":[{"en":"de- undoes what en- did: encrypt on the way out, decrypt on the way back.","cn":"de- 撤销 en- 做的事：出去时 encrypt，回来时 decrypt。"},{"en":"The four forms are regular: decrypts, decrypted, decrypted, decrypting.","cn":"四个形式都规则：decrypts、decrypted、decrypted、decrypting。"},{"en":"The object is the same as for its twin: a file, a message, a signal.","cn":"宾语与它的孪生词相同：文件、消息、信号。"},{"en":"The phrase is with a key, not by a key.","cn":"搭配是 with a key，不是 by a key。"},{"en":"Decrypt comes after encryption in time, never before it.","cn":"解密在时间上总在加密之后，绝不会在前。"}],"abstract":[{"en":"Picture a page pulled out of a locked cylinder and flattened, its creases fading as it opens.","cn":"想象一张纸从带锁的圆筒里被抽出、摊平，折痕在展开中消失。"},{"en":"Picture gravel on a table slowly remembering the shape of letters.","cn":"想象桌上的碎石慢慢想起字母的形状。"},{"en":"Picture a door that stays shut until someone pronounces the sentence written on its frame.","cn":"想象一扇门，直到有人念出门框上写的那句话才打开。"}]},"examples":[{"en":"The tool can decrypt the backup in a single pass.","cn":"这个工具一遍就能解密备份。"},{"en":"Only the intended reader can decrypt the short note.","cn":"只有原定读者才能解开这张便条。"},{"en":"They spent the winter trying to decrypt the admiral's letters.","cn":"他们用整个冬天试图破解那位将军的信件。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「低（de）刻入扑（crypt）」——把刻意藏进去的东西低身扒开，就是解密","word":"decrypt"},"root":"希腊 kryptos「隐藏的」→ 拉丁 crypta「拱室」→ 英语 crypt；英语以拉丁 de-「反向」+ 该词根构成 decrypt，与 encrypt 配成一对相反动作。","sensesIntro":{"en":"Eight senses move from the plain reversal through permitted and unpermitted openings, the old cipher, the technical signal, the audit duty and the style of plainness.","cn":"八个义项从单纯的还原出发，经过获准与未获准的开启、古代密码、技术信号、审计义务，最后到讲明白的文风。"},"semanticMap":{"core":{"en":"CORE IMAGE: a page drawn out of a locked cylinder and pressed flat until the letters return.","cn":"核心意象：纸从带锁的圆筒里抽出、压平，字迹重新回来。"},"chain":["CODED INPUT","REVERSING PREFIX","RESTORED TEXT","READER","READING RESULT","CLEAR MEANING"],"branches":[{"senses":"01 · 02","en":"REVERSAL AND ACCESS: undoing the code in general, and opening one item for its intended reader.","cn":"还原与准入：泛指解除代码，也指为原定读者打开单份内容。"},{"senses":"03","en":"AT-REST USE: unfolding a protected disk so ordinary work can continue.","cn":"静态使用：展开受保护的硬盘，让日常工作继续。"},{"senses":"04 · 06","en":"IN TRANSIT: reading captured messages, and converting a scrambled frame back to data.","cn":"传输之中：读懂截获的消息，以及把打乱的帧还原成数据。"},{"senses":"05","en":"HISTORICAL RECOVERY: old hand ciphers whose rule was lost.","cn":"历史还原：规则已经失传的古代手工密码。"},{"senses":"07 · 08","en":"DUTY AND STYLE: a documented legal access on one side, making an evasive statement plain on the other.","cn":"义务与文风：一边是有记录的法律调取，一边是把躲闪的说法讲明白。"}]},"affixes":{"intro":{"en":"Decrypt is a Latin reversing prefix on a Greek hidden root; its noun and participles add Latin and English endings.","cn":"decrypt 是拉丁反向前缀加希腊「隐藏」词根；其名词与分词再加拉丁和英语词尾。"},"latinIntro":{"en":"The Latin parts are de- for reversal and -tion in the noun; crypt- reaches Latin from Greek as crypta.","cn":"拉丁成分是表示反向的 de- 与名词中的 -tion；crypt- 以 crypta 的形式从希腊语进入拉丁语。"},"items":[{"word":"de-","structure":"de- (Latin prefix)","meaning":"undoing, reversal","meaningCN":"撤销；反向","example":"It marks the return journey from code to text.","exampleCN":"它标记从代码回到文本的回程。"},{"word":"in-","structure":"in- (Latin prefix)","meaning":"into","meaningCN":"进入","example":"The opposite prefix shows what de- undoes.","exampleCN":"对立前缀展示了 de- 所撤销的内容。"},{"word":"kryptos","structure":"kryptos (Greek adjective)","meaning":"hidden","meaningCN":"隐藏的","example":"The adjective carries the family meaning.","exampleCN":"这个形容词承载词族的核心含义。"},{"word":"kryptein","structure":"kryptein (Greek verb)","meaning":"to hide","meaningCN":"隐藏","example":"The verb is the original act that code imitates.","exampleCN":"这个动词是代码所模仿的原始动作。"},{"word":"crypta","structure":"crypta (Latin noun)","meaning":"covered vault","meaningCN":"有顶的拱室","example":"The Latin noun kept the concrete hidden-place sense.","exampleCN":"这个拉丁名词保留了具体的「隐蔽之处」义。"},{"word":"-tion","structure":"-tion (Latin noun ending)","meaning":"action or result","meaningCN":"动作或结果","example":"The ending makes the reversal a named process.","exampleCN":"这个词尾把反向动作变成有名目的过程。"},{"word":"-ed","structure":"-ed (English participle ending)","meaning":"having been","meaningCN":"已经被……的","example":"A decrypted copy is no longer protected.","exampleCN":"已解密的副本不再受保护。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"Decrypting runs while the reader waits.","exampleCN":"decrypting 在读者等待时进行。"},{"word":"-er","structure":"-er (English agent ending)","meaning":"one that performs","meaningCN":"执行动作的装置","example":"The ending names a device or program that does the work.","exampleCN":"这个词尾指执行该工作的装置或程序。"}],"latinEntries":[{"word":"crypta","structure":"crypta, cryptae (n., first declension)","meaning":"covered vault, hidden chamber","meaningCN":"有顶的拱室、隐蔽空间"}],"derivatives":[{"word":"decryption","pos":"n.","zh":"解密"},{"word":"decrypted","pos":"adj.","zh":"已解密的"},{"word":"encrypt","pos":"v.","zh":"加密"},{"word":"cryptic","pos":"adj.","zh":"晦涩的"}]}},{"word":"privacy","ipa_uk":"/ˈprɪvəsi/","ipa_us":"/ˈprɪvəsi/","definition_zh":"隐私；不受他人打扰的状态，以及对个人信息的控制权","definition_en":"the state of being free from public attention or disturbance, and the control a person has over personal information","core_image":"一间只亮着一盏灯的屋子，窗帘拉严，门外的人只能看见布上的影子，却进不来","scene":"深夜的屋子里只亮着一盏台灯，窗帘拉得很严，门外的人只能看见布上的影子。She drew the curtain because privacy mattered more to her than the view.","sceneCN":"这里 privacy 指不受他人注视与打扰的状态（第 1 个义项：独处不受扰）；句意：她拉上窗帘，因为对她来说，不被打扰比窗外的景色更重要。","pos":[{"tag":"n.","zh":"隐私；私生活；独处不受扰；信息控制权"}],"collocations":[{"phrase":"personal privacy","zh":"个人隐私"},{"phrase":"data privacy","zh":"数据隐私"},{"phrase":"privacy policy","zh":"隐私政策"},{"phrase":"invade privacy","zh":"侵犯隐私"},{"phrase":"privacy settings","zh":"隐私设置"},{"phrase":"right to privacy","zh":"隐私权"},{"phrase":"protect privacy","zh":"保护隐私"}],"forms":[{"label":"复数","form":"privacies"}],"derivatives":[{"word":"private","pos":"adj.","zh":"私人的；私下的"},{"word":"privately","pos":"adv.","zh":"私下地"},{"word":"privacy-conscious","pos":"adj.","zh":"注重隐私的"}],"senses":[{"no":"01","title":"Freedom from being disturbed","titleCN":"独处而不受打扰","definition":"the condition of being alone and free from other people's interruption","definitionCN":"独处且不被他人打断的状态","example":"He reads in the garden for an hour of privacy each morning.","exampleCN":"他每天早上在花园里读一小时书，享受不被打扰的时光。","why":"the Latin adjective described something withdrawn from public life, and withdrawal begins as simple freedom from company.","whyCN":"这个拉丁形容词指从公共生活中退开，而退开最初就是免于他人陪伴。"},{"no":"02","title":"Freedom from public attention","titleCN":"不受公众注视","definition":"the state of not being watched, reported on or discussed by the public","definitionCN":"不被公众注视、报道或议论的状态","example":"The family moved inland to raise the children in privacy.","exampleCN":"这家人搬到内陆，想在不受注视的环境里抚养孩子。","why":"publicity is the opposite pole, and the word names the absence of it rather than the presence of walls.","whyCN":"「公开」是对立的一端，这个词指公开的缺席，而不是墙的存在。"},{"no":"03","title":"Control over one's own information","titleCN":"对本人信息的控制","definition":"a person's power to decide who learns what about them","definitionCN":"个人决定谁能知道自己哪些情况的权力","example":"Privacy means the choice to tell, not the duty to hide.","exampleCN":"隐私意味着「可以选择说」，而不是「必须藏」。","why":"once information could be copied and shared at scale, withdrawal became a matter of control rather than of distance.","whyCN":"当信息能被大规模复制与共享，退开就从「隔开距离」变成了「掌握控制权」。"},{"no":"04","title":"Data privacy as a field of practice","titleCN":"数据隐私这一实务领域","definition":"the handling of personal data by organisations under rules of collection, use and deletion","definitionCN":"机构按收集、使用与删除规则处理个人数据","example":"The company hired a lawyer to lead its data privacy work.","exampleCN":"公司聘请了一位律师主管数据隐私工作。","why":"a social value is turned into a managed operation, and its name follows the operation.","whyCN":"一项社会价值被转化为可管理的业务，其名称便随业务走。"},{"no":"05","title":"The legal right to seclusion","titleCN":"法律上的隐私权","definition":"the recognised claim that others may not intrude into one's personal sphere","definitionCN":"被承认的、他人不得侵入个人领域的主张","example":"The court treated privacy as a limit on how evidence may be gathered.","exampleCN":"法院把隐私视为取证方式的一条界限。","why":"a value argued in courts becomes a right, and the abstract noun carries that legal weight.","whyCN":"在法庭上被论证的价值会变成一项权利，这个抽象名词便承担了法律分量。"},{"no":"06","title":"Settings that limit visibility","titleCN":"限制可见范围的设置","definition":"the options in an app or account that decide who can see what","definitionCN":"应用或账号中决定谁能看到什么的选择项","example":"She changed her privacy so that only friends could see the album.","exampleCN":"她改动了隐私设置，只有好友能看到那本相册。","why":"when exposure is governed by menus, the value word is used for the switches themselves.","whyCN":"当曝光由菜单控制时，这个价值名词就被用来指那些开关。"},{"no":"07","title":"Confidentiality of a matter","titleCN":"某件事的保密性","definition":"the quality of a discussion or document that stays within a trusted circle","definitionCN":"谈话或文件只留在可信圈子内的性质","example":"They asked for privacy during the settlement talks.","exampleCN":"他们要求和解谈判过程保持保密。","why":"a thing kept from outsiders is private in the old sense, and the abstract noun covers that condition.","whyCN":"不让外人知道的事在旧义上就是「私下的」，抽象名词涵盖这种状态。"},{"no":"08","title":"Physical seclusion of a place","titleCN":"空间上的遮蔽与清静","definition":"the shielding of a room or home from view, sound or entry","definitionCN":"房间或住宅在视线、声音与进入上受到的遮蔽","example":"The hedge gives the terrace a little privacy from the road.","exampleCN":"那道树篱让露台与马路之间有了一点遮蔽。","why":"walls, hedges and curtains are the oldest tools of withdrawal, so the word attaches to physical shelter.","whyCN":"墙、树篱与窗帘是「退开」最古老的工具，因此这个词也依附于实体的遮蔽。"},{"no":"09","title":"Protection against surveillance","titleCN":"对抗监控的隐私","definition":"the expectation that states and companies will not track a person without cause","definitionCN":"国家对个人的追踪需有正当理由这一期待","example":"Cameras on every corner turned privacy into a public argument.","exampleCN":"街角的摄像头把隐私变成了公共议题。","why":"the word sharpens when watching becomes cheap, because the old freedom now needs defending.","whyCN":"当「观看」变得廉价，这个词就变得尖锐，因为旧的自由如今需要辩护。"},{"no":"10","title":"Personal space in shared settings","titleCN":"共享场所中的个人空间","definition":"the informal room a person keeps around themselves among others","definitionCN":"在他人之间为自己留出的非正式余地","example":"Open desks leave almost no privacy for a phone call.","exampleCN":"开放式工位几乎不给人打电话的私人余地。","why":"the word stretches from legal seclusion to the small distance people maintain in a crowd.","whyCN":"这个词从法律的清静延伸到人群中人们维持的那点距离。"}],"etymology":{"intro":{"en":"Privacy comes from Latin privatus, withdrawn from public office and belonging to oneself. The abstract ending -acy names a state, so the word names a condition rather than a thing.","cn":"privacy 来自拉丁语 privatus，指「退出公职、属于个人」。抽象词尾 -acy 表示状态，因此这个词指一种处境，而不是一件东西。"},"items":[{"era":"LATIN PRIVUS","en":"Latin privus meant single, each for itself, and the derived verb privare meant to set apart or deprive.","cn":"拉丁语 privus 意为「单个的、各自的」，派生动词 privare 意为「分开、剥夺」。"},{"era":"LATIN PRIVATUS","en":"Privatus described a person withdrawn from public office, a private citizen as opposed to a magistrate.","cn":"privatus 描述退出公职的人，即与官员相对的普通公民。"},{"era":"FRENCH PRIVE","en":"French privé carried the sense of personal or secluded, and English borrowed the adjective as private.","cn":"法语 privé 带有「个人的、僻静的」之意，英语借入形容词 private。"},{"era":"ENGLISH -ACY","en":"The ending -acy, from Latin -acia, turns an adjective into the name of a state, so privacy is the state of being private.","cn":"词尾 -acy 来自拉丁 -acia，把形容词变成状态之名，因此 privacy 就是「处于私人状态」。"},{"era":"MODERN DATA USE","en":"In the twentieth century the word moved from seclusion to information, as records became easy to copy and share.","cn":"二十世纪，随着记录变得易于复制与共享，这个词从「清静」转向「信息」。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the link between privus and the wider family of Latin separating words is debated, and the deeper forms are reconstructions.","cn":"来源不确定：privus 与拉丁语中其他表示「分开」的词是否同源仍有争论，更古的形式属于重构形式。"}]},"similar":{"note":{"en":"The first group is built on the same private root; the second group is the neighbouring ideas of secrecy, solitude and protection.","cn":"第一组建立在同一个「私人」词根上；第二组是保密、独处与保护这些相邻概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"private","ipa":"/ˈpraɪvət/","tag":"the adjective","definition":"Belonging to a person rather than the public; a private room is the place where privacy is possible.","definitionCN":"属于个人而非公众；private 的房间就是能有 privacy 的地方。"},{"word":"privately","ipa":"/ˈpraɪvətli/","tag":"the adverb","definition":"In a way that avoids public view; it describes how something is done, not the state itself.","definitionCN":"以避开公众视线的方式；它描述做事方式，而不是状态本身。"},{"word":"deprive","ipa":"/dɪˈpraɪv/","tag":"same Latin root, different branch","definition":"To take something away from someone; it comes from the same Latin verb of setting apart but means loss, not seclusion.","definitionCN":"把某物从某人处拿走；出自同一个表示「分开」的拉丁动词，但指失去，不是清静。"},{"word":"privilege","ipa":"/ˈprɪvəlɪdʒ/","tag":"same Latin root, different branch","definition":"A special right granted to a person or group; the root idea of a private law applied to one party survives here.","definitionCN":"授予个人或群体的特殊权利；这里保留的是「针对一方的私人法规」这一词根含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"secrecy","ipa":"/ˈsiːkrəsi/","tag":"hidden content","definition":"The keeping of information from others; privacy protects a person's sphere, secrecy hides a fact.","definitionCN":"把信息瞒住；privacy 保护个人领域，secrecy 隐藏某个事实。"},{"word":"solitude","ipa":"/ˈsɒlɪtjuːd/","tag":"being alone","definition":"The state of being alone, often chosen for calm; privacy can be enjoyed in company by being left undisturbed.","definitionCN":"独处的状态，常为求安宁而选择；privacy 也可以在人群中通过不被打扰而获得。"},{"word":"confidentiality","ipa":"/kənˌfɪdenʃiˈæləti/","tag":"professional duty","definition":"The obligation not to pass on information given in trust; it is a duty, while privacy is a condition or right.","definitionCN":"不转述受托信息的义务；它是义务，而 privacy 是状态或权利。"},{"word":"anonymity","ipa":"/ˌænəˈnɪməti/","tag":"namelessness","definition":"The state of not being identified; privacy may keep a known person unobserved, anonymity removes the name itself.","definitionCN":"不被识别的状态；privacy 可让已知的人不被注视，anonymity 则连名字都去掉。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real Latin root and the real legal and technical phrases.","cn":"正常联想：来自真实拉丁词根与真实的法律、技术搭配。"},"normal":[{"en":"The adjective is private and the state is privacy: the ending -acy names a condition.","cn":"形容词是 private，状态名词是 privacy：词尾 -acy 表示状态。"},{"en":"The old sense is a private citizen withdrawn from office, not a secret kept from a friend.","cn":"旧义是退出公职的普通公民，而不是对朋友隐瞒的秘密。"},{"en":"Fixed phrases run from law to software: right to privacy, privacy policy, privacy settings.","cn":"固定搭配从法律延伸到软件：隐私权、隐私政策、隐私设置。"},{"en":"The verb is invade or protect: privacy is something done to, not something done.","cn":"动词是 invade 或 protect：privacy 是被对待的对象，而不是动作。"},{"en":"Data privacy is the modern centre of gravity of the word.","cn":"数据隐私是这个词现代的重心所在。"}],"abstract":[{"en":"Picture a lit room whose curtain lets light out but keeps eyes out.","cn":"想象一间亮灯的屋子，窗帘把光放出去，却把目光挡在外面。"},{"en":"Picture a door with no handle on the outside and no lock on the inside.","cn":"想象一扇门，外面没有把手，里面没有锁。"},{"en":"Picture a name written in water and read only by the person who wrote it.","cn":"想象一个写在水上的名字，只有写下它的人读得到。"}]},"examples":[{"en":"Privacy is not secrecy; it is the power to decide what is shared.","cn":"隐私不是保密，而是决定分享什么的权力。"},{"en":"The new rules give patients more privacy over their records.","cn":"新规让患者对自己的病历拥有更多隐私掌控。"},{"en":"A thin wall gave the neighbours almost no privacy.","cn":"一堵薄墙几乎没给邻居留下任何私人空间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「扑来（pri）为谁（vacy）」——扑过来想知道「为谁」，正是要守住隐私","word":"privacy"},"root":"拉丁 privus「单个的、各自的」→ privare「分开、剥夺」→ privatus「退出公职的私人」→ 法语 privé → 英语 private；加 -acy（拉丁 -acia）表状态构成 privacy。","sensesIntro":{"en":"Ten senses start from being left alone, pass through public attention, information control, professional handling, legal right, app settings, confidentiality and physical shelter, and end at surveillance and shared space.","cn":"十个义项从「不被打扰」出发，经过公众注视、信息控制、行业实务、法律权利、应用设置、保密与实体遮蔽，最后落在监控与共享空间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lit room sealed by a curtain, visible as a glow from outside but not open to eyes.","cn":"核心意象：一间亮灯的屋子被窗帘封住，外面只看见光，却看不进去。"},"chain":["WITHDRAWAL","BEING ALONE","SHIELD FROM VIEW","CONTROL OF INFORMATION","LEGAL CLAIM","PROTECTED SPHERE"],"branches":[{"senses":"01 · 08","en":"QUIET AND SHELTER: being undisturbed, and the walls or hedges that make it possible.","cn":"清静与遮蔽：不被打扰，以及使之成为可能的墙与树篱。"},{"senses":"02 · 09","en":"PUBLICITY AND WATCHING: the absence of public notice, and the defence of that absence against surveillance.","cn":"公开与注视：不受公众关注，以及针对监控为这种缺席辩护。"},{"senses":"03","en":"INFORMATION CONTROL: deciding who may know what about oneself.","cn":"信息控制：决定谁能知道自己哪些情况。"},{"senses":"04 · 06","en":"ROUTINE AND SETTINGS: organisational data handling, and the switches that govern visibility.","cn":"实务与设置：机构的数据处理，以及控制可见性的开关。"},{"senses":"05 · 07 · 10","en":"RIGHT, CONFIDENCE, SPACE: a legal claim, a confidential circle, and the small room kept in a crowd.","cn":"权利、信任与空间：法律主张、可信圈子，以及在人群中留出的余地。"}]},"affixes":{"intro":{"en":"Privacy is a Latin adjective turned into a state noun by the ending -acy; English later built private and privately from the same base.","cn":"privacy 是拉丁形容词加 -acy 构成的状态名词；英语后来又从同一词基造出 private 与 privately。"},"latinIntro":{"en":"The Latin base is privus, single or separate, with privatus as its adjective of withdrawal; -acia supplied the abstract ending.","cn":"拉丁词基是 privus「单个的、分开的」，其形容词 privatus 表示退出；抽象词尾来自 -acia。"},"items":[{"word":"privus","structure":"privus (Latin adjective)","meaning":"single, each for itself","meaningCN":"单个的；各自分开的","example":"The adjective begins the idea of what belongs to one person.","exampleCN":"这个形容词开启了「属于一个人」的观念。"},{"word":"privare","structure":"privare (Latin verb)","meaning":"to set apart, to deprive","meaningCN":"分开；剥夺","example":"The verb supplies both the sense of separation and of loss.","exampleCN":"这个动词同时提供「分开」与「失去」两层含义。"},{"word":"privatus","structure":"privatus (Latin adjective)","meaning":"withdrawn from public office","meaningCN":"退出公职的","example":"The adjective describes a private citizen rather than a magistrate.","exampleCN":"这个形容词描述普通公民而非官员。"},{"word":"-acy","structure":"-acy (English ending from Latin -acia)","meaning":"state or quality","meaningCN":"状态或性质","example":"The ending turns the adjective into the name of a condition.","exampleCN":"这个词尾把形容词变成状态之名。"},{"word":"private","structure":"privatus through French privé","meaning":"personal, not public","meaningCN":"个人的；非公开的","example":"Private is the adjective behind the state noun.","exampleCN":"private 是状态名词背后的形容词。"},{"word":"-ly","structure":"-ly (English adverb ending)","meaning":"in that manner","meaningCN":"以那种方式","example":"The adverb describes the manner of doing something.","exampleCN":"这个副词描述做某事的方式。"},{"word":"de-","structure":"de- (Latin prefix) in deprive","meaning":"away, removal","meaningCN":"离开；去除","example":"The prefixed verb names loss rather than seclusion.","exampleCN":"带前缀的动词指失去，而不是清静。"},{"word":"privi-","structure":"privi- (bound Latin base in privilege)","meaning":"private, set apart for one","meaningCN":"私人的；为一方特设的","example":"The same base appears in a word for a special right.","exampleCN":"同一词基也出现在表示特殊权利的词中。"},{"word":"-lege","structure":"-lege (Latin lex, law, in privilege)","meaning":"law","meaningCN":"法律","example":"The second element ties the word to a private law.","exampleCN":"第二个构件把这个词与「私人法规」联系起来。"}],"latinEntries":[{"word":"privatus","structure":"privatus, privata, privatum (adj., first and second declension)","meaning":"private, withdrawn from public office","meaningCN":"私人的；退出公职的"},{"word":"privare","structure":"privare, privavi, privatum (v., first conjugation)","meaning":"to set apart, to deprive","meaningCN":"分开；剥夺"}],"derivatives":[{"word":"private","pos":"adj.","zh":"私人的"},{"word":"privately","pos":"adv.","zh":"私下地"},{"word":"deprive","pos":"v.","zh":"剥夺"},{"word":"privilege","pos":"n.","zh":"特权"}]}},{"word":"database management","ipa_uk":"/ˌdeɪtəbeɪs məˈnædʒmənt/","ipa_us":"/ˈdeɪtəbeɪs məˈnædʒmənt/","definition_zh":"数据库管理；对数据库进行建立、维护、控制与保障的一整套工作","definition_en":"the work of building, maintaining, controlling and protecting a database and the data inside it","core_image":"一间档案室里，成排的抽屉贴着编号标签，管理员拿着登记簿核对每一份进出的卷宗","scene":"档案室里成排的抽屉都贴着编号，管理员拿着登记簿核对每一份进出的卷宗。Good database management kept the clinic's patient records accurate for twenty years.","sceneCN":"这里 database management 指对数据库进行建立、维护与控制的一整套工作（第 1 个义项：日常管理工作）；句意：良好的数据库管理让这家诊所的病人记录二十年保持准确。","pos":[{"tag":"n.","zh":"数据库管理；数据库管理工作；数据库管理系统（作定语）"}],"collocations":[{"phrase":"database management system","zh":"数据库管理系统"},{"phrase":"database management software","zh":"数据库管理软件"},{"phrase":"database management course","zh":"数据库管理课程"},{"phrase":"efficient database management","zh":"高效的数据库管理"},{"phrase":"database management tasks","zh":"数据库管理任务"},{"phrase":"database management team","zh":"数据库管理团队"}],"forms":[{"label":"复合名词","form":"database management"},{"label":"复数（作可数用法时）","form":"database managements"}],"derivatives":[{"word":"database","pos":"n.","zh":"数据库"},{"word":"manage","pos":"v.","zh":"管理；经营"},{"word":"management","pos":"n.","zh":"管理；管理层"},{"word":"manager","pos":"n.","zh":"管理者"}],"senses":[{"no":"01","title":"The routine work of keeping a database healthy","titleCN":"维持数据库正常运转的日常工作","definition":"the day-to-day work of loading, checking, updating and repairing a database","definitionCN":"对数据库进行装载、检查、更新与修复的日常工作","example":"Database management here means nightly checks, not a new product.","exampleCN":"这里的数据库管理指的是每晚的检查，而不是一款新产品。","why":"the compound names an activity, so it first means the work people do rather than the tool they use.","whyCN":"这个复合词指一项活动，因此首先表示人做的工作，而不是人用的工具。"},{"no":"02","title":"The software system that runs a database","titleCN":"运行数据库的软件系统","definition":"the program layer that stores, queries and controls access to data","definitionCN":"负责存储、查询与控制数据访问的程序层","example":"The vendor sells database management to hospitals and banks.","exampleCN":"这家厂商把数据库管理系统卖给医院和银行。","why":"the phrase is shortened from the longer name of the system, and the activity noun came to stand for the software that performs it.","whyCN":"这个短语由系统全称缩略而来，动作名词转而指执行该动作的软件。"},{"no":"03","title":"The organisational function","titleCN":"组织内的职能与岗位","definition":"the team and role responsible for data holdings inside an organisation","definitionCN":"组织内部负责数据资产团队与岗位","example":"Database management sits between the application team and the network team.","exampleCN":"数据库管理处在应用团队与网络团队之间。","why":"a repeated technical duty becomes a permanent office, and the duty's name becomes the office's name.","whyCN":"反复出现的技术职责会固定成一个常设岗位，职责之名就成了岗位之名。"},{"no":"04","title":"Control of access and quality","titleCN":"对访问权限与数据质量的控制","definition":"the setting of permissions, standards and rules for who may read or change data","definitionCN":"为谁可读取或修改数据设定权限、标准与规则","example":"Database management decides which clerk may see the billing table.","exampleCN":"数据库管理决定哪位职员可以查看计费表。","why":"a database holds other people's facts, so administration naturally grows into governance.","whyCN":"数据库装着别人的事实，因此「管理」自然长成「治理」。"},{"no":"05","title":"Performance and capacity work","titleCN":"性能与容量方面的工作","definition":"the tuning of queries, indexes and storage so that a system stays fast as it grows","definitionCN":"调整查询、索引与存储，使系统在增长中保持速度","example":"Slow reports were solved by better database management, not new hardware.","exampleCN":"报告变慢是靠更好的数据库管理解决的，而不是靠新硬件。","why":"the practical core of the job is keeping response time acceptable, and that core is named by the compound.","whyCN":"这项工作最实际的核心是让响应时间可接受，复合词就指这个核心。"},{"no":"06","title":"Backup and recovery responsibility","titleCN":"备份与恢复的责任","definition":"the practice of copying data and restoring it after failure","definitionCN":"复制数据并在故障后恢复的做法","example":"Database management proved its worth the night the disk failed.","exampleCN":"磁盘坏掉的那一夜，数据库管理证明了它的价值。","why":"the value of administration is clearest after a loss, and the phrase covers that duty too.","whyCN":"管理的价值在损失之后最清楚，这个短语也涵盖这项责任。"},{"no":"07","title":"A course or subject of study","titleCN":"一门课程或学科","definition":"the taught subject covering data models, query languages and administration","definitionCN":"讲授数据模型、查询语言与管理实务的课程","example":"The evening course in database management filled in two days.","exampleCN":"那门数据库管理晚间课程两天就报满了。","why":"a skill taught in classrooms becomes a subject title, and the activity phrase serves as the title.","whyCN":"在课堂上讲授的技能会变成课程名，活动短语就成了课程名。"},{"no":"08","title":"A product or market category","titleCN":"产品与市场类别","definition":"the commercial class of tools sold for organising and protecting data","definitionCN":"为组织与保护数据而出售的那一类商业工具","example":"Analysts rank database management among the steadier software markets.","exampleCN":"分析人士把数据库管理列为较稳定的软件市场之一。","why":"an activity that everyone needs becomes a shelf in the market, named after the activity.","whyCN":"人人需要的活动会变成市场上的一个货架，并以活动本身命名。"}],"etymology":{"intro":{"en":"Database management is a twentieth-century compound of three older pieces: Latin data, Greek basis through Latin, and Italian handling through French. Each part kept its own history.","cn":"database management 是二十世纪的三段式复合词：拉丁语 data、经拉丁语转手的希腊语 basis，以及经法语进入英语的意大利语「操作」。每一段都保留了自己的来历。"},"items":[{"era":"LATIN DATUM","en":"Latin datum means something given, the neuter participle of dare, to give. Its plural data entered English as a mass of facts.","cn":"拉丁语 datum 意为「被给予的东西」，是 dare「给予」的中性分词。其复数 data 进入英语，指一批事实。"},{"era":"GREEK BASIS","en":"Greek basis meant a step or a pedestal, and Latin basis kept that sense of a supporting bottom before English used it for a foundation of any kind.","cn":"希腊语 basis 指台阶或基座，拉丁语 basis 保留了「支撑的底部」之意，后来英语用它指任何基础。"},{"era":"ITALIAN MANEGGIARE","en":"Italian maneggiare meant to handle or train horses, from mano, hand. French took it as manage and English borrowed the French verb.","cn":"意大利语 maneggiare 意为「操作、驯马」，来自 mano「手」。法语借入为 manage，英语又借入这个法语动词。"},{"era":"ENGLISH DATABASE","en":"English joined data and base in the mid-twentieth century to name a structured store of records held for machine processing.","cn":"英语在二十世纪中叶把 data 与 base 拼合，指为机器处理而保存的结构化记录集合。"},{"era":"ENGLISH MANAGEMENT","en":"Management first meant the handling of a household or an estate, then the running of an enterprise, and only later the care of a technical system.","cn":"management 原指料理家务或田产，后来指经营企业，再后来才指照管技术系统。"},{"era":"MODERN COMPOUND","en":"The full phrase settled once databases became large enough to need a specialist, and it now names both the work and the software that supports it.","cn":"当数据库大到需要专职人员时，这个完整短语才固定下来，如今既指这项工作，也指支持它的软件。"}]},"similar":{"note":{"en":"The first group shares the words inside the compound; the second group names neighbouring kinds of information work.","cn":"第一组共享复合词内部的几个词；第二组是相邻的信息工作类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"database","ipa":"/ˈdeɪtəbeɪs/","tag":"the object being managed","definition":"The organised store itself; management is the work done on it and the system that runs it.","definitionCN":"指被组织起来的存储本身；management 是对它做的工作以及运行它的系统。"},{"word":"management","ipa":"/məˈnædʒmənt/","tag":"the second element alone","definition":"The running of people or operations in general; joined to database it loses its staff sense.","definitionCN":"泛指对人或者业务的经营；与 database 组合后不再指人员层面的管理。"},{"word":"data management","ipa":"/ˈdeɪtə məˈnædʒmənt/","tag":"wider scope","definition":"The broader discipline covering all data, not only what sits inside one database.","definitionCN":"范围更大的学科，涵盖全部数据，而不只是某个数据库里的内容。"},{"word":"database administrator","ipa":"/ˈdeɪtəbeɪs ədˈmɪnɪstrətə/","tag":"the person","definition":"The role that carries out the work; the phrase database management names the work itself.","definitionCN":"指承担这项工作的岗位；database management 指工作本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"data governance","ipa":"/ˈdeɪtə ˈɡʌvənəns/","tag":"rules and accountability","definition":"The policy side: who owns data, what may be done with it and who answers for mistakes.","definitionCN":"偏政策的一面：数据归谁所有、可以怎么用、出错谁负责。"},{"word":"data administration","ipa":"/ˈdeɪtə ˌædmɪnɪˈstreɪʃn/","tag":"close overlap","definition":"An older term for the same control work, often used when the emphasis is on records and standards rather than software.","definitionCN":"指同一类管控工作的旧称，多用于强调记录与规范，而非软件。"},{"word":"information management","ipa":"/ˌɪnfəˈmeɪʃn məˈnædʒmənt/","tag":"whole organisation","definition":"The management of all information resources, of which a database is one technical part.","definitionCN":"对全部信息资产的管理，数据库只是其中一个技术部分。"},{"word":"records management","ipa":"/ˈrekɔːdz məˈnædʒmənt/","tag":"documents and retention","definition":"The control of documents through their life cycle, including retention and disposal.","definitionCN":"按生命周期管理文件，包括保存期限与销毁。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the three real parts and the real technical phrases.","cn":"正常联想：来自三个真实构件与真实技术搭配。"},"normal":[{"en":"Data is the Latin plural of datum, something given; a database is a structured gift of facts.","cn":"data 是 datum「被给予之物」的拉丁复数；database 就是被整理好的事实。"},{"en":"Basis meant a pedestal, so a database is a set of records with a base under it.","cn":"basis 原指基座，所以 database 是一批底下有基座的记录。"},{"en":"Manage came from handling horses by hand, and the word still carries the sense of steady control.","cn":"manage 来自用手照看马匹，至今仍带「稳稳掌控」的意思。"},{"en":"The phrase names work and software: database management tasks, database management system.","cn":"这个短语既指工作也指软件：数据库管理任务、数据库管理系统。"},{"en":"Three duties anchor it: access control, performance, recovery.","cn":"三项职责锚定它：访问控制、性能、恢复。"}],"abstract":[{"en":"Picture a cabinet whose drawers rearrange themselves when someone searches too slowly.","cn":"想象一个柜子，当有人查找太慢时，抽屉会自己重新排列。"},{"en":"Picture a ledger that refuses to open for a reader who has not signed the register.","cn":"想象一本账簿，没在登记簿上签名的人打不开它。"},{"en":"Picture a copy of every page kept in another room, waiting for the day the first room burns.","cn":"想象每一页的副本都放在另一间屋里，等着第一间屋烧掉的那天。"}]},"examples":[{"en":"Good database management is mostly boring, which is exactly the point.","cn":"好的数据库管理大部分时候很枯燥，而这正是它的意义。"},{"en":"The firm outsourced database management but kept control of the data.","cn":"公司把数据库管理外包，但数据控制权仍握在自己手里。"},{"en":"She took a course in database management before joining the audit team.","cn":"她加入审计团队之前修了一门数据库管理课程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「得他（data）被子（base）满街（manage）门特」——给成堆数据盖上被子、管好门，就是数据库管理","word":"database management"},"root":"拉丁 datum「被给予之物」→ data；希腊 basis「基座」→ 拉丁 basis → base；意大利 maneggiare「用手操作」→ 法语 manage → 英语 management；二十世纪中叶拼成 database，再加 management 成复合词。","sensesIntro":{"en":"Eight senses cover the daily work, the software layer, the organisational role, governance, performance, recovery, teaching and the market.","cn":"八个义项涵盖日常工作、软件层、组织职能、治理、性能、恢复、教学与市场。"},"semanticMap":{"core":{"en":"CORE IMAGE: rows of labelled drawers in an archive, with a clerk checking every file in and out against a register.","cn":"核心意象：档案室成排贴标签的抽屉，管理员按登记簿核对每份卷宗的进出。"},"chain":["STORED RECORDS","STRUCTURE","ROUTINE CARE","ACCESS CONTROL","INTEGRITY","RELIABLE SERVICE"],"branches":[{"senses":"01 · 05","en":"DAILY CARE: routine upkeep on one side, tuning for speed and growth on the other.","cn":"日常照管：一边是例行维护，一边是为速度与增长做调优。"},{"senses":"02 · 08","en":"SYSTEM AND MARKET: the software that performs the work, and the commercial class it is sold in.","cn":"系统与市场：执行工作的软件，以及它所在的商业类别。"},{"senses":"03 · 07","en":"ROLE AND SUBJECT: a permanent office inside an organisation, and a taught course outside it.","cn":"岗位与课程：组织内的常设职位，以及组织外讲授的课程。"},{"senses":"04","en":"GOVERNANCE: permissions, standards and the rules about who may read or change data.","cn":"治理：权限、标准，以及谁可读取或改动数据的规则。"},{"senses":"06","en":"RECOVERY: copies kept against failure, the duty that proves the work was worth doing.","cn":"恢复：为故障而保存副本，这项职责证明工作值得做。"}]},"affixes":{"intro":{"en":"The compound has no prefix or suffix of its own; it is held together by two Latin-based nouns and one Italian-based one.","cn":"这个复合词本身没有前后缀，而是由两个拉丁来源名词与一个意大利来源名词拼合而成。"},"latinIntro":{"en":"Latin gives datum and basis; Italian gives maneggiare, which French shaped into manage before English took it.","cn":"拉丁语提供 datum 与 basis；意大利语提供 maneggiare，法语把它塑造成 manage，英语再借入。"},"items":[{"word":"datum","structure":"datum, dati (n., second declension)","meaning":"something given","meaningCN":"被给予的东西","example":"The noun supplies the first half of the compound.","exampleCN":"这个名词提供复合词的前半部分。"},{"word":"data","structure":"plural of datum used as a mass noun","meaning":"facts or records","meaningCN":"事实或记录","example":"English treats the plural as a body of facts.","exampleCN":"英语把这个复数当作一批事实来用。"},{"word":"basis","structure":"basis (Greek) through Latin basis","meaning":"a pedestal, a foundation","meaningCN":"基座；基础","example":"The second half supplies the idea of a supporting structure.","exampleCN":"后半部分提供「支撑结构」的意思。"},{"word":"manus","structure":"manus (Latin noun)","meaning":"hand","meaningCN":"手","example":"The hand is the image inside the Italian verb of handling.","exampleCN":"「手」是意大利语「操作」动词里的意象。"},{"word":"maneggiare","structure":"maneggiare (Italian verb)","meaning":"to handle, to train a horse","meaningCN":"操作；驯马","example":"The verb reached English through French.","exampleCN":"这个动词经法语进入英语。"},{"word":"manage","structure":"manage (English verb from French)","meaning":"to run, to control","meaningCN":"经营；掌控","example":"The verb is the base of the second noun.","exampleCN":"这个动词是第二个名词的词基。"},{"word":"-ment","structure":"-ment (Latin-derived noun ending through French)","meaning":"the act or result of","meaningCN":"……的动作或结果","example":"The ending turns manage into a name for the work.","exampleCN":"这个词尾把 manage 变成工作的名称。"},{"word":"database","structure":"data plus base","meaning":"an organised store of records","meaningCN":"有组织的记录集合","example":"The first two pieces were joined in the twentieth century.","exampleCN":"前两个构件在二十世纪被拼在一起。"},{"word":"database management","structure":"database plus management","meaning":"the care of such a store","meaningCN":"对这类存储的照管","example":"The full compound adds the work to the object.","exampleCN":"完整复合词在对象之后加上工作本身。"}],"latinEntries":[{"word":"datum","structure":"datum, dati (n., second declension)","meaning":"a thing given","meaningCN":"被给予之物"},{"word":"basis","structure":"basis, basis (n., third declension, from Greek)","meaning":"a pedestal, a base","meaningCN":"基座；基础"}],"derivatives":[{"word":"database","pos":"n.","zh":"数据库"},{"word":"manage","pos":"v.","zh":"管理"},{"word":"manager","pos":"n.","zh":"管理者"},{"word":"managerial","pos":"adj.","zh":"管理上的"}]}},{"word":"interface design","ipa_uk":"/ɪnˈtəfeɪs dɪˈzaɪn/","ipa_us":"/ˈɪntərfeɪs dɪˈzaɪn/","definition_zh":"界面设计；设计人与设备或程序之间交互方式的工作","definition_en":"the work of shaping how a person meets and operates a device, program or system","core_image":"一台机器的面板上，按钮的大小、顺序与标注被反复调整，直到陌生人不看说明也能按对","scene":"工作台上摊着几张手绘的面板草图，按钮被反复挪动位置，旁边的测试者皱起眉头又松开。Good interface design lets a first-time user finish the task without reading the manual.","sceneCN":"这里 interface design 指设计人与设备之间交互方式的工作（第 1 个义项：界面设计这项工作）；句意：好的界面设计让第一次使用的人不看说明书就能完成任务。","pos":[{"tag":"n.","zh":"界面设计；交互界面设计（作定语）"}],"collocations":[{"phrase":"user interface design","zh":"用户界面设计"},{"phrase":"interface design principles","zh":"界面设计原则"},{"phrase":"interface design tools","zh":"界面设计工具"},{"phrase":"interface design course","zh":"界面设计课程"},{"phrase":"clean interface design","zh":"简洁的界面设计"},{"phrase":"interface design team","zh":"界面设计团队"}],"forms":[{"label":"复合名词","form":"interface design"},{"label":"复数（作可数用法时）","form":"interface designs"}],"derivatives":[{"word":"interface","pos":"n.","zh":"界面；接口"},{"word":"design","pos":"n./v.","zh":"设计"},{"word":"designer","pos":"n.","zh":"设计师"},{"word":"designing","pos":"n.","zh":"设计工作"}],"senses":[{"no":"01","title":"The craft of shaping an interaction","titleCN":"塑造交互方式的这门手艺","definition":"the practice of deciding how a person will meet, understand and operate a system","definitionCN":"决定人如何接触、理解并操作一套系统的实践","example":"Interface design asks what the user is trying to do before asking what looks good.","exampleCN":"界面设计先问用户想做什么，再问什么好看。","why":"a compound of an object and an activity names the activity, so the phrase first denotes the craft.","whyCN":"「对象＋活动」的复合词指活动本身，因此这个短语首先指这门手艺。"},{"no":"02","title":"The visual arrangement of a screen","titleCN":"屏幕上的视觉排布","definition":"the layout of controls, text and space on a display","definitionCN":"显示屏上控件、文字与空白的排布","example":"The interface design puts the search box where the eye lands first.","exampleCN":"这次界面设计把搜索框放在视线最先落到的位置。","why":"users meet a screen before they meet a method, so the phrase often means the arrangement they see.","whyCN":"用户先遇到屏幕，再遇到方法，因此这个短语常指他们看得见的排布。"},{"no":"03","title":"A phase of a product project","titleCN":"产品项目中的一个阶段","definition":"the stage between requirements and build when interaction is settled","definitionCN":"需求与开发之间、确定交互方式的阶段","example":"Interface design comes before the code freeze, not after it.","exampleCN":"界面设计在代码冻结之前，而不是之后。","why":"work that must be finished at a fixed point becomes a named phase of the schedule.","whyCN":"必须在固定节点完成的工作，会变成进度表上有了名字的阶段。"},{"no":"04","title":"A branch of human-computer interaction","titleCN":"人机交互中的一个分支","definition":"the research and teaching area that studies how people and machines meet","definitionCN":"研究人与机器如何相遇的研究与教学领域","example":"Her doctorate is in interface design, not in graphic art.","exampleCN":"她的博士方向是界面设计，而不是平面艺术。","why":"a craft with its own methods and evidence becomes a discipline with its own name.","whyCN":"有了自己的方法与证据的手艺，会变成有名目的学科。"},{"no":"05","title":"Design of physical controls","titleCN":"实体控制面板的设计","definition":"the arrangement of buttons, dials and labels on a machine or panel","definitionCN":"机器或面板上按钮、旋钮与标注的布置","example":"Interface design for a lift panel must work for a hand in gloves.","exampleCN":"电梯面板的界面设计必须让戴手套的手也能操作。","why":"the screen is recent, but the problem of a panel a stranger must read is old.","whyCN":"屏幕是晚近的东西，但「陌生人必须读懂的面板」这个问题很古老。"},{"no":"06","title":"Design of a programmatic interface","titleCN":"程序调用接口的设计","definition":"the shaping of functions, names and data that one program offers another","definitionCN":"一个程序向另一个程序提供的函数、命名与数据的塑造","example":"Interface design for the library matters as much as its speed.","exampleCN":"这个库的接口设计与其速度同样重要。","why":"the word interface also names the seam between programs, and design applies there without any pixels.","whyCN":"interface 也指程序之间的接缝，在那里做设计并不涉及任何像素。"},{"no":"07","title":"The usability craft behind a flow","titleCN":"支撑一条任务流程的可用性工艺","definition":"the work of ordering steps so a task can be finished with few errors","definitionCN":"安排步骤顺序，使任务能以很少的错误完成","example":"Checkout interface design cut abandoned carts by a third.","exampleCN":"结账流程的界面设计让放弃购物车的人少了三分之一。","why":"the measure of the craft is whether people finish, so the phrase also names the work aimed at that measure.","whyCN":"这门手艺的衡量标准是人能否完成，因此短语也指为达成该标准所做的工作。"},{"no":"08","title":"The finished design as an artifact","titleCN":"作为成果的界面设计方案","definition":"the document or file that specifies the final arrangement","definitionCN":"规定最终排布的文件或图样","example":"The engineers built exactly the interface design she handed over.","exampleCN":"工程师完全照她交出的界面设计方案实现。","why":"an activity noun routinely stands for its product, and a design handed over is such a product.","whyCN":"活动名词常指其产物，交付出去的设计图就是这样的产物。"}],"etymology":{"intro":{"en":"Interface design joins a Latin preposition, a Latin word for shape, and a Latin verb for marking out. Both halves passed through French before English used them together.","cn":"interface design 由一个拉丁介词、一个表示「形状」的拉丁词和一个表示「标画」的拉丁动词组成。两部分都经法语转手，英语才把它们合起来用。"},"items":[{"era":"LATIN INTER","en":"Latin inter meant between or among, and English kept that sense in the prefix of interface.","cn":"拉丁语 inter 意为「在……之间」，英语在 interface 的前缀里保留了这个意思。"},{"era":"LATIN FACIES","en":"Latin facies meant form, appearance or outward look, and English face still carries both the bodily and the surface sense.","cn":"拉丁语 facies 意为「形状、外观」，英语 face 至今兼有「脸」与「表面」两层意思。"},{"era":"ENGLISH INTERFACE","en":"Interface first named a boundary surface where two bodies meet, and only later the meeting point between a person and a machine.","cn":"interface 最初指两个物体相接的边界面，后来才指人与机器相遇的地方。"},{"era":"LATIN DESIGNARE","en":"Designare meant to mark out or trace, from signum, a mark; English design kept the sense of a plan marked down before it is made.","cn":"designare 意为「标画、描出」，来自 signum「标记」；英语 design 保留了「先画好再做」的意思。"},{"era":"FRENCH PASSAGE","en":"Both interface and design entered English through French forms, which is why their spelling and stress differ from the Latin originals.","cn":"interface 与 design 都经法语形式进入英语，所以拼写与重音都与拉丁原词不同。"},{"era":"MODERN COMPOUND","en":"The full phrase became common with computing, when the seam between person and machine became something a specialist had to plan.","cn":"随着计算机普及，人与机器之间的接缝需要专人规划，这个完整短语才流行起来。"}]},"similar":{"note":{"en":"The first group shares the words inside the compound; the second group is the neighbouring design and research fields.","cn":"第一组共享复合词内部的词；第二组是相邻的设计与研究领域。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"interface","ipa":"/ɪnˈtəfeɪs/","tag":"the thing designed","definition":"The meeting surface itself; the compound adds the work of deciding its shape.","definitionCN":"指相接的界面本身；复合词加上「决定其形态」的工作。"},{"word":"user interface","ipa":"/ˈjuːzə ɪnˈtəfeɪs/","tag":"the human side","definition":"The part a person actually sees and touches, as opposed to interfaces between programs.","definitionCN":"人实际看见并触碰的部分，与程序之间的接口相对。"},{"word":"design","ipa":"/dɪˈzaɪn/","tag":"the second element alone","definition":"The general activity of planning a form; joined to interface it narrows to human interaction.","definitionCN":"泛指规划形态的活动；与 interface 组合后收窄为人机交互。"},{"word":"designer","ipa":"/dɪˈzaɪnə/","tag":"the person","definition":"The one who does the work; the phrase names the work, not the worker.","definitionCN":"指做这项工作的人；短语指工作，而不是人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"interaction design","ipa":"/ˌɪntərˈækʃn dɪˈzaɪn/","tag":"behaviour over layout","definition":"The design of behaviour and response over time; interface design often concentrates on the surface that carries it.","definitionCN":"设计随时间变化的行为与反馈；interface design 常更专注于承载它的表面。"},{"word":"usability","ipa":"/juːˈzæbɪləti/","tag":"the measured quality","definition":"How easily a task is completed; it is the test of interface design rather than the designing itself.","definitionCN":"任务完成的容易程度；它是界面设计的检验标准，而不是设计本身。"},{"word":"layout","ipa":"/ˈleɪaʊt/","tag":"arrangement only","definition":"The placement of elements on a surface; layout is one outcome of interface design, not the whole craft.","definitionCN":"元素在表面上的摆放；layout 只是界面设计的一个结果，不是全部。"},{"word":"human-computer interaction","ipa":"/ˌhjuːmən kəmˈpjuːtə ˌɪntərˈækʃn/","tag":"the research field","definition":"The academic study of people and machines; interface design is its applied craft.","definitionCN":"研究人与机器的学科；interface design 是它的应用手艺。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real Latin pieces and the real professional phrases.","cn":"正常联想：来自真实拉丁构件与真实行业搭配。"},"normal":[{"en":"Inter means between and face means surface, so an interface is the surface between two parties.","cn":"inter 表示「之间」，face 表示「表面」，interface 就是两方之间的表面。"},{"en":"Design comes from marking out: the designer draws before the builder builds.","cn":"design 来自「标画」：设计者先画，建造者再造。"},{"en":"Fixed phrases: user interface design, interface design principles, interface design tools.","cn":"固定搭配：用户界面设计、界面设计原则、界面设计工具。"},{"en":"The test is behavioural: can a stranger finish without the manual.","cn":"检验标准是行为上的：陌生人能否不看说明书就完成。"},{"en":"The phrase has no pixels in its second sense: an interface between two programs is also designed.","cn":"这个短语的另一义与像素无关：两个程序之间的接口同样需要设计。"}],"abstract":[{"en":"Picture a doorknob that tells your hand which way to turn before your eyes read anything.","cn":"想象一个门把手，在你眼睛读到任何字之前，就先告诉你的手该往哪边转。"},{"en":"Picture a panel whose labels fade as soon as a stranger stops needing them.","cn":"想象一块面板，陌生人一不需要说明，标注就自动淡去。"},{"en":"Picture a seam between two rooms that has been made wide enough to walk through without noticing.","cn":"想象两间屋子之间的接缝被做得足够宽，走过去时根本察觉不到。"}]},"examples":[{"en":"Interface design fails quietly when a button looks like decoration.","cn":"当按钮看起来像装饰时，界面设计就悄悄失败了。"},{"en":"They rewrote the interface design after watching five users hesitate.","cn":"看过五位用户犹豫之后，他们重写了界面设计。"},{"en":"Interface design for the control room had to survive cold hands and loud noise.","cn":"控制室的界面设计必须经得起手冷和噪声。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因特（inter）费事（face）第一赛（design）」——人与机器之间那层费事的表面，要第一赛着设计","word":"interface design"},"root":"拉丁 inter「之间」+ facies「形状、外观」→ 英语 interface；拉丁 designare「标画」← signum「标记」→ 法语 → 英语 design；两词在计算机时代合成 interface design。","sensesIntro":{"en":"Eight senses run from the craft to the screen layout, the project phase, the research branch, physical panels, program interfaces, the usability work and the delivered plan.","cn":"八个义项从手艺出发，走向屏幕排布、项目阶段、研究分支、实体面板、程序接口、可用性工作与交付的方案。"},"semanticMap":{"core":{"en":"CORE IMAGE: a machine panel redrawn again and again until a stranger presses the right button without instructions.","cn":"核心意象：机器面板被反复重画，直到陌生人不必看说明就能按对按钮。"},"chain":["PERSON AND SYSTEM","MEETING SURFACE","ARRANGEMENT","BEHAVIOUR","TEST WITH USERS","FINISHED PLAN"],"branches":[{"senses":"01 · 07","en":"CRAFT AND USABILITY: the practice of shaping the meeting, and the work of ordering steps so tasks finish.","cn":"手艺与可用性：塑造相遇方式的实践，以及安排步骤使任务完成的工作。"},{"senses":"02 · 05","en":"VISIBLE SURFACES: a screen layout, and the older physical panel with buttons and labels.","cn":"可见的表面：屏幕排布，以及更古老的、带按钮与标注的实体面板。"},{"senses":"03 · 08","en":"BEFORE AND AFTER: a phase in the schedule, and the plan handed to builders at its end.","cn":"先后两端：进度表上的一个阶段，以及阶段结束时交给实现者的方案。"},{"senses":"04","en":"RESEARCH BRANCH: the academic study of how people and machines meet.","cn":"研究分支：关于人与机器如何相遇的学术研究。"},{"senses":"06","en":"PROGRAM SEAM: an interface with no pixels, designed for another program to call.","cn":"程序接缝：没有像素的接口，供另一个程序调用。"}]},"affixes":{"intro":{"en":"Interface design is two Latin-derived nouns placed side by side; neither half takes a new affix in the compound.","cn":"interface design 是两个拉丁来源名词并置而成；在复合词中，两半都没有新增词缀。"},"latinIntro":{"en":"Latin supplies inter, facies, signum and designare; French supplied the modern shapes of both nouns.","cn":"拉丁语提供 inter、facies、signum 与 designare；法语提供了两个名词的现代形式。"},"items":[{"word":"inter-","structure":"inter (Latin preposition)","meaning":"between, among","meaningCN":"在……之间","example":"The prefix places the surface between two parties.","exampleCN":"这个介词把表面放在两方之间。"},{"word":"facies","structure":"facies (Latin noun, fifth declension)","meaning":"form, appearance, surface","meaningCN":"形状；外观；表面","example":"The noun supplies the visible side of the word.","exampleCN":"这个名词提供这个词「可见的一面」。"},{"word":"face","structure":"face (English noun from French)","meaning":"front surface","meaningCN":"正面；表面","example":"English kept both the bodily and the surface sense.","exampleCN":"英语同时保留了「脸」与「表面」两义。"},{"word":"signum","structure":"signum (Latin noun)","meaning":"a mark, a sign","meaningCN":"标记；符号","example":"The mark is what design originally traced.","exampleCN":"「标记」正是设计最初要描出的东西。"},{"word":"designare","structure":"designare (Latin verb)","meaning":"to mark out, to plan","meaningCN":"标画；规划","example":"The verb joins planning to drawing.","exampleCN":"这个动词把规划与绘制连在一起。"},{"word":"design","structure":"design (English noun and verb from French)","meaning":"a plan or to plan a form","meaningCN":"方案；规划形态","example":"The word entered English through French dess(e)ign.","exampleCN":"这个词经法语形式进入英语。"},{"word":"-er","structure":"-er (English agent ending)","meaning":"one who does","meaningCN":"做……的人","example":"The ending names the person who carries out the craft.","exampleCN":"这个词尾指从事这门手艺的人。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"Designing is the ongoing work behind a finished design.","exampleCN":"designing 是成品方案背后的持续工作。"}],"latinEntries":[{"word":"facies","structure":"facies, faciei (n., fifth declension)","meaning":"shape, appearance, face","meaningCN":"形状、外观、脸面"},{"word":"signum","structure":"signum, signi (n., second declension)","meaning":"mark, token","meaningCN":"标记、记号"}],"derivatives":[{"word":"interface","pos":"n.","zh":"界面"},{"word":"design","pos":"n./v.","zh":"设计"},{"word":"designer","pos":"n.","zh":"设计师"},{"word":"redesign","pos":"v.","zh":"重新设计"}]}},{"word":"digital literacy","ipa_uk":"/ˌdɪdʒɪtl ˈlɪtərəsi/","ipa_us":"/ˌdɪdʒɪtl ˈlɪtərəsi/","definition_zh":"数字素养；使用数字工具并判断、评估与管理数字信息的能力","definition_en":"the ability to use digital tools and to find, judge, manage and use digital information responsibly","core_image":"一个人一手翻着纸质手册，一手在屏幕上滑动，两边的信息被他互相核对","scene":"教室里，学生一手翻着纸质手册，一手在屏幕上滑动，把两边的说法互相核对。Digital literacy is now as basic as reading, because most notices arrive online first.","sceneCN":"这里 digital literacy 指使用数字工具并判断数字信息的能力（第 1 个义项：综合能力）；句意：如今数字素养已和识字一样基础，因为大多数通知先在网上出现。","pos":[{"tag":"n.","zh":"数字素养；数字信息能力（作定语）"}],"collocations":[{"phrase":"digital literacy skills","zh":"数字素养技能"},{"phrase":"digital literacy programme","zh":"数字素养项目"},{"phrase":"digital literacy course","zh":"数字素养课程"},{"phrase":"improve digital literacy","zh":"提升数字素养"},{"phrase":"basic digital literacy","zh":"基本数字素养"},{"phrase":"digital literacy gap","zh":"数字素养差距"}],"forms":[{"label":"复合名词","form":"digital literacy"}],"derivatives":[{"word":"digital","pos":"adj.","zh":"数字的"},{"word":"literate","pos":"adj.","zh":"识字的"},{"word":"literacy","pos":"n.","zh":"读写能力"},{"word":"illiterate","pos":"adj.","zh":"不识字的"}],"senses":[{"no":"01","title":"The general ability to work with digital tools","titleCN":"使用数字工具的综合能力","definition":"the competence to operate devices, software and accounts without constant help","definitionCN":"无需一直求助就能操作设备、软件与账号的能力","example":"Digital literacy begins with knowing how a file is saved.","exampleCN":"数字素养从知道文件怎样保存开始。","why":"literacy names a basic competence, and the compound transfers that idea from letters to digital tools.","whyCN":"literacy 指一种基本能力，这个复合词把「识字」的观念移到数字工具上。"},{"no":"02","title":"The ability to judge online information","titleCN":"判断网络信息的能力","definition":"the skill of finding a source, checking its origin and deciding whether to trust it","definitionCN":"找到来源、核查其出处并决定是否可信的技能","example":"Digital literacy means asking who wrote the page and when.","exampleCN":"数字素养就是追问这页内容是谁、何时写的。","why":"when anyone can publish, reading becomes judging, and the old literacy idea widens.","whyCN":"当人人都能发布，阅读就变成判断，旧的识字观念随之扩大。"},{"no":"03","title":"Critical handling of media","titleCN":"对媒介内容的批判性处理","definition":"the habit of separating evidence from persuasion in images, clips and feeds","definitionCN":"在图像、短片与信息流中区分证据与劝说的习惯","example":"Her class treats digital literacy and media literacy as one subject.","exampleCN":"她的课把数字素养与媒介素养当作同一个科目。","why":"the digital form of text is mostly image and video, so the skill overlaps with media criticism.","whyCN":"数字文本多半以图像和视频出现，因此这项技能与媒介批评重叠。"},{"no":"04","title":"A workplace requirement","titleCN":"职场中的一项要求","definition":"the level of digital competence an employer expects of staff","definitionCN":"雇主对员工预期的数字能力水平","example":"The job advert listed digital literacy above years of service.","exampleCN":"招聘广告把数字素养看得比工龄更重要。","why":"a general competence becomes a hiring criterion, and the phrase takes on that administrative role.","whyCN":"普遍能力一旦成为招聘标准，这个短语就承担了行政功能。"},{"no":"05","title":"A school subject","titleCN":"学校课程与科目","definition":"the taught curriculum that trains pupils in safe and effective digital use","definitionCN":"训练学生安全有效使用数字工具的教学课程","example":"Digital literacy is timetabled once a week in the lower school.","exampleCN":"低年级每周排一节数字素养课。","why":"skills that society expects of everyone are eventually written into a syllabus.","whyCN":"社会期待人人具备的技能，最终会被写进课程纲要。"},{"no":"06","title":"Competence in safety and privacy","titleCN":"安全与隐私方面的能力","definition":"the knowledge needed to recognise scams, protect accounts and limit exposure","definitionCN":"识别骗局、保护账号并减少暴露的知识","example":"Digital literacy saves more money from fraud than any single tool.","exampleCN":"在防诈骗上，数字素养比任何单一工具都更省钱。","why":"risk is part of the digital environment, so the ability to avoid it is counted as literacy.","whyCN":"风险是数字环境的一部分，因此避开风险的能力也被算作素养。"},{"no":"07","title":"Understanding of data and computation","titleCN":"对数据与计算的基本理解","definition":"a working grasp of how data is collected, stored and turned into decisions","definitionCN":"对数据如何被收集、存储并转化为决定的实际理解","example":"Digital literacy includes knowing why a form asks for a postcode.","exampleCN":"数字素养包括明白表格为什么要问邮编。","why":"the literacy idea extends from using tools to understanding what they do with information.","whyCN":"素养的观念从「会用工具」延伸到「明白工具拿信息做什么」。"},{"no":"08","title":"A policy goal for inclusion","titleCN":"促进社会包容的政策目标","definition":"the public aim of making digital participation possible for every group","definitionCN":"让每个群体都能参与数字生活的公共目标","example":"The grant was framed as digital literacy for rural towns.","exampleCN":"这笔拨款被表述为面向乡镇的数字素养项目。","why":"when access becomes a social dividing line, the competence is treated as a public good.","whyCN":"当接入成为社会分界线，这项能力就被当作公共福利来对待。"}],"etymology":{"intro":{"en":"Digital literacy is a late twentieth-century compound. Digital goes back to the Latin word for finger, literacy to the Latin word for letter; together they move a schoolroom idea into the network age.","cn":"digital literacy 是二十世纪后期的复合词。digital 可追到拉丁语「手指」，literacy 追到拉丁语「字母」；两者合起来把课堂里的观念搬进网络时代。"},"items":[{"era":"LATIN DIGITUS","en":"Latin digitus meant finger or toe. Because people counted on their fingers, the same word came to mean a numeral and then a numeric code.","cn":"拉丁语 digitus 指手指或脚趾。因为人用手指计数，同一个词又指数码，进而指数字编码。"},{"era":"ENGLISH DIGITAL","en":"Digital first meant relating to fingers, then relating to numerals, and in the twentieth century to signals stored as numbers.","cn":"digital 先指与手指有关，再指与数有关，二十世纪则指以数字形式存储的信号。"},{"era":"LATIN LITTERA","en":"Latin littera meant a letter of the alphabet and, in the plural, a written work. English letter and literature descend from it.","cn":"拉丁语 littera 指字母，复数则指著作。英语 letter 与 literature 都由它而来。"},{"era":"ENGLISH LITERACY","en":"Literacy, formed on the adjective literate, named the ability to read and write, and later any basic competence in a field.","cn":"literacy 由形容词 literate 构成，指读写能力，后来泛指某个领域的基本能力。"},{"era":"MODERN COMPOUND","en":"The two words were joined as computers entered schools and workplaces, to name the competence that replaces an older print skill.","cn":"当计算机进入学校与职场，两个词被合在一起，用来指取代旧印刷技能的那项能力。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of Latin littera is debated, and the forms proposed for it are reconstructions rather than attested ancestors.","cn":"来源不确定：拉丁语 littera 更早的来源仍有争论，为它提出的形式属于重构形式，而非有记载的祖词。"}]},"similar":{"note":{"en":"The first group is the words inside the compound and their relatives; the second group is neighbouring literacies.","cn":"第一组是复合词内部的词及其亲属词；第二组是相邻的各种素养。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"digital","ipa":"/ˈdɪdʒɪtl/","tag":"the first element","definition":"Relating to numeric signals or computer technology; alone it says nothing about a person's skill.","definitionCN":"指与数字信号或计算机技术有关；单独用时并不表示人的技能。"},{"word":"literacy","ipa":"/ˈlɪtərəsi/","tag":"the second element","definition":"The ability to read and write; the compound replaces letters with digital practice.","definitionCN":"读写能力；复合词把「字母」替换成数字实践。"},{"word":"literate","ipa":"/ˈlɪtərət/","tag":"the adjective","definition":"Able to read and write; digitally literate is the matching adjective for the compound.","definitionCN":"能读写的；digitally literate 是这个复合词对应的形容词。"},{"word":"digit","ipa":"/ˈdɪdʒɪt/","tag":"same root, single unit","definition":"A finger or a single numeral; the small unit behind the adjective.","definitionCN":"指手指或单个数字；形容词背后的小单位。"}]},{"heading":"NEAR MEANING","entries":[{"word":"media literacy","ipa":"/ˈmiːdiə ˈlɪtərəsi/","tag":"messages and persuasion","definition":"The ability to read messages for their purpose and bias; it overlaps with digital literacy on feeds and clips.","definitionCN":"读懂信息的意图与偏向的能力；在信息流与短视频上与数字素养重叠。"},{"word":"information literacy","ipa":"/ˌɪnfəˈmeɪʃn ˈlɪtərəsi/","tag":"finding and judging sources","definition":"The skill of locating, evaluating and citing information, often taught in libraries.","definitionCN":"查找、评估并引用信息的技能，常在图书馆课程中讲授。"},{"word":"computer literacy","ipa":"/kəmˈpjuːtə ˈlɪtərəsi/","tag":"older, narrower term","definition":"Basic familiarity with hardware and office software; it covers operation rather than judgement.","definitionCN":"对硬件与办公软件的基本熟悉；偏重操作，而非判断。"},{"word":"digital skills","ipa":"/ˌdɪdʒɪtl ˈskɪlz/","tag":"practical tasks","definition":"The specific abilities to perform tasks online; literacy adds judgement and understanding.","definitionCN":"在网上完成具体任务的能力；literacy 另加判断与理解。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real root meanings and the real policy phrases.","cn":"正常联想：来自真实词根含义与真实政策搭配。"},"normal":[{"en":"Digitus is a finger, and counting on fingers gave us the numeral and then the digital age.","cn":"digitus 是手指，用手指计数产生了数字，也产生了数字时代。"},{"en":"Littera is a letter, and literacy is the ability to handle letters; swap letters for screens and you have the compound.","cn":"littera 是字母，literacy 是处理字母的能力；把字母换成屏幕，就得到这个复合词。"},{"en":"Fixed phrases: digital literacy skills, basic digital literacy, digital literacy gap.","cn":"固定搭配：数字素养技能、基本数字素养、数字素养差距。"},{"en":"It is both a skill and a subject: you can have it, and you can be taught it.","cn":"它既是能力也是科目：人可以具备它，也可以被教授它。"},{"en":"Two halves of judgement: finding a source and deciding whether to trust it.","cn":"判断分两步：找到来源，再决定是否可信。"}],"abstract":[{"en":"Picture a hand that counts on its fingers while the other hand types.","cn":"想象一只手还在数手指，另一只手已经在打字。"},{"en":"Picture a letter that arrives as a thousand small glowing dots and still has to be read.","cn":"想象一封信用成千上万个发光小点送达，却仍然需要被读懂。"},{"en":"Picture a key that opens a room while another key decides whether the room should be entered.","cn":"想象一把钥匙打开一间屋子，另一把钥匙决定该不该进去。"}]},"examples":[{"en":"Digital literacy is not the same as owning a phone.","cn":"数字素养并不等于拥有一部手机。"},{"en":"The library runs free digital literacy sessions on Saturday mornings.","cn":"图书馆每周六上午开设免费的数字素养课程。"},{"en":"Employers now screen for digital literacy in the first interview.","cn":"雇主现在在第一轮面试就考察数字素养。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「低技（digital）特儿（tal）立（li）特（te）拉稀（racy）」——低头摆弄技术却仍要会读会判，就是数字素养","word":"digital literacy"},"root":"拉丁 digitus「手指」→ 计数→数字→英语 digital；拉丁 littera「字母」→ 英语 letter / literature → literate → literacy；二十世纪后期合成 digital literacy。","sensesIntro":{"en":"Eight senses move from general device competence to judging sources, media criticism, hiring, schooling, safety, understanding data and public inclusion.","cn":"八个义项从设备操作能力出发，走向来源判断、媒介批判、招聘、学校课程、安全、数据理解与公共包容。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person checking a paper manual against a glowing screen, comparing the two accounts line by line.","cn":"核心意象：一个人拿纸质手册对着屏幕，逐条核对两边的说法。"},"chain":["DIGITAL TOOL","OPERATION","INFORMATION","JUDGEMENT","RESPONSIBLE USE","PARTICIPATION"],"branches":[{"senses":"01 · 07","en":"OPERATING AND UNDERSTANDING: running tools on one side, grasping what they do with data on the other.","cn":"操作与理解：一边会用工具，一边明白工具拿数据做什么。"},{"senses":"02 · 03","en":"JUDGING CONTENT: checking a source, and reading images and feeds critically.","cn":"判断内容：核查来源，并批判地阅读图像与信息流。"},{"senses":"04","en":"WORKPLACE: the level of competence an employer expects and tests.","cn":"职场：雇主期待并考察的能力水平。"},{"senses":"05","en":"SCHOOLING: the same skill written into a timetable and a syllabus.","cn":"学校教育：同一技能被写进课表与课程纲要。"},{"senses":"06 · 08","en":"SAFETY AND ACCESS: avoiding fraud on one side, making participation possible for every group on the other.","cn":"安全与接入：一边是防诈骗，一边是让每个群体都能参与。"}]},"affixes":{"intro":{"en":"Digital literacy is a compound of an adjective and a noun; both come from Latin bases but neither adds an affix in the joining.","cn":"digital literacy 是形容词加名词的复合词；两部分都来自拉丁词基，拼合时都没有新增词缀。"},"latinIntro":{"en":"Latin supplies digitus, finger, and littera, letter; the English endings -al and -cy were added before the two words met.","cn":"拉丁语提供 digitus「手指」与 littera「字母」；英语词尾 -al 与 -cy 在两个词相遇之前就已加上。"},"items":[{"word":"digitus","structure":"digitus (Latin noun)","meaning":"finger, toe","meaningCN":"手指；脚趾","example":"The finger is the starting point of the numeral sense.","exampleCN":"「手指」是数字义的起点。"},{"word":"-al","structure":"-al (Latin adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending turns the noun into an adjective of relation.","exampleCN":"这个词尾把名词变成关系形容词。"},{"word":"littera","structure":"littera (Latin noun)","meaning":"a letter of the alphabet","meaningCN":"字母","example":"The letter is the unit that literacy originally handled.","exampleCN":"字母是 literacy 最初处理的对象。"},{"word":"-ate","structure":"-atus (Latin adjective ending)","meaning":"provided with","meaningCN":"具备……的","example":"Literate says a person has been provided with letters.","exampleCN":"literate 表示一个人已经具备字母能力。"},{"word":"-cy","structure":"-cy (English noun ending from Latin -cia)","meaning":"state or quality","meaningCN":"状态或性质","example":"The ending turns literate into the name of an ability.","exampleCN":"这个词尾把 literate 变成能力的名称。"},{"word":"digital","structure":"digitalis through French digital","meaning":"of fingers, then of numerals","meaningCN":"先指手指，后指数字","example":"The adjective moved from anatomy to arithmetic.","exampleCN":"这个形容词从身体部位转向算术。"},{"word":"literacy","structure":"literate plus -cy","meaning":"the ability to read and write","meaningCN":"读写能力","example":"The noun widened to cover basic competence in any field.","exampleCN":"这个名词后来泛指任何领域的基本能力。"},{"word":"literate","structure":"littera plus -atus","meaning":"able to read and write","meaningCN":"能读写的","example":"The adjective is the base of the second noun.","exampleCN":"这个形容词是第二个名词的词基。"}],"latinEntries":[{"word":"digitus","structure":"digitus, digiti (n., second declension)","meaning":"finger, toe; a numeral","meaningCN":"手指、脚趾；数字"},{"word":"littera","structure":"littera, litterae (n., first declension)","meaning":"a letter; in the plural, writings","meaningCN":"字母；复数指著作"}],"derivatives":[{"word":"digital","pos":"adj.","zh":"数字的"},{"word":"literacy","pos":"n.","zh":"读写能力"},{"word":"literate","pos":"adj.","zh":"识字的"},{"word":"digit","pos":"n.","zh":"数字；手指"}]}},{"word":"engineering","ipa_uk":"/ˌendʒɪˈnɪərɪŋ/","ipa_us":"/ˌendʒɪˈnɪərɪŋ/","definition_zh":"工程；工程学；把科学原理用于设计、建造与改进的行业与活动","definition_en":"the profession and activity of applying scientific and mathematical principles to design, build and improve things","core_image":"一张铺满图纸的长桌，桌边摆着模型桥、齿轮和计算尺，几个人围着它争论尺寸","scene":"长桌上铺满图纸，模型桥旁散着齿轮与计算尺，几个人围着争论一处尺寸。The bridge stood because careful engineering had anticipated the river's spring floods.","sceneCN":"这里 engineering 指把科学原理用于设计与建造的行业与活动（第 1 个义项：工程这一行业）；句意：那座桥能立住，是因为细致的工程工作早已预判了河流的春汛。","pos":[{"tag":"n.","zh":"工程；工程学；工程设计工作"}],"collocations":[{"phrase":"civil engineering","zh":"土木工程"},{"phrase":"mechanical engineering","zh":"机械工程"},{"phrase":"software engineering","zh":"软件工程"},{"phrase":"engineering degree","zh":"工程学位"},{"phrase":"engineering team","zh":"工程团队"},{"phrase":"reverse engineering","zh":"逆向工程"},{"phrase":"genetic engineering","zh":"基因工程"}],"forms":[{"label":"不可数名词","form":"engineering"},{"label":"复数（罕用，指多种工程实践）","form":"engineerings"}],"derivatives":[{"word":"engineer","pos":"n./v.","zh":"工程师；设计建造"},{"word":"engineered","pos":"adj.","zh":"经工程设计的"},{"word":"bioengineering","pos":"n.","zh":"生物工程"},{"word":"geoengineering","pos":"n.","zh":"地球工程"}],"senses":[{"no":"01","title":"The profession as a whole","titleCN":"作为一个整体的工程行业","definition":"the organised occupation of designing and building reliable structures, machines and systems","definitionCN":"设计并建造可靠结构、机器与系统的有组织职业","example":"Engineering attracts people who like a problem with a measurable answer.","exampleCN":"工程行业吸引那些喜欢有可测量答案的问题的人。","why":"the -ing noun names the occupation, not one act, so it first means the trade as a body of practitioners.","whyCN":"这个 -ing 名词指职业，而不是单次动作，因此首先指由从业者构成的行业。"},{"no":"02","title":"The application of science to practical ends","titleCN":"把科学用于实际目的","definition":"the activity of turning physical knowledge into working designs under real constraints","definitionCN":"在真实约束下把物理知识变成可用设计的活动","example":"Engineering begins where the equation has to survive mud and weather.","exampleCN":"当方程式必须经受泥泞与天气时，工程就开始了。","why":"the word marks the meeting point of theory and matter, which is why it is often defined against pure science.","whyCN":"这个词标记理论与物质的交会点，因此常被拿来与纯科学对照定义。"},{"no":"03","title":"A named branch of the profession","titleCN":"有名字的工程分支","definition":"one specialised division such as civil, mechanical or electrical work","definitionCN":"如土木、机械或电气这样的专门分支","example":"She moved from chemical engineering to safety inspection.","exampleCN":"她从化学工程转到安全检验。","why":"large trades divide by material and method, and each division takes the head word as its family name.","whyCN":"大型行业会按材料与方法分科，每个分支都以这个词作姓氏般的类名。"},{"no":"04","title":"The design work behind a structure","titleCN":"支撑一项结构的设计工作","definition":"the calculations and choices that make a particular bridge, building or device work","definitionCN":"使某座桥、某栋楼或某台设备成立的计算与选择","example":"The elegance of the hall is engineering you cannot see.","exampleCN":"这座大厅的优雅是看不见的工程工作。","why":"a finished object hides its design, and the word names that hidden labour.","whyCN":"成品把设计藏在内部，这个词就指那份看不见的劳动。"},{"no":"05","title":"Analysis of forces and materials","titleCN":"对受力与材料的分析","definition":"the technical calculation of loads, stresses and safety margins","definitionCN":"对荷载、应力与安全裕度的技术计算","example":"Good engineering predicted the crack two winters before it opened.","exampleCN":"优秀的工程分析在裂缝张开前两个冬天就预测到了它。","why":"the intellectual core of the trade is predicting behaviour before anything is built.","whyCN":"这门行业最核心的智力工作，是在建造之前预测行为。"},{"no":"06","title":"Manipulation of people or systems","titleCN":"对人或者系统的操纵","definition":"the arranging of social or financial affairs to produce a desired result","definitionCN":"安排社会或财务事务以产生预期结果","example":"The scheme was social engineering dressed as charity.","exampleCN":"那套方案是披着慈善外衣的社会操纵。","why":"the word's core is planned control of a system, and people can be treated as one.","whyCN":"这个词的核心是对系统的有计划的控制，而人也可以被当作系统。"},{"no":"07","title":"Deliberate alteration of living things","titleCN":"对生物的有意改造","definition":"the planned modification of genes or organisms for a purpose","definitionCN":"为某种目的对基因或生物体进行有计划的改造","example":"Genetic engineering of the crop reduced its water needs.","exampleCN":"对那种作物的基因工程降低了它的用水需求。","why":"once heredity was understood as a mechanism, it could be designed like any other.","whyCN":"一旦遗传被理解为一种机制，它就能像别的机制一样被设计。"},{"no":"08","title":"Financial or business structuring","titleCN":"金融与业务结构的设计","definition":"the construction of financial arrangements to fit a defined aim","definitionCN":"为实现特定目标而搭建的金融安排","example":"The tax result came from financial engineering, not from luck.","exampleCN":"那个税务结果来自金融设计，而不是运气。","why":"money, like steel, can be arranged into structures, and the trade word extends to it.","whyCN":"钱和钢一样可以被搭成结构，行业词就延伸到这里。"},{"no":"09","title":"The academic subject","titleCN":"作为学科的工程学","definition":"the taught discipline of analysis, materials and design in a university","definitionCN":"大学里讲授的分析、材料与设计学科","example":"He teaches engineering to students who have never held a tool.","exampleCN":"他教那些从没拿过工具的学生学工程。","why":"a trade codified in textbooks becomes a degree subject with the same name.","whyCN":"被写进教科书的行业会成为同名学位科目。"},{"no":"10","title":"The industrial sector","titleCN":"工程产业部门","definition":"the firms and jobs that make up the trade in an economy","definitionCN":"在经济中构成该行业的公司与岗位","example":"Engineering employs more people here than farming does.","exampleCN":"在这里，工程产业雇用的人比农业多。","why":"a profession counted in statistics becomes a sector, and the name travels with it.","whyCN":"被统计的职业会变成一个产业部门，名称也随之而去。"}],"etymology":{"intro":{"en":"Engineering grows from engine, and engine goes back through French to Latin ingenium, inborn cleverness. The modern sense shifts from a clever device to the organised design of devices.","cn":"engineering 由 engine 生长而来，而 engine 经法语可追到拉丁语 ingenium「天生的才智」。现代含义从「巧妙的装置」转向「有组织地设计装置」。"},"items":[{"era":"LATIN INGENIUM","en":"Latin ingenium meant inborn character or natural talent, built from in- and gignere, to beget. A device born of talent was also called an ingenium.","cn":"拉丁语 ingenium 指天生的性情或才能，由 in- 与 gignere「生育」构成。由才能所生之物也被称为 ingenium。"},{"era":"OLD FRENCH ENGIN","en":"Old French engin meant cleverness and also a contrivance, especially a military engine for a siege.","cn":"古法语 engin 指聪明，也指巧妙的装置，尤指攻城用的军用器械。"},{"era":"ENGLISH ENGINE","en":"English engine first named any machine or device, and only with steam did it narrow to a power-producing motor.","cn":"英语 engine 最初指任何机器或装置，直到蒸汽时代才收窄为产生动力的发动机。"},{"era":"MILITARY ENGINEER","en":"An engineer was first the person who built and worked military engines; the title later covered civil works as well.","cn":"engineer 最初指建造与操作军用器械的人；这个称号后来也涵盖民用工程。"},{"era":"ENGLISH ENGINEERING","en":"Engineering named the activity of such builders in the eighteenth century, when roads, canals and machines became a profession.","cn":"十八世纪，道路、运河与机器成为一门职业，engineering 才用来指这些建造者的活动。"},{"era":"MODERN BRANCHES","en":"The word then multiplied into branches and into figurative uses such as social and genetic engineering, all keeping the sense of planned construction.","cn":"此后这个词繁殖出许多分支，也进入社会工程、基因工程等比喻用法，全都保留「有计划的建造」这一含义。"}]},"similar":{"note":{"en":"The first group shares the engine root and the professional family; the second group is the neighbouring ideas of technology and design.","cn":"第一组共享 engine 词根与职业词族；第二组是技术与设计这些相邻观念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"engineer","ipa":"/ˌendʒɪˈnɪə/","tag":"the person","definition":"The practitioner; engineering is the field and the activity that the practitioner carries out.","definitionCN":"指从业者；engineering 是从业者所从事的领域与活动。"},{"word":"engine","ipa":"/ˈendʒɪn/","tag":"the root noun","definition":"A machine that converts energy into motion; the older and wider sense was any contrivance.","definitionCN":"把能量转成运动的机器；更早更广的含义是任何巧妙装置。"},{"word":"engineered","ipa":"/ˌendʒɪˈnɪəd/","tag":"participle and adjective","definition":"Designed with deliberate technical care, as in an engineered joint.","definitionCN":"指经过有意的技术设计，如「工程设计的接缝」。"},{"word":"engineering science","ipa":"/ˌendʒɪˈnɪərɪŋ ˈsaɪəns/","tag":"the theoretical side","definition":"The body of scientific knowledge that supports engineering practice.","definitionCN":"支撑工程实践的那部分科学知识。"}]},{"heading":"NEAR MEANING","entries":[{"word":"technology","ipa":"/tekˈnɒlədʒi/","tag":"the products and knowledge","definition":"The tools and techniques a society uses; engineering is the work of creating them.","definitionCN":"一个社会使用的工具与技术；engineering 是创造它们的工作。"},{"word":"applied science","ipa":"/əˈplaɪd ˈsaɪəns/","tag":"knowledge, not practice","definition":"Science directed at practical problems; engineering adds design decisions under cost and safety limits.","definitionCN":"面向实际问题的科学；engineering 另加成本与安全限制下的设计决策。"},{"word":"construction","ipa":"/kənˈstrʌkʃn/","tag":"building activity","definition":"The act of building on site; engineering is the wider work that plans and justifies it.","definitionCN":"指在现场施工；engineering 是包含规划与论证的更广工作。"},{"word":"design","ipa":"/dɪˈzaɪn/","tag":"the plan","definition":"The arrangement of a form to meet a purpose; engineering is the profession that applies it to physical systems.","definitionCN":"为达成目的而安排形态；engineering 是把它施于实体系统的职业。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real Latin root and the real branch names.","cn":"正常联想：来自真实拉丁词根与真实分支名称。"},"normal":[{"en":"Ingenium meant inborn talent; an engine was a thing born of talent.","cn":"ingenium 指天生的才能；engine 就是才能所生之物。"},{"en":"The title started with military engines and then moved to roads and machines.","cn":"这个称号从军用器械开始，后来转向道路与机器。"},{"en":"Branch names all end in the same word: civil, mechanical, electrical, software.","cn":"各分支名都以同一个词收尾：土木、机械、电气、软件。"},{"en":"Fixed phrases show its reach: engineering degree, engineering team, reverse engineering.","cn":"固定搭配显示它的范围：工程学位、工程团队、逆向工程。"},{"en":"The word is uncountable as a field, so one says a career in engineering, not an engineering.","cn":"作为领域它不可数，所以说「从事工程行业」，而不是「一个工程」。"}],"abstract":[{"en":"Picture a drawing table whose lines hold up a bridge that does not exist yet.","cn":"想象一张绘图桌，纸上的线条撑起一座还不存在的桥。"},{"en":"Picture a gear that turns a river into a schedule.","cn":"想象一枚齿轮把一条河变成一张时间表。"},{"en":"Picture a safety margin drawn as a thin margin on paper and standing as a thick wall in the world.","cn":"想象纸上薄薄一道安全裕度，在现实里站成厚厚一堵墙。"}]},"examples":[{"en":"Engineering is judged by what happens after ten winters, not on opening day.","cn":"工程的好坏要看十个冬天之后，而不是落成那天。"},{"en":"She studied engineering because she wanted to see her drawings become heavy things.","cn":"她学工程，是因为想让自己的图纸变成有重量的东西。"},{"en":"The company treats engineering and maintenance as one budget line.","cn":"公司把工程与维护放在同一条预算线上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「恩（en）机（gi）捏（neer）ring」——承恩于机器，又亲手去捏去造的那一行，就是工程","word":"engineering"},"root":"拉丁 ingenium「天生才能」← in- + gignere「生育」→ 古法语 engin「巧器」→ 英语 engine；engineer 先指造军用器械者，十八世纪起 engineering 指这一职业与活动。","sensesIntro":{"en":"Ten senses move from the profession to applied science, branches, hidden design work, force analysis, social and genetic manipulation, finance, teaching and the sector.","cn":"十个义项从行业出发，经过应用科学、分支、隐藏的设计工作、受力分析、社会与基因改造、金融、教学，最后到产业部门。"},"semanticMap":{"core":{"en":"CORE IMAGE: a table of drawings, a model bridge and a slide rule, with people arguing over one dimension.","cn":"核心意象：一桌图纸、一座模型桥与一把计算尺，人们围着某个尺寸争论。"},"chain":["HUMAN NEED","SCIENTIFIC KNOWLEDGE","DESIGN DECISION","BUILT STRUCTURE","SYSTEM CONTROL","ENGINEERED WORLD"],"branches":[{"senses":"01 · 09","en":"PROFESSION AND SUBJECT: the trade as a body of workers, and the same trade taught as a degree.","cn":"行业与学科：由从业者构成的行业，以及被当作学位教授的同一行业。"},{"senses":"02 · 05","en":"THEORY MEETS MATTER: applying science, and calculating loads and margins before building.","cn":"理论与物质相接：应用科学，并在建造前计算荷载与裕度。"},{"senses":"03 · 10","en":"DIVISIONS AND SCALE: named branches on one side, the whole sector counted in an economy on the other.","cn":"分支与规模：一边是有名目的分支，一边是经济统计中的整个产业。"},{"senses":"04 · 08","en":"HIDDEN STRUCTURING: the design behind a built thing, and the arrangement of financial affairs.","cn":"隐形的搭建：建成物背后的设计，以及金融事务的安排。"},{"senses":"06 · 07","en":"TREATING SYSTEMS AS BUILDABLE: social manipulation, and the deliberate alteration of living things.","cn":"把系统当作可建造物：社会操纵，以及对生物的有意改造。"}]},"affixes":{"intro":{"en":"Engineering is an English -ing noun on the base engineer, which itself carries a French and Latin history; the ending makes a trade out of a person.","cn":"engineering 是以 engineer 为词基的英语 -ing 名词，而 engineer 本身带有法语与拉丁语的历史；这个词尾把人变成一门行业。"},"latinIntro":{"en":"Latin ingenium is the deep source; French engin and engineer are the middle steps; English then added -ing to name the occupation.","cn":"拉丁语 ingenium 是深远源头；法语 engin 与 engineer 是中间环节；英语再加 -ing 来指这门职业。"},"items":[{"word":"in-","structure":"in- (Latin prefix)","meaning":"in, within","meaningCN":"在内","example":"The prefix is part of the Latin noun for inborn quality.","exampleCN":"这个前缀是拉丁语「天生品质」名词的一部分。"},{"word":"gignere","structure":"gignere (Latin verb)","meaning":"to beget, to produce","meaningCN":"生育；产生","example":"The verb explains why a device could be called a born thing.","exampleCN":"这个动词解释了为何装置可被称为「被生出之物」。"},{"word":"ingenium","structure":"ingenium (Latin noun)","meaning":"inborn talent; a clever device","meaningCN":"天生才能；巧妙的装置","example":"The noun already joins talent with contrivance.","exampleCN":"这个名词已经把才能与装置连在一起。"},{"word":"engin","structure":"engin (Old French noun)","meaning":"cleverness; a siege engine","meaningCN":"聪明；攻城器械","example":"French narrowed the noun toward machines of war.","exampleCN":"法语把这个名词收窄到战争器械。"},{"word":"engine","structure":"engine (English noun)","meaning":"a machine or device","meaningCN":"机器；装置","example":"English widened it again to any machine.","exampleCN":"英语又把它扩大到任何机器。"},{"word":"engineer","structure":"engine plus -eer (agent ending from French)","meaning":"one who builds engines","meaningCN":"建造器械的人","example":"The ending marks the person who practices the trade.","exampleCN":"这个词尾标记从事该行业的人。"},{"word":"-ing","structure":"-ing (English gerund and abstract noun ending)","meaning":"the activity or field of","meaningCN":"……的活动或领域","example":"The ending turns the person's work into a profession.","exampleCN":"这个词尾把人的工作变成一门职业。"},{"word":"bio-","structure":"bio- (Greek prefix)","meaning":"life","meaningCN":"生命","example":"The prefix marks a branch that works on living material.","exampleCN":"这个前缀标记一个处理生命材料的分支。"},{"word":"re-","structure":"re- (Latin prefix)","meaning":"again, back","meaningCN":"再次；回","example":"Reverse engineering takes a finished thing backward.","exampleCN":"逆向工程把成品往回拆解。"}],"latinEntries":[{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"inborn character, talent, clever device","meaningCN":"天性、才能、巧妙的装置"}],"derivatives":[{"word":"engineer","pos":"n./v.","zh":"工程师；设计建造"},{"word":"engine","pos":"n.","zh":"发动机；机器"},{"word":"bioengineering","pos":"n.","zh":"生物工程"},{"word":"geoengineering","pos":"n.","zh":"地球工程"}]}},{"word":"engineer","ipa_uk":"/ˌendʒɪˈnɪə/","ipa_us":"/ˌendʒɪˈnɪr/","definition_zh":"工程师；设计并建造机器、结构或系统的人；也指巧妙地安排或促成","definition_en":"a person who designs and builds machines, structures or systems; also to arrange or bring something about by skill","core_image":"一个戴着安全帽的人蹲在图纸与实物之间，用手比量一处接缝，然后在纸上改掉一个数字","scene":"工地上，戴安全帽的人蹲在图纸与钢梁之间，用手比量一处接缝，又在纸上改掉一个数字。The engineer changed one dimension and the whole frame became cheaper to build.","sceneCN":"这里 engineer 指设计并建造结构的人（第 1 个义项：工程师这一职业的人）；句意：这位工程师改动了一个尺寸，整个框架的建造成本便降低了。","pos":[{"tag":"n.","zh":"工程师；设计师；轮机员"},{"tag":"v.","zh":"设计建造；巧妙地促成"}],"collocations":[{"phrase":"civil engineer","zh":"土木工程师"},{"phrase":"software engineer","zh":"软件工程师"},{"phrase":"chief engineer","zh":"总工程师"},{"phrase":"field engineer","zh":"现场工程师"},{"phrase":"engineer a solution","zh":"设计出一套解决办法"},{"phrase":"engineer a deal","zh":"巧妙地促成交易"},{"phrase":"reverse engineer","zh":"逆向拆解分析"}],"forms":[{"label":"复数","form":"engineers"},{"label":"第三人称单数","form":"engineers"},{"label":"过去式","form":"engineered"},{"label":"过去分词","form":"engineered"},{"label":"现在分词","form":"engineering"}],"derivatives":[{"word":"engineering","pos":"n.","zh":"工程；工程学"},{"word":"engineered","pos":"adj.","zh":"经设计的"},{"word":"engineerable","pos":"adj.","zh":"可工程化设计的（罕用）"}],"senses":[{"no":"01","title":"One who designs and builds","titleCN":"设计与建造的人","definition":"a person who applies technical knowledge to make machines, structures or systems work","definitionCN":"运用技术知识使机器、结构或系统运转的人","example":"The engineer walked the site before agreeing to the plan.","exampleCN":"工程师先走了一遍现场，才同意那套方案。","why":"the -eer ending marks the agent, so the word begins as the person who works with engines.","whyCN":"词尾标记施事者，因此这个词最初指与器械打交道的人。"},{"no":"02","title":"A licensed professional title","titleCN":"受许可的职业头衔","definition":"a formally qualified and often registered practitioner with legal responsibility for designs","definitionCN":"具备正式资格、常需注册并对设计负法律责任的从业者","example":"Only a licensed engineer may sign the structural drawings.","exampleCN":"只有持证工程师才能在结构图上签字。","why":"when public safety depends on a signature, the occupation becomes a protected title.","whyCN":"当公共安全系于一个签名，这个职业就变成受保护的头衔。"},{"no":"03","title":"The one who runs an engine","titleCN":"操作发动机的人","definition":"the crew member responsible for a ship's or train's engines and machinery","definitionCN":"船上或火车上负责发动机与机械的船员或乘务员","example":"The engine room answered to the engineer, not to the captain.","exampleCN":"轮机舱听工程师的，而不是听船长的。","why":"the oldest everyday sense is the person in charge of the engine itself, a mechanic rather than a designer.","whyCN":"最古老的日常义是掌管发动机本身的人，是技工而不是设计者。"},{"no":"04","title":"To design and construct","titleCN":"设计并建造","definition":"to plan and build something so that it meets a technical requirement","definitionCN":"为使某物满足技术要求而规划并建造","example":"They engineered the tunnel to drain itself without pumps.","exampleCN":"他们把隧道设计成无需水泵即可自排水。","why":"the noun's work becomes a verb the moment people speak of doing what the person does.","whyCN":"当人们开始说「做这个人的事」，名词的工作就变成了动词。"},{"no":"05","title":"To arrange cleverly","titleCN":"巧妙地安排","definition":"to plan a situation so that a desired result follows","definitionCN":"安排局面，使预期结果随之出现","example":"They engineered a delay that nobody could object to.","exampleCN":"他们安排了一次谁也挑不出毛病的延迟。","why":"planned construction of a situation uses the same skill as planned construction of a bridge.","whyCN":"安排局面与建造桥梁运用同一种「有计划的搭建」技能。"},{"no":"06","title":"To bring about by manipulation","titleCN":"通过操纵促成","definition":"to cause an outcome by quietly controlling the conditions","definitionCN":"通过悄悄控制条件造成某个结果","example":"The result was engineered long before the vote.","exampleCN":"那个结果早在投票之前就被促成了。","why":"the neutral verb darkens when the arrangement is hidden, because control without disclosure is manipulation.","whyCN":"当安排被隐藏时，这个中性动词就变暗，因为不公开的控制就是操纵。"},{"no":"07","title":"A military builder of works","titleCN":"军中修筑工事的人","definition":"a soldier trained to build bridges, roads and fortifications","definitionCN":"受训修筑桥梁、道路与工事的军人","example":"A military engineer surveyed the crossing before dawn.","exampleCN":"一名军事工程人员在黎明前勘察了渡口。","why":"the title was born in armies, where engines meant siege machines.","whyCN":"这个头衔诞生于军队，那时「器械」指攻城机械。"},{"no":"08","title":"A software professional","titleCN":"软件从业者","definition":"a person who designs and maintains programs and systems","definitionCN":"设计并维护程序与系统的人","example":"The engineer fixed the bug by removing a line, not adding one.","exampleCN":"工程师删掉一行代码而不是加一行，就修好了那个缺陷。","why":"programs are now built things, so their builders inherit the old title without any metal involved.","whyCN":"程序如今也是被建造之物，其建造者便继承了旧头衔，尽管不涉及金属。"},{"no":"09","title":"The on-site technical specialist","titleCN":"现场技术专员","definition":"the person who installs, tests and repairs equipment where it is used","definitionCN":"在使用现场安装、测试与维修设备的人","example":"A field engineer arrived with two replacement boards.","exampleCN":"一位现场工程师带着两块备用板赶到。","why":"design and repair split into separate roles, and both keep the same broad title.","whyCN":"设计与维修分成两种角色，两者都保留同一个宽泛头衔。"},{"no":"10","title":"One who alters living material","titleCN":"改造生物材料的人","definition":"a specialist who redesigns genes or organisms","definitionCN":"重新设计基因或生物体的专业人员","example":"The genetic engineer checked the sequence twice before proceeding.","exampleCN":"基因工程师在继续之前把序列检查了两遍。","why":"the trade word follows its new materials, so a person who edits heredity is titled like a builder.","whyCN":"行业词随新材料而延伸，编辑遗传的人也被冠以建造者式的头衔。"}],"etymology":{"intro":{"en":"Engineer is a person-word built on engine, from Latin ingenium, inborn talent. It began with military machines and widened to anyone who plans and builds.","cn":"engineer 是在 engine 之上构成的人物名词，而 engine 来自拉丁语 ingenium「天生才能」。它始于军用器械，后来扩大到一切规划与建造的人。"},"items":[{"era":"LATIN INGENIUM","en":"Latin ingenium meant natural talent and, by extension, a thing produced by talent, including a clever device.","cn":"拉丁语 ingenium 指天生的才能，引申指才能所造之物，包括巧妙的装置。"},{"era":"OLD FRENCH ENGIN","en":"Old French engin meant both wit and a contrivance, and siege engines gave the word its military weight.","cn":"古法语 engin 兼指机智与装置，攻城器械给了这个词军事分量。"},{"era":"ENGLISH ENGINE","en":"English engine covered any machine before steam narrowed it to a motor, a narrowing that came later than the person-word.","cn":"英语 engine 曾泛指任何机器，蒸汽时代才收窄为发动机，而这个收窄晚于人物名词的出现。"},{"era":"MILITARY ENGINEER","en":"The engineer was first the soldier or craftsman who built and worked siege engines, then any builder of public works.","cn":"engineer 最初指建造与操作攻城器械的士兵或工匠，后来指任何公共工程的建造者。"},{"era":"CIVIL WIDENING","en":"Roads, canals and railways turned military builders into civil professionals, and the title spread to every branch of construction.","cn":"道路、运河与铁路把军事建造者变成民用专业人员，这个头衔扩散到各个建造分支。"},{"era":"MODERN EXTENSIONS","en":"The twentieth century added software, genetic and financial uses, all sharing the sense of deliberate design.","cn":"二十世纪又添上软件、基因与金融用法，共同点是「有意的设计」。"}]},"similar":{"note":{"en":"The first group is the same root in its other roles; the second group is the neighbouring technical occupations.","cn":"第一组是同一词根的其他角色；第二组是相邻的技术职业。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"engineering","ipa":"/ˌendʒɪˈnɪərɪŋ/","tag":"the field","definition":"The profession and activity; the engineer is the person inside it.","definitionCN":"指职业与活动；engineer 是从事其中的人。"},{"word":"engine","ipa":"/ˈendʒɪn/","tag":"the machine","definition":"The motor or device itself; the person-word was formed from it, not the other way round.","definitionCN":"指发动机或装置本身；人物名词由它构成，而不是反过来。"},{"word":"engineered","ipa":"/ˌendʒɪˈnɪəd/","tag":"participle","definition":"Deliberately designed, or brought about by arrangement, depending on the object.","definitionCN":"指经有意设计，或指被安排促成，视宾语而定。"},{"word":"engineer's","ipa":"/ˌendʒɪˈnɪəz/","tag":"possessive form","definition":"Belonging to the engineer, as in an engineer's drawing; it is not a separate word.","definitionCN":"表示属于工程师，如「工程师的图纸」；它不是另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"technician","ipa":"/tekˈnɪʃn/","tag":"skilled operation","definition":"A person trained to run and maintain equipment; an engineer usually also designs it.","definitionCN":"受训操作与维护设备的人；engineer 通常还要设计。"},{"word":"mechanic","ipa":"/məˈkænɪk/","tag":"repair","definition":"A person who repairs machines; the engineer may have designed what the mechanic fixes.","definitionCN":"修理机器的人；engineer 可能正是设计了该机器的人。"},{"word":"designer","ipa":"/dɪˈzaɪnə/","tag":"form and function","definition":"A person who plans a form; the engineer's planning is constrained by physics and safety.","definitionCN":"规划形态的人；engineer 的规划受物理与安全约束。"},{"word":"architect","ipa":"/ˈɑːkɪtekt/","tag":"buildings","definition":"The designer of buildings; the engineer settles structure and services beneath that design.","definitionCN":"建筑设计者；engineer 负责设计之下的结构与设备。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real suffix and the real pair of noun and verb.","cn":"正常联想：来自真实词尾以及名词与动词的真实成对关系。"},"normal":[{"en":"The ending -eer marks a person, as in mountaineer and auctioneer.","cn":"词尾 -eer 标记人物，如 mountaineer、auctioneer。"},{"en":"The verb repeats the noun's forms: engineers, engineered, engineered, engineering.","cn":"动词重复名词的形式：engineers、engineered、engineered、engineering。"},{"en":"Two objects split the verb: engineer a bridge, engineer a delay.","cn":"两类宾语分开动词：设计一座桥，促成一次延迟。"},{"en":"Fixed phrases: civil engineer, chief engineer, field engineer.","cn":"固定搭配：土木工程师、总工程师、现场工程师。"},{"en":"The title began in armies and ended up in software, which shows how far a person-word can travel.","cn":"这个头衔从军队开始，最后进了软件业，可见人物名词能走多远。"}],"abstract":[{"en":"Picture a hand measuring a joint that exists only on paper, and the paper answering back.","cn":"想象一只手在量只存在于纸上的接缝，而纸竟然回了话。"},{"en":"Picture a bridge that keeps a copy of its builder inside one of its bolts.","cn":"想象一座桥把建造者的影子留在一颗螺栓里。"},{"en":"Picture a schedule rearranged by someone who never touches the clock.","cn":"想象一张时间表被一个从不碰钟的人重新排列。"}]},"examples":[{"en":"The engineer refused to approve a joint she could not calculate.","cn":"那位工程师拒绝批准一处她算不出来的接缝。"},{"en":"They engineered the drainage so that the field would dry by itself.","cn":"他们把排水设计得让田地能自行变干。"},{"en":"A field engineer can fix in an hour what took a year to design.","cn":"现场工程师能在一小时内修好设计花了一年才做出的东西。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「恩（en）机（gi）捏（neer）」——承恩于机器、亲手去捏的人，就是工程师","word":"engineer"},"root":"拉丁 ingenium「天生才能」→ 古法语 engin「巧器」→ 英语 engine；加施事后缀构成 engineer，最初指造军用器械者，后泛指设计建造者，并转出动词用法。","sensesIntro":{"en":"Ten senses run from the designing professional through the licensed title, the engine operator, the two verb uses, military and software roles, field work and the editing of living material.","cn":"十个义项从设计者出发，经过持证头衔、轮机操作者、两种动词用法、军事与软件角色、现场工作，最后到生物材料的改造者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a helmeted figure crouched between drawings and steel, measuring a joint and changing a number.","cn":"核心意象：戴安全帽的人蹲在图纸与钢梁之间，量一处接缝，改掉一个数字。"},"chain":["ENGINE","BUILDER","DESIGN","CONSTRUCTION","CONTROL OF CONDITIONS","OUTCOME"],"branches":[{"senses":"01 · 10","en":"BUILDERS OF THINGS: the general designer-builder, and the specialist who edits living material.","cn":"建造者：泛指设计与建造的人，以及编辑生物材料的专家。"},{"senses":"02 · 07 · 09","en":"TITLES AND ROLES: a licensed professional who signs drawings, a specialist on site, and the military builder of works.","cn":"头衔与角色：在图纸上签字的持证者、现场作业的专员，以及军中修筑工事的人。"},{"senses":"03","en":"ENGINE KEEPER: the mechanic in the engine room, the oldest everyday meaning.","cn":"管机器的人：轮机舱里的技工，最古老的日常含义。"},{"senses":"04 · 08","en":"BUILDING BY DESIGN: constructing to a requirement, and building programs rather than metal.","cn":"按设计建造：按需求建造，以及建造程序而非金属。"},{"senses":"05 · 06","en":"ARRANGING OUTCOMES: skilled arrangement in the open, and quiet manipulation behind it.","cn":"安排结果：公开的巧妙安排，以及其背后的隐秘操纵。"}]},"affixes":{"intro":{"en":"Engineer is engine with an agent ending; the same base then takes -ing for the field and -ed for the participle.","cn":"engineer 是 engine 加施事词尾；同一词基再加 -ing 成为领域名词，加 -ed 成为分词。"},"latinIntro":{"en":"Latin ingenium is the deep base; French engin and the French agent ending -ier shaped the person-word before English took it.","cn":"拉丁语 ingenium 是深远词基；法语 engin 与法语施事词尾 -ier 在英语借入前已塑成这个人物名词。"},"items":[{"word":"ingenium","structure":"ingenium (Latin noun)","meaning":"inborn talent; a clever device","meaningCN":"天生才能；巧妙装置","example":"The noun already joins a person's gift to a made thing.","exampleCN":"这个名词已把人的天赋与造物连在一起。"},{"word":"engin","structure":"engin (Old French noun)","meaning":"wit; a siege machine","meaningCN":"机智；攻城器械","example":"French gave the base its military colour.","exampleCN":"法语给这个词基添上军事色彩。"},{"word":"engine","structure":"engine (English noun)","meaning":"machine, motor","meaningCN":"机器；发动机","example":"The base names the thing the person works with.","exampleCN":"词基指这个人打交道的对象。"},{"word":"-eer","structure":"-eer (agent ending from French -ier)","meaning":"one who works with","meaningCN":"从事……的人","example":"The ending is the same one seen in mountaineer.","exampleCN":"这个词尾与 mountaineer 中所见相同。"},{"word":"-ing","structure":"-ing (English abstract noun ending)","meaning":"the field or activity","meaningCN":"领域或活动","example":"The ending turns the person into a profession.","exampleCN":"这个词尾把人变成一门职业。"},{"word":"-ed","structure":"-ed (English participle ending)","meaning":"having been","meaningCN":"已经被……的","example":"An engineered part has been through deliberate design.","exampleCN":"经工程设计的零件走过了有意的设计。"},{"word":"-able","structure":"-able (English adjective ending)","meaning":"able to be","meaningCN":"可以被……的","example":"The ending marks what can be designed technically.","exampleCN":"这个词尾标记可以被技术设计的东西。"},{"word":"re-","structure":"re- (Latin prefix)","meaning":"back, again","meaningCN":"回；再次","example":"Reverse engineering takes a product apart to learn it.","exampleCN":"逆向工程把产品拆开来学习。"}],"latinEntries":[{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"inborn talent, clever device","meaningCN":"天生才能、巧妙装置"}],"derivatives":[{"word":"engineering","pos":"n.","zh":"工程"},{"word":"engineered","pos":"adj.","zh":"经设计的"},{"word":"engine","pos":"n.","zh":"发动机"},{"word":"bioengineer","pos":"n.","zh":"生物工程师"}]}},{"word":"engineering science","ipa_uk":"/ˌendʒɪˈnɪərɪŋ ˈsaɪəns/","ipa_us":"/ˌendʒɪˈnɪərɪŋ ˈsaɪəns/","definition_zh":"工程科学；支撑工程设计的那部分科学知识，如力学、材料与传热","definition_en":"the body of scientific knowledge, such as mechanics, materials and heat transfer, that supports engineering design","core_image":"黑板上左边是公式，右边是折断的试件，中间用一支粉笔画出两者的对应关系","scene":"黑板左边写满公式，右边摆着一段折断的试件，中间用粉笔画出二者的对应关系。Engineering science explains why the beam bent before anyone tested it.","sceneCN":"这里 engineering science 指支撑工程设计的那部分科学知识（第 1 个义项：知识体系）；句意：工程科学在任何人做测试之前就解释了那根梁为什么会弯。","pos":[{"tag":"n.","zh":"工程科学；工程科学学科（作定语）"}],"collocations":[{"phrase":"engineering science course","zh":"工程科学课程"},{"phrase":"engineering science department","zh":"工程科学系"},{"phrase":"applied engineering science","zh":"应用工程科学"},{"phrase":"engineering science research","zh":"工程科学研究"},{"phrase":"principles of engineering science","zh":"工程科学原理"}],"forms":[{"label":"复合名词","form":"engineering science"},{"label":"复数（指多个分支时）","form":"engineering sciences"}],"derivatives":[{"word":"engineering","pos":"n.","zh":"工程"},{"word":"science","pos":"n.","zh":"科学"},{"word":"scientific","pos":"adj.","zh":"科学的"},{"word":"engineer","pos":"n.","zh":"工程师"}],"senses":[{"no":"01","title":"The scientific base of design","titleCN":"设计所依赖的科学基础","definition":"the knowledge of how materials, forces and flows behave that designers must rely on","definitionCN":"设计者必须依赖的、关于材料、力与流动如何表现的知识","example":"Engineering science tells you the limit before the drawing is finished.","exampleCN":"工程科学在图纸画完之前就告诉你极限在哪里。","why":"the compound joins a practice to the knowledge under it, so it names that knowledge first.","whyCN":"这个复合词把实践与其底下的知识连在一起，因此首先指那套知识。"},{"no":"02","title":"A university department and degree","titleCN":"大学的院系与学位","definition":"an academic unit or programme that teaches the theoretical side of engineering","definitionCN":"讲授工程理论侧面的学术单位或培养项目","example":"The engineering science department shares a building with physics.","exampleCN":"工程科学系与物理系共用一栋楼。","why":"a body of knowledge taught in one place becomes a department with a name.","whyCN":"在一处讲授的知识体系会变成一个有名目的院系。"},{"no":"03","title":"Applied physics in practice","titleCN":"实际应用中的物理","definition":"the working combination of mechanics, thermodynamics and materials knowledge","definitionCN":"力学、热力学与材料知识的实际组合","example":"Engineering science here means heat, stress and fatigue in one course.","exampleCN":"这里的工程科学指把热、应力与疲劳放在一门课里。","why":"the field is applied physics assembled around design problems rather than around nature alone.","whyCN":"这门学问是把物理围绕设计问题、而不是围绕自然本身组装起来的。"},{"no":"04","title":"A subject in a curriculum","titleCN":"课程表中的一门科目","definition":"the taught course that gives students the theory behind their later projects","definitionCN":"在学生日后做项目之前提供理论的讲授科目","example":"Engineering science is the second-year course everyone struggles with.","exampleCN":"工程科学是二年级那门人人都吃力的课。","why":"the same content appears in a timetable, and the phrase becomes a course title.","whyCN":"同样的内容出现在课表里，短语就成课程名称。"},{"no":"05","title":"Modelling and research work","titleCN":"建模与研究工作","definition":"the research activity of building and testing models of physical behaviour","definitionCN":"建立并检验物理行为模型的研究活动","example":"Their engineering science produced a model that matched the test data.","exampleCN":"他们的工程科学研究做出了与试验数据吻合的模型。","why":"between theory and test sits modelling, and the compound also names that activity.","whyCN":"理论与试验之间是建模，这个复合词也指这项活动。"},{"no":"06","title":"The bridge between pure and applied","titleCN":"纯科学与应用之间的桥梁","definition":"the middle ground that turns a physical result into a design rule","definitionCN":"把物理结论转化为设计规则的中间地带","example":"Engineering science is where a physicist's result becomes a builder's rule.","exampleCN":"工程科学就是物理学家的结论变成建造者规则的地方。","why":"the phrase exists precisely because neither pure science nor practice covers that middle step.","whyCN":"正因为纯科学与实践都不覆盖这个中间步骤，这个短语才存在。"},{"no":"07","title":"Simulation and computation","titleCN":"仿真与计算","definition":"the numerical study of behaviour by solving physical equations on a computer","definitionCN":"在计算机上求解物理方程以研究行为的数值工作","example":"Engineering science now spends more time on simulation than on hand calculation.","exampleCN":"如今工程科学花在仿真上的时间比手算更多。","why":"once equations are solved by machine, modelling becomes a large part of the field.","whyCN":"方程一旦由机器求解，建模就成为该领域的一大部分。"},{"no":"08","title":"A qualification area","titleCN":"资格认证所对应的领域","definition":"the knowledge area examined when a technical qualification is awarded","definitionCN":"授予技术资格时所考核的知识领域","example":"The exam covers engineering science before it covers project practice.","exampleCN":"考试先考工程科学，再考项目实务。","why":"what a profession requires of newcomers is written into examinations, and the field is named there.","whyCN":"行业对新人的要求会写进考试，领域名称也出现在那里。"}],"etymology":{"intro":{"en":"Engineering science joins a word for planned building with a Latin word for knowledge. The compound marks the point where knowing and making are deliberately separated for study.","cn":"engineering science 把「有计划的建造」与拉丁语「知识」拼在一起。这个复合词标记了「知」与「造」被刻意分开研究的那一点。"},"items":[{"era":"LATIN INGENIUM","en":"Latin ingenium gave English engine and then engineer, the person whose work became engineering.","cn":"拉丁语 ingenium 先给英语 engine，再给 engineer，这个人的工作后来成了 engineering。"},{"era":"ENGLISH ENGINEERING","en":"From the eighteenth century engineering named the profession of roads, canals and machines.","cn":"十八世纪起，engineering 指道路、运河与机器这一行。"},{"era":"LATIN SCIENTIA","en":"Latin scientia meant knowledge, from scire, to know. English science narrowed it to organised knowledge of the natural world.","cn":"拉丁语 scientia 意为「知识」，来自 scire「知道」。英语 science 把它收窄为关于自然界的系统知识。"},{"era":"NINETEENTH-CENTURY UNION","en":"Engineering schools separated the underlying theory from workshop practice, and the union of the two words named that theory.","cn":"工程学校把底层理论与车间实务分开，两个词的联合就指那套理论。"},{"era":"MODERN FIELD","en":"In the twentieth century the phrase covered mechanics, materials, fluids and heat as a single teaching and research field.","cn":"二十世纪，这个短语把力学、材料、流体与传热合为一个教学与研究领域。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain: the deeper origin of Latin scire is debated, and the forms sometimes derived for it are reconstructions.","cn":"来源不确定：拉丁语 scire 更早的来源有争论，为它推导出的形式属于重构形式。"}]},"similar":{"note":{"en":"The first group shares the words inside the compound; the second group is neighbouring names for knowledge about made things.","cn":"第一组共享复合词内部的词；第二组是关于人造物的相邻知识名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"engineering","ipa":"/ˌendʒɪˈnɪərɪŋ/","tag":"the practice","definition":"The profession itself; engineering science is the theory that the profession applies.","definitionCN":"指职业本身；engineering science 是该职业所应用的理论。"},{"word":"science","ipa":"/ˈsaɪəns/","tag":"the second element","definition":"Organised knowledge of nature; joined to engineering it is knowledge selected for design.","definitionCN":"关于自然的系统知识；与 engineering 组合后，指为设计而选取的知识。"},{"word":"applied science","ipa":"/əˈplaɪd ˈsaɪəns/","tag":"same territory, different emphasis","definition":"Science aimed at practical problems; the compound is the engineering school's name for that aim.","definitionCN":"面向实际问题的科学；这个复合词是工程院校对该取向的称呼。"},{"word":"engineering technology","ipa":"/ˌendʒɪˈnɪərɪŋ tekˈnɒlədʒi/","tag":"the practical cousin","definition":"The hands-on side of technical education, as opposed to the theoretical side named here.","definitionCN":"技术教育中偏动手的一面，与这里命名的理论一面相对。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mechanics","ipa":"/məˈkænɪks/","tag":"one core branch","definition":"The study of forces and motion; it is the oldest and largest part of the field.","definitionCN":"研究力与运动的学问；是该领域最古老、最大的一块。"},{"word":"materials science","ipa":"/məˈtɪəriəlz ˈsaɪəns/","tag":"one core branch","definition":"The study of how substances behave under load, heat and time.","definitionCN":"研究物质在受力、受热与时间作用下如何表现。"},{"word":"physics","ipa":"/ˈfɪzɪks/","tag":"the parent discipline","definition":"The study of matter and energy as such; the compound selects from it what design needs.","definitionCN":"研究物质与能量本身；复合词从中挑出设计所需的部分。"},{"word":"engineering design","ipa":"/ˌendʒɪˈnɪərɪŋ dɪˈzaɪn/","tag":"the other half","definition":"The decisions that turn this knowledge into a particular object.","definitionCN":"把这类知识变成具体对象的那些决定。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the two real words and the real academic phrases.","cn":"正常联想：来自两个真实词与真实学术搭配。"},"normal":[{"en":"Scientia is knowledge, so the phrase is literally the knowledge under the building trade.","cn":"scientia 是知识，所以这个短语字面上就是「建造行业底下的知识」。"},{"en":"Engine goes back to ingenium, inborn talent, so the whole phrase runs from talent to knowledge.","cn":"engine 可追到 ingenium「天生才能」，整个短语从才能一路走到知识。"},{"en":"Fixed phrases: engineering science course, engineering science department.","cn":"固定搭配：工程科学课程、工程科学系。"},{"en":"It is the middle term: not pure physics, not workshop practice.","cn":"它是中间项：既不是纯物理，也不是车间实务。"},{"en":"Three contents anchor it: mechanics, materials, heat.","cn":"三项内容锚定它：力学、材料、热。"}],"abstract":[{"en":"Picture a chalk line drawn between an equation and a broken test piece.","cn":"想象在一条公式与一段折断的试件之间画着一道粉笔线。"},{"en":"Picture a rule book whose pages are printed in the language of physics.","cn":"想象一本规则手册，书页是用物理的语言印的。"},{"en":"Picture a bridge that exists first as a set of assumptions.","cn":"想象一座桥，最初只是一组假设。"}]},"examples":[{"en":"Engineering science predicts failure; inspection only finds it.","cn":"工程科学预测失效，检验只是把它找出来。"},{"en":"The department changed its name from engineering science to mechanical engineering.","cn":"那个系把名字从工程科学改成了机械工程。"},{"en":"Students learn engineering science before they learn to trust a simulation.","cn":"学生先学工程科学，才学会信任仿真结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「恩机捏 ring（engineering）赛恩斯（science）」——工程背后那套赛过直觉的学问，就是工程科学","word":"engineering science"},"root":"拉丁 ingenium「天生才能」→ engine / engineer → engineering；拉丁 scientia「知识」← scire「知道」→ science；十九世纪工程院校把底层理论从车间实务中分出，合成 engineering science。","sensesIntro":{"en":"Eight senses cover the knowledge base, a department, applied physics, a course, modelling research, the middle ground, simulation and a qualification area.","cn":"八个义项涵盖知识基础、院系、应用物理、课程、建模研究、中间地带、仿真与资格领域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a blackboard with equations on one side and a broken specimen on the other, joined by a chalk line.","cn":"核心意象：黑板一边是公式，一边是折断的试件，中间由一道粉笔线相连。"},"chain":["NATURAL LAW","APPLIED MODEL","MATERIAL BEHAVIOUR","DESIGN RULE","ACADEMIC FIELD","PRACTICE"],"branches":[{"senses":"01 · 06","en":"KNOWLEDGE AND ITS ROLE: the supporting body of knowledge, and its position between physics and building.","cn":"知识及其位置：作为支撑的知识体系，以及它处于物理与建造之间的位置。"},{"senses":"02 · 04","en":"TAUGHT FORM: a department with a building, and a course on a timetable.","cn":"教学形态：有楼宇的院系，以及课表上的一门课。"},{"senses":"03 · 07","en":"CONTENT AND COMPUTATION: mechanics with heat and materials, and the simulation that now carries much of it.","cn":"内容与计算：力学连同热与材料，以及如今承载其中许多工作的仿真。"},{"senses":"05","en":"MODELLING RESEARCH: building and checking models against test data.","cn":"建模研究：建立模型并用试验数据检验。"},{"senses":"08","en":"QUALIFICATION: the examined knowledge area for a technical title.","cn":"资格：技术头衔所考核的知识领域。"}]},"affixes":{"intro":{"en":"Engineering science is two nouns side by side. Neither half takes a new affix, but each already carries its own endings.","cn":"engineering science 是两个名词并置而成。两半都没有新增词缀，但各自已带原有词尾。"},"latinIntro":{"en":"Latin supplies ingenium behind engine, and scientia behind science; the English endings -ing and -ence were added before the nouns met.","cn":"拉丁语提供 engine 背后的 ingenium 与 science 背后的 scientia；英语词尾 -ing 与 -ence 在两词相遇前就已加上。"},"items":[{"word":"in-","structure":"in- (Latin prefix)","meaning":"in, within","meaningCN":"在内","example":"It belongs to the Latin noun behind engine.","exampleCN":"它属于 engine 背后的那个拉丁名词。"},{"word":"gignere","structure":"gignere (Latin verb)","meaning":"to beget","meaningCN":"生育；产生","example":"The verb explains the sense of something produced.","exampleCN":"这个动词解释了「被产出之物」的含义。"},{"word":"-ing","structure":"-ing (English abstract noun ending)","meaning":"the field or activity of","meaningCN":"……的领域或活动","example":"The ending turns the builder into a profession.","exampleCN":"这个词尾把建造者变成一门职业。"},{"word":"scire","structure":"scire (Latin verb)","meaning":"to know","meaningCN":"知道","example":"The verb is the source of the second noun.","exampleCN":"这个动词是第二个名词的来源。"},{"word":"scientia","structure":"scientia (Latin noun)","meaning":"knowledge","meaningCN":"知识","example":"The noun names organised knowing.","exampleCN":"这个名词指系统化的知识。"},{"word":"-ence","structure":"-ence (Latin noun ending through French)","meaning":"state or quality","meaningCN":"状态或性质","example":"The ending shapes the English noun science.","exampleCN":"这个词尾塑成英语名词 science。"},{"word":"-tific","structure":"-fic (Latin-derived adjective ending)","meaning":"making, producing","meaningCN":"造成；产生","example":"The ending appears in the related adjective.","exampleCN":"这个词尾出现在相关形容词中。"},{"word":"engineer","structure":"engine plus agent ending","meaning":"one who builds","meaningCN":"建造的人","example":"The person-word sits between engine and engineering.","exampleCN":"人物名词处在 engine 与 engineering 之间。"}],"latinEntries":[{"word":"scientia","structure":"scientia, scientiae (n., first declension)","meaning":"knowledge","meaningCN":"知识"},{"word":"ingenium","structure":"ingenium, ingeni (n., second declension)","meaning":"inborn talent, clever device","meaningCN":"天生才能、巧妙装置"}],"derivatives":[{"word":"engineering","pos":"n.","zh":"工程"},{"word":"science","pos":"n.","zh":"科学"},{"word":"scientific","pos":"adj.","zh":"科学的"},{"word":"engineer","pos":"n.","zh":"工程师"}]}},{"word":"mechanical","ipa_uk":"/mɪˈkænɪkl/","ipa_us":"/məˈkænɪkl/","definition_zh":"机械的；与机器或力学有关的；不加思考的、机械式的","definition_en":"relating to machines or to mechanics; also done by habit without thought","core_image":"一组齿轮咬合着转动，其中一枚缺了齿，仍在原处空转，发出规律的咔嗒声","scene":"打开机壳后，一排齿轮仍在咬合转动，其中一枚缺了齿，却还在原处空转。The lift stopped because a mechanical fault jammed the door, not because of the power cut.","sceneCN":"这里 mechanical 指与机器部件有关的（第 2 个义项：机器部件方面的）；句意：电梯停下是因为机械故障卡住了门，而不是因为停电。","pos":[{"tag":"adj.","zh":"机械的；力学的；机械式的"},{"tag":"n.","zh":"机械部件（罕用，复数形式指机械结构）"}],"collocations":[{"phrase":"mechanical engineering","zh":"机械工程"},{"phrase":"mechanical failure","zh":"机械故障"},{"phrase":"mechanical parts","zh":"机械零件"},{"phrase":"mechanical energy","zh":"机械能"},{"phrase":"mechanical advantage","zh":"机械效益"},{"phrase":"mechanical repetition","zh":"机械的重复"},{"phrase":"mechanical keyboard","zh":"机械键盘"}],"forms":[{"label":"比较级","form":"more mechanical"},{"label":"最高级","form":"most mechanical"},{"label":"副词","form":"mechanically"},{"label":"名词","form":"mechanicalness（罕用）"}],"derivatives":[{"word":"mechanically","pos":"adv.","zh":"机械地"},{"word":"mechanic","pos":"n.","zh":"技工；修理工"},{"word":"mechanics","pos":"n.","zh":"力学"},{"word":"mechanism","pos":"n.","zh":"机构；机制"}],"senses":[{"no":"01","title":"Relating to machines","titleCN":"与机器有关的","definition":"concerning machines or their parts rather than human or electronic action","definitionCN":"涉及机器或其部件，而非人或电子动作","example":"A mechanical clock needs winding once a day.","exampleCN":"机械钟每天要上一次发条。","why":"the adjective was built on the Greek word for a device, so its first job is to mark things of that kind.","whyCN":"这个形容词建在希腊语「装置」一词上，因此首要作用是标记同类事物。"},{"no":"02","title":"Of a machine's working parts","titleCN":"机器工作部件方面的","definition":"describing a fault or action that belongs to moving parts, not to power or software","definitionCN":"描述属于运动部件的故障或动作，而非电力或软件","example":"The mechanic found a mechanical cause for the noise.","exampleCN":"技工找到了噪声的机械原因。","why":"when a system has layers, the adjective isolates the layer of gears, bearings and seals.","whyCN":"当系统分层时，这个形容词专门标出齿轮、轴承与密封件那一层。"},{"no":"03","title":"Belonging to mechanics as a science","titleCN":"属于力学这门科学的","definition":"concerning the study of forces and motion rather than chemistry or electricity","definitionCN":"涉及力与运动的研究，而非化学或电学","example":"The paper sits on the boundary between mechanical and electrical effects.","exampleCN":"那篇论文处在力学效应与电学效应的交界上。","why":"the same Greek root names a branch of physics, and the adjective follows it into the classroom.","whyCN":"同一个希腊词根也命名物理学的一个分支，形容词便随之进入课堂。"},{"no":"04","title":"Automatic, without thought","titleCN":"不假思索的、机械式的","definition":"done by habit or rule with no attention behind it","definitionCN":"凭习惯或规则完成，背后没有留意","example":"His apology sounded mechanical and convinced no one.","exampleCN":"他的道歉听起来很机械，谁也没被说服。","why":"a machine repeats without judging, and human behaviour that repeats without judging borrows the word.","whyCN":"机器重复而不判断，人不判断地重复行为时便借用这个词。"},{"no":"05","title":"Barely varying, routine","titleCN":"几乎不变的、例行公事的","definition":"describing a process that repeats identically with no adjustment","definitionCN":"描述一模一样重复、毫无调整的过程","example":"The grading was mechanical: same comments, different names.","exampleCN":"那次评分很机械：评语都一样，只是名字不同。","why":"repetition without variation is the visible signature of a machine at work.","whyCN":"毫无变化的重复，是机器运转时最显眼的特征。"},{"no":"06","title":"Describing a physical breakdown","titleCN":"指实体的损坏","definition":"used of a failure caused by wear, jam or breakage of parts","definitionCN":"用于因磨损、卡死或断裂造成的失效","example":"Mechanical damage is cheaper to prevent than to repair.","exampleCN":"机械损伤预防起来比修理便宜。","why":"engineers divide failures by cause, and this adjective labels the cause that lives in the hardware.","whyCN":"工程师按原因给故障分类，这个形容词标记住在硬件里的那一类。"},{"no":"07","title":"Of mechanical advantage","titleCN":"机械效益意义上的","definition":"concerning the ratio by which a tool multiplies force","definitionCN":"涉及工具放大力量的比值","example":"A lever gives mechanical gain at the cost of distance.","exampleCN":"杠杆以距离为代价换取机械上的增益。","why":"the science of mechanics measures how tools multiply force, and that measure carries the adjective.","whyCN":"力学测量工具如何放大力量，这一测量便带着这个形容词。"},{"no":"08","title":"Of reproduction by machine","titleCN":"机器复制意义上的","definition":"describing copies made by a device rather than by hand","definitionCN":"描述由装置而非手工做出的复制","example":"Mechanical copies of the print are worth far less than the original.","exampleCN":"那幅版画的机械复制品比原作便宜得多。","why":"the age of printed multiples made the word a standard label for copies a machine produces.","whyCN":"印刷复制品的时代让这个词成了机器所产副本的标准标签。"},{"no":"09","title":"Of a device's touch and feel","titleCN":"设备手感层面的","definition":"describing switches or keys that act through physical parts","definitionCN":"描述通过实体部件动作的开关或按键","example":"She still prefers a mechanical switch for typing.","exampleCN":"打字时她仍偏爱机械开关。","why":"users distinguish a real moving part from a touch surface, and the old adjective draws the line.","whyCN":"用户要区分真正的运动部件与触摸表面，旧形容词正好划出这条线。"},{"no":"10","title":"Drawn with instruments","titleCN":"用仪器绘制的","definition":"describing technical drawing done with rulers and compasses rather than freehand","definitionCN":"描述用直尺与圆规而非徒手完成的技术制图","example":"The old course began with mechanical drawing before design.","exampleCN":"那门旧课程先教机械制图，再教设计。","why":"before printing, precision came from instruments, and drawing by instrument took the adjective's name.","whyCN":"在印刷之前，精确来自仪器，用仪器绘图便取了这个形容词的名字。"}],"etymology":{"intro":{"en":"Mechanical comes from Greek mekhane, a device or means, through Latin mechanicus. The adjective first meant belonging to machines and later came to mean unthinking.","cn":"mechanical 来自希腊语 mekhane「装置、手段」，经拉丁语 mechanicus 而来。形容词最初指「属于机器的」，后来引申为「不加思考的」。"},"items":[{"era":"GREEK MEKHANE","en":"Greek mekhane meant a machine, a device or a means of doing something, and mekhos meant a means or expedient.","cn":"希腊语 mekhane 指机器、装置或做事的手段，mekhos 指手段或办法。"},{"era":"GREEK MEKHANIKOS","en":"The adjective mekhanikos described what belongs to devices or to inventive skill.","cn":"形容词 mekhanikos 描述属于装置或属于巧思技艺的事物。"},{"era":"LATIN MECHANICUS","en":"Latin mechanicus kept the Greek sense and was used of mechanical arts and of engineers.","cn":"拉丁语 mechanicus 保留希腊含义，用于机械技艺与工程人员。"},{"era":"ENGLISH MECHANICAL","en":"English mechanical first meant of machines and of the science of mechanics, with no hint of dullness.","cn":"英语 mechanical 最初指机器与力学，还没有「呆板」的暗示。"},{"era":"MECHANICS","en":"Newtonian mechanics made the adjective the standard label for force and motion, and the noun mechanics followed.","cn":"牛顿力学让这个形容词成为力与运动的标准标签，名词 mechanics 随后出现。"},{"era":"MODERN FIGURATIVE","en":"Industry and bureaucracy made repetition visible, and the adjective acquired its modern meaning of acting without thought.","cn":"工业与官僚制度让重复变得显眼，这个形容词于是获得「不假思索」的现代含义。"}]},"similar":{"note":{"en":"The first group is the same machine root in other shapes; the second group is the neighbouring words for automatic and machine-made.","cn":"第一组是同一「机器」词根的其他形式；第二组是「自动」与「机器制造」的相邻说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mechanic","ipa":"/məˈkænɪk/","tag":"the person","definition":"One who repairs machines; the adjective describes what belongs to machines.","definitionCN":"指修理机器的人；形容词描述属于机器的事物。"},{"word":"mechanics","ipa":"/məˈkænɪks/","tag":"the science","definition":"The study of forces and motion; the adjective's third sense points to it.","definitionCN":"研究力与运动的学问；形容词的第三个义项指向它。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"the arrangement","definition":"The assembly of parts that produces an action; the adjective describes such parts.","definitionCN":"指产生某个动作的部件组合；形容词描述这类部件。"},{"word":"mechanically","ipa":"/məˈkænɪkli/","tag":"the adverb","definition":"In a machine-like or unthinking way; it tells how something is done.","definitionCN":"以机器般或不假思索的方式；它说明做事的方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"automatic","ipa":"/ˌɔːtəˈmætɪk/","tag":"self-acting","definition":"Working by itself once set going; mechanical stresses the parts, automatic stresses the lack of a hand.","definitionCN":"一旦启动便自行工作；mechanical 强调部件，automatic 强调不需人手。"},{"word":"manual","ipa":"/ˈmænjuəl/","tag":"by hand","definition":"Done with the hands; it is the direct opposite of mechanical action.","definitionCN":"用手完成的；是机械动作的直接对立面。"},{"word":"routine","ipa":"/ˈruːtiːn/","tag":"habitual repetition","definition":"Regular and unvarying; routine describes the pattern, mechanical describes the absence of thought.","definitionCN":"规律而少变化；routine 描述模式，mechanical 描述缺少思考。"},{"word":"robotic","ipa":"/rəʊˈbɒtɪk/","tag":"machine-like behaviour","definition":"Stiff and emotionless in manner; a modern synonym for the figurative sense of mechanical.","definitionCN":"举止僵硬而无感情；是 mechanical 比喻义的现代同义说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real Greek root and the real technical phrases.","cn":"正常联想：来自真实希腊词根与真实技术搭配。"},"normal":[{"en":"Mekhane is a device, so mechanical means device-like before it means unthinking.","cn":"mekhane 是装置，所以 mechanical 先表示「像装置的」，再表示「不假思索的」。"},{"en":"The family is regular: mechanic, mechanics, mechanism, mechanically.","cn":"词族很整齐：mechanic、mechanics、mechanism、mechanically。"},{"en":"Fixed phrases split the senses: mechanical failure, mechanical advantage, mechanical repetition.","cn":"固定搭配分开义项：机械故障、机械效益、机械的重复。"},{"en":"The adverb ends in -ly, and the comparison uses more and most.","cn":"副词以 -ly 结尾，比较级用 more 与 most。"},{"en":"It contrasts with manual, which is the hand against the gear.","cn":"它与 manual 相对：一只手对着一个齿轮。"}],"abstract":[{"en":"Picture a gear with one tooth missing, still turning because nothing has told it to stop.","cn":"想象一枚缺了齿的齿轮还在转，因为没人告诉它该停。"},{"en":"Picture a hand that apologises on a schedule, never looking up.","cn":"想象一只手按时间表道歉，从不抬头。"},{"en":"Picture a drawing so straight that the ruler is still visible in the ink.","cn":"想象一张画得极直的图，墨迹里还看得见尺子。"}]},"examples":[{"en":"Mechanical wear, not bad code, caused the shutdown.","cn":"造成停机的是机械磨损，而不是糟糕的代码。"},{"en":"His replies were polite but entirely mechanical.","cn":"他的回答礼貌，却完全是机械式的。"},{"en":"Mechanical drawings from that era still guide the repair shop.","cn":"那个年代的机械制图至今仍指导着修理车间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「米（me）卡（cha）你扣（ni-cal）」——米粒卡住你扣动的地方，正是机械出了毛病","word":"mechanical"},"root":"希腊 mekhane「装置、手段」→ mekhanikos「装置的」→ 拉丁 mechanicus → 英语 mechanical；力学义随牛顿力学固定，比喻义「不假思索」起于近代工业与官僚重复。","sensesIntro":{"en":"Ten senses move from machines to their working parts, the science of mechanics, unthinking habit, routine, breakdown, force ratios, machine copies, the feel of a switch and instrument drawing.","cn":"十个义项从机器出发，经过工作部件、力学、不假思索、例行重复、损坏、力比、机器复制、开关手感，最后到仪器制图。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of meshing gears, one tooth missing, still turning and clicking in place.","cn":"核心意象：一排咬合的齿轮，其中一枚缺了齿，仍在原处转动并咔嗒作响。"},"chain":["DEVICE","MOVING PARTS","FORCE AND MOTION","AUTOMATIC ACTION","REPETITION","WITHOUT THOUGHT"],"branches":[{"senses":"01 · 02","en":"MACHINE AND PARTS: things of that kind, and specifically the moving layer inside a system.","cn":"机器与部件：同类事物，以及系统中运动的那一层。"},{"senses":"03 · 07","en":"SCIENCE OF FORCE: mechanics as a subject, and the measured gain a tool gives.","cn":"力的科学：作为学科的力学，以及工具提供的可测增益。"},{"senses":"04 · 05","en":"AUTOMATISM: acting without attention, and repeating without variation.","cn":"自动性：不留神地行动，以及毫无变化地重复。"},{"senses":"06 · 09","en":"HARDWARE IN THE WORLD: physical breakdown, and the feel of a real moving switch.","cn":"现实中的硬件：实体损坏，以及真实运动开关的手感。"},{"senses":"08 · 10","en":"MADE BY INSTRUMENT: copies produced by a machine, and drawings produced by a ruler.","cn":"由器械造成：机器生产的复制品，以及用尺规画出的图纸。"}]},"affixes":{"intro":{"en":"Mechanical is a Greek adjective ending on a Greek noun; English later added -ly for the adverb and -s for the science noun.","cn":"mechanical 是希腊名词加希腊形容词词尾；英语后来又加 -ly 成副词、加 -s 成学科名词。"},"latinIntro":{"en":"Latin mechanicus is the borrowing that carried the Greek adjective into European languages; the ending -ical reached English through French forms.","cn":"拉丁语 mechanicus 是把希腊形容词带入欧洲语言的借词；词尾 -ical 经法语形式进入英语。"},"items":[{"word":"mekhane","structure":"mekhane (Greek noun)","meaning":"machine, device, means","meaningCN":"机器；装置；手段","example":"The noun is the source of the whole family.","exampleCN":"这个名词是整个词族的源头。"},{"word":"mekhanikos","structure":"mekhanikos (Greek adjective)","meaning":"of devices, inventive","meaningCN":"装置的；有巧思的","example":"The adjective supplies the ending that English kept.","exampleCN":"这个形容词提供英语所保留的词尾。"},{"word":"-ical","structure":"-ical (adjective ending through Latin and French)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending marks an adjective of relation.","exampleCN":"这个词尾标记关系形容词。"},{"word":"-ics","structure":"-ics (Greek-derived noun ending)","meaning":"the study of","meaningCN":"……学","example":"The ending turns the adjective's field into a science.","exampleCN":"这个词尾把形容词所指领域变成一门学问。"},{"word":"-ism","structure":"-ism (Greek-derived noun ending)","meaning":"system or arrangement","meaningCN":"体系或结构","example":"The ending builds the word for an assembly of parts.","exampleCN":"这个词尾构成「部件组合」的名称。"},{"word":"-ly","structure":"-ly (English adverb ending)","meaning":"in that manner","meaningCN":"以那种方式","example":"The adverb describes the manner of action.","exampleCN":"副词描述动作的方式。"},{"word":"mechanic","structure":"mechanicus used as a noun","meaning":"one skilled with machines","meaningCN":"擅长机器的人","example":"Latin used the adjective as a name for a worker.","exampleCN":"拉丁语把这个形容词用作工人的名称。"},{"word":"manus","structure":"manus (Latin noun)","meaning":"hand","meaningCN":"手","example":"The Latin word for hand is the base of the direct opposite.","exampleCN":"拉丁语「手」是它的直接对立词的词基。"}],"latinEntries":[{"word":"mechanicus","structure":"mechanicus, mechanica, mechanicum (adj., first and second declension, from Greek)","meaning":"of machines, mechanical","meaningCN":"机器的；机械的"}],"derivatives":[{"word":"mechanically","pos":"adv.","zh":"机械地"},{"word":"mechanic","pos":"n.","zh":"技工"},{"word":"mechanics","pos":"n.","zh":"力学"},{"word":"mechanism","pos":"n.","zh":"机构；机制"}]}},{"word":"mechanical engineering","ipa_uk":"/mɪˈkænɪkl ˌendʒɪˈnɪərɪŋ/","ipa_us":"/məˈkænɪkl ˌendʒɪˈnɪərɪŋ/","definition_zh":"机械工程；设计、制造与维护机器及动力系统的工程分支","definition_en":"the branch of engineering that designs, builds and maintains machines, mechanisms and power systems","core_image":"车间里立着一台拆开的发动机，旁边摊着热力学图表与零件清单，工程师正把两者对照","scene":"车间里立着一台拆开的发动机，旁边摊着图表与零件清单，有人正把两者逐一对照。Mechanical engineering turned the noisy engine into a quieter one without losing power.","sceneCN":"这里 mechanical engineering 指设计、制造与维护机器及动力系统的工程分支（第 1 个义项：这一分支）；句意：机械工程把那台吵闹的发动机改得更安静，却没有损失动力。","pos":[{"tag":"n.","zh":"机械工程；机械工程学（作定语）"}],"collocations":[{"phrase":"mechanical engineering degree","zh":"机械工程学位"},{"phrase":"mechanical engineering department","zh":"机械工程系"},{"phrase":"mechanical engineering firm","zh":"机械工程公司"},{"phrase":"study mechanical engineering","zh":"学习机械工程"},{"phrase":"mechanical engineering design","zh":"机械工程设计"}],"forms":[{"label":"复合名词","form":"mechanical engineering"}],"derivatives":[{"word":"mechanical","pos":"adj.","zh":"机械的"},{"word":"mechanic","pos":"n.","zh":"技工"},{"word":"mechanics","pos":"n.","zh":"力学"},{"word":"mechatronics","pos":"n.","zh":"机电一体化"}],"senses":[{"no":"01","title":"The branch that designs machines","titleCN":"设计机器的工程分支","definition":"the division of engineering concerned with machines, their parts and their motion","definitionCN":"工程中负责机器、其部件及其运动的门类","example":"Mechanical engineering begins where parts have to move without breaking.","exampleCN":"机械工程从「部件必须动而不坏」这一点开始。","why":"the compound narrows a wide profession to the part that deals with moving hardware.","whyCN":"这个复合词把宽泛的行业收窄到处理运动硬件的那一部分。"},{"no":"02","title":"The profession of its practitioners","titleCN":"从业者组成的职业","definition":"the work and career of the engineers who practise this branch","definitionCN":"从事这一分支的工程师的工作与职业","example":"Mechanical engineering kept the factory running through two recessions.","exampleCN":"机械工程让那家工厂熬过了两次衰退。","why":"a branch is also a body of people, and the phrase names their livelihood.","whyCN":"分支同时也是一群人，这个短语就指他们的生计。"},{"no":"03","title":"The practice of designing power and motion","titleCN":"设计动力与运动系统的实务","definition":"the applied work of sizing motors, shafts, bearings and transmissions","definitionCN":"确定电机、轴、轴承与传动尺寸的应用工作","example":"Mechanical engineering chose the bearing that outlasted the warranty.","exampleCN":"机械工程选用了寿命超过保修期的轴承。","why":"the discipline's daily decisions are about power and motion, so the phrase often means that practice.","whyCN":"这门学问的日常决策围绕动力与运动，因此短语常指这项实务。"},{"no":"04","title":"A university department and degree","titleCN":"大学的院系与学位","definition":"the academic unit and programme that teach the branch","definitionCN":"讲授这一分支的学术单位与培养项目","example":"The mechanical engineering department opened a new heat lab.","exampleCN":"机械工程系新开了一间热学实验室。","why":"codified knowledge taught in one place becomes an institution with a name.","whyCN":"被整理的知识在一处讲授，就变成有名目的建制。"},{"no":"05","title":"An industry sector","titleCN":"一个产业部门","definition":"the firms that build machines and mechanical systems for a market","definitionCN":"为市场制造机器与机械系统的公司群体","example":"Mechanical engineering employs a third of the town.","exampleCN":"机械工程养活了镇上三分之一的人。","why":"a profession counted in output and jobs becomes a sector in economic language.","whyCN":"被按产值与岗位统计的职业，在经济语言里就成了产业部门。"},{"no":"06","title":"Thermodynamics and machine theory","titleCN":"热力学与机械原理","definition":"the core knowledge of heat, energy and mechanisms that the branch rests on","definitionCN":"该分支所依托的热、能量与机构的核心知识","example":"Mechanical engineering still rewards those who understand cycles.","exampleCN":"机械工程仍然厚待懂循环过程的人。","why":"the branch's identity is fixed by the sciences it applies, especially heat and mechanism.","whyCN":"这一分支的身份由它所应用的学问固定，尤其是热与机构。"},{"no":"07","title":"Manufacturing system design","titleCN":"制造系统的设计","definition":"the planning of production machines and the lines that link them","definitionCN":"规划生产机器以及连接它们的产线","example":"Mechanical engineering laid out the line before the robots arrived.","exampleCN":"机械工程在机器人到来之前就排好了产线。","why":"machines are rarely alone, and arranging them into a working line belongs to the same branch.","whyCN":"机器很少孤立存在，把它们排成能运转的产线也属同一分支。"},{"no":"08","title":"A curriculum of study","titleCN":"一套课程体系","definition":"the sequence of courses that turns a student into a practitioner","definitionCN":"把学生培养成从业者的课程序列","example":"The curriculum in mechanical engineering moved drafting into the first term.","exampleCN":"机械工程的课程把制图挪到了第一学期。","why":"the taught order of the branch is itself called by its name.","whyCN":"这一分支的教学顺序本身也用它的名字来称呼。"}],"etymology":{"intro":{"en":"Mechanical engineering joins a Greek word for device with a French-shaped word for the building profession. The phrase names the oldest of the engineering branches.","cn":"mechanical engineering 把希腊语「装置」与法语形态的「建造行业」拼在一起。这个短语命名了工程中最古老的分支。"},"items":[{"era":"GREEK MEKHANE","en":"Greek mekhane meant device or means, and its adjective mekhanikos passed through Latin as mechanicus.","cn":"希腊语 mekhane 指装置或手段，其形容词 mekhanikos 经拉丁语成为 mechanicus。"},{"era":"ENGLISH MECHANICAL","en":"English mechanical named what belongs to machines and to the science of force and motion.","cn":"英语 mechanical 指属于机器以及力与运动的学问。"},{"era":"LATIN INGENIUM TO ENGINE","en":"Engine, from ingenium, meant a contrivance before it meant a motor, and its builders were the first engineers.","cn":"engine 来自 ingenium，先指巧妙装置，后指发动机，其建造者是最早的工程师。"},{"era":"EIGHTEENTH-CENTURY PROFESSION","en":"Engineering became a profession with canals, roads and steam, and machine work became its largest branch.","cn":"随着运河、道路与蒸汽，工程成为职业，机器工作成为其中最大的分支。"},{"era":"NINETEENTH-CENTURY NAME","en":"Technical schools separated machine building from civil works, and the compound became the branch's fixed name.","cn":"技术学校把机器制造与土木分开，这个复合词就成了该分支的固定名称。"},{"era":"MODERN SCOPE","en":"The branch later absorbed thermodynamics, control and manufacturing systems while keeping the old name.","cn":"这一分支后来吸收热力学、控制与制造系统，却保留了旧名称。"}]},"similar":{"note":{"en":"The first group is the words inside the phrase and their close forms; the second group is neighbouring engineering branches.","cn":"第一组是短语内部的词及其近形；第二组是相邻的工程分支。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mechanical","ipa":"/məˈkænɪkl/","tag":"the adjective alone","definition":"Belonging to machines or done without thought; alone it does not name a branch of study.","definitionCN":"指属于机器或不假思索；单独用时并不指某个学科分支。"},{"word":"mechanical engineer","ipa":"/məˈkænɪkl ˌendʒɪˈnɪə/","tag":"the person","definition":"The practitioner of the branch; the phrase names the field rather than its worker.","definitionCN":"指这一分支的从业者；短语指领域而非从业者。"},{"word":"engineering","ipa":"/ˌendʒɪˈnɪərɪŋ/","tag":"the whole profession","definition":"The general field; the compound selects the machine-building part of it.","definitionCN":"指整个行业；复合词选取其中造机器的部分。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"an object of study","definition":"An assembly of moving parts; it is one of the things this branch designs.","definitionCN":"指运动部件的组合；它是这一分支所设计的东西之一。"}]},{"heading":"NEAR MEANING","entries":[{"word":"civil engineering","ipa":"/ˈsɪvl ˌendʒɪˈnɪərɪŋ/","tag":"the sibling branch","definition":"The branch for roads, bridges and buildings; both trace back to the same profession.","definitionCN":"负责道路、桥梁与建筑的分支；两者都出自同一行业。"},{"word":"electrical engineering","ipa":"/ɪˈlektrɪkl ˌendʒɪˈnɪərɪŋ/","tag":"the power cousin","definition":"The branch for electrical systems; machines often need both branches at once.","definitionCN":"负责电气系统的分支；机器常常同时需要两个分支。"},{"word":"mechatronics","ipa":"/mekəˈtrɒnɪks/","tag":"machines plus control","definition":"The joining of machine design with electronics and control; a later blend beside the older branch.","definitionCN":"把机械设计与电子、控制结合；是旧分支旁边较晚的混合领域。"},{"word":"industrial engineering","ipa":"/ɪnˈdʌstriəl ˌendʒɪˈnɪərɪŋ/","tag":"systems and people","definition":"The design of production systems and work methods rather than the machines themselves.","definitionCN":"设计生产系统与工作方法，而不是机器本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the two real halves and the real academic phrases.","cn":"正常联想：来自两个真实构件与真实学术搭配。"},"normal":[{"en":"Mekhane is a device and ingenium is talent, so the phrase is device work done by trained talent.","cn":"mekhane 是装置，ingenium 是才能，所以这个短语是「由受过训练的才能所做的装置工作」。"},{"en":"It is the branch that deals with things that move and can break.","cn":"它是处理「会动、也会坏」的东西的那个分支。"},{"en":"Fixed phrases: mechanical engineering degree, mechanical engineering department.","cn":"固定搭配：机械工程学位、机械工程系。"},{"en":"Its sibling branches are civil and electrical, and the three often share a project.","cn":"它的兄弟分支是土木与电气，三者常常共用同一个项目。"},{"en":"The person is a mechanical engineer; the field keeps the longer phrase.","cn":"人叫 mechanical engineer，领域则用更长的短语。"}],"abstract":[{"en":"Picture an engine opened like a book, its diagrams laid beside the parts they describe.","cn":"想象一台发动机像书一样被翻开，图表摊在它所描述的零件旁边。"},{"en":"Picture a bearing that quietly outlives every promise made about it.","cn":"想象一枚轴承，静静地比所有关于它的承诺活得都久。"},{"en":"Picture a factory line drawn on paper years before the machines arrive.","cn":"想象一条在机器到来数年前就画在纸上的产线。"}]},"examples":[{"en":"Mechanical engineering solved the vibration by changing a single bearing.","cn":"机械工程换了一枚轴承就解决了振动问题。"},{"en":"She chose mechanical engineering because she wanted to hold what she designed.","cn":"她选择机械工程，因为她想亲手拿起自己设计的东西。"},{"en":"The department merged mechanical engineering with materials science.","cn":"那个系把机械工程与材料科学合并了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「米卡你扣（mechanical）恩机捏 ring（engineering）」——米粒卡住扣子的地方，正是机械工程要修的地方","word":"mechanical engineering"},"root":"希腊 mekhane「装置」→ mechanicus → mechanical；拉丁 ingenium「才能」→ engine → engineer → engineering；十九世纪技术学校分科后合成 mechanical engineering。","sensesIntro":{"en":"Eight senses cover the branch, its practitioners, power-and-motion practice, the department, the sector, core theory, production lines and the curriculum.","cn":"八个义项涵盖分支本身、从业者、动力与运动实务、院系、产业、核心理论、产线与课程。"},"semanticMap":{"core":{"en":"CORE IMAGE: an opened engine beside heat charts and a parts list, being checked item by item.","cn":"核心意象：一台拆开的发动机旁边摊着热学图表与零件清单，正被逐项核对。"},"chain":["FORCE AND MOTION","MACHINE DESIGN","POWER SYSTEM","MANUFACTURE","PROFESSION","INDUSTRY"],"branches":[{"senses":"01 · 06","en":"BRANCH AND THEORY: the division itself, and the heat-and-mechanism knowledge it rests on.","cn":"分支与理论：这一门类本身，以及它所依托的热与机构知识。"},{"senses":"02 · 08","en":"PEOPLE AND TEACHING: the practitioners' livelihood, and the course sequence that produces them.","cn":"人与教学：从业者的生计，以及培养他们的课程序列。"},{"senses":"03","en":"POWER AND MOTION PRACTICE: sizing motors, shafts, bearings and drives.","cn":"动力与运动实务：确定电机、轴、轴承与传动的尺寸。"},{"senses":"04","en":"INSTITUTION: a department and a degree with a fixed name.","cn":"建制：有名目的院系与学位。"},{"senses":"05 · 07","en":"SCALE AND ARRANGEMENT: an economic sector on one side, production lines on the other.","cn":"规模与安排：一边是产业部门，一边是生产产线。"}]},"affixes":{"intro":{"en":"The phrase is two nouns, each already formed; joining them adds no affix but narrows a profession to one branch.","cn":"这个短语由两个已成形名词组成；并置不添加词缀，只是把行业收窄为一个分支。"},"latinIntro":{"en":"Greek mekhane reaches English through Latin mechanicus, and Latin ingenium through French engin; the English endings -ical and -ing close both halves.","cn":"希腊语 mekhane 经拉丁语 mechanicus 进入英语，拉丁语 ingenium 经法语 engin 进入英语；两半各以英语词尾 -ical 与 -ing 收束。"},"items":[{"word":"mekhane","structure":"mekhane (Greek noun)","meaning":"device, means","meaningCN":"装置；手段","example":"The noun is the source of the first half.","exampleCN":"这个名词是第一半的来源。"},{"word":"-ical","structure":"-ical (adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes the first half an adjective.","exampleCN":"这个词尾把前半变成形容词。"},{"word":"ingenium","structure":"ingenium (Latin noun)","meaning":"inborn talent; a device","meaningCN":"天生才能；装置","example":"The noun sits behind the second half.","exampleCN":"这个名词位于后半的背后。"},{"word":"engine","structure":"engine (English noun)","meaning":"machine, motor","meaningCN":"机器；发动机","example":"The intermediate form links talent to machinery.","exampleCN":"这个中间形式把才能与机械连起来。"},{"word":"-eer","structure":"-eer (agent ending)","meaning":"one who works with","meaningCN":"从事……的人","example":"The ending marks the practitioner.","exampleCN":"这个词尾标记从业者。"},{"word":"-ing","structure":"-ing (English abstract noun ending)","meaning":"the field or activity","meaningCN":"领域或活动","example":"The ending turns the practitioner into a profession.","exampleCN":"这个词尾把从业者变成一门职业。"},{"word":"thermo-","structure":"thermo- (Greek prefix)","meaning":"heat","meaningCN":"热","example":"The prefix marks the heat side of the branch.","exampleCN":"这个前缀标记该分支的热学一面。"},{"word":"mechano-","structure":"mechano- (Greek combining form)","meaning":"machine","meaningCN":"机器","example":"The form appears in names of machine-based fields.","exampleCN":"这个构词成分出现在以机器为基础的领域名称中。"}],"latinEntries":[{"word":"mechanicus","structure":"mechanicus, mechanica, mechanicum (adj., from Greek)","meaning":"of machines","meaningCN":"机器的"}],"derivatives":[{"word":"mechanical","pos":"adj.","zh":"机械的"},{"word":"mechanic","pos":"n.","zh":"技工"},{"word":"mechanics","pos":"n.","zh":"力学"},{"word":"mechatronics","pos":"n.","zh":"机电一体化"}]}},{"word":"machinery","ipa_uk":"/məˈʃiːnəri/","ipa_us":"/məˈʃiːnəri/","definition_zh":"机械；机器的总称；也指机构或运作体系","definition_en":"machines taken as a group, or the working parts of a system, including an organisation's apparatus","core_image":"一排机器连着同一条传动轴，皮带一起转动，整片地面都在轻微震动","scene":"车间里一排机器连着同一条传动轴，皮带一齐转动，整片地面都在轻轻震动。The factory replaced its old machinery with one quieter line.","sceneCN":"这里 machinery 指机器的总称（第 1 个义项：成套机器）；句意：工厂把旧机械换成了一条更安静的产线。","pos":[{"tag":"n.","zh":"机械（总称）；机器部件；机构"}],"collocations":[{"phrase":"heavy machinery","zh":"重型机械"},{"phrase":"agricultural machinery","zh":"农业机械"},{"phrase":"industrial machinery","zh":"工业机械"},{"phrase":"the machinery of government","zh":"政府机构"},{"phrase":"operate machinery","zh":"操作机械"},{"phrase":"machinery noise","zh":"机械噪声"}],"forms":[{"label":"不可数名词","form":"machinery"}],"derivatives":[{"word":"machine","pos":"n./v.","zh":"机器；机械加工"},{"word":"mechanic","pos":"n.","zh":"技工"},{"word":"mechanism","pos":"n.","zh":"机构"},{"word":"machinist","pos":"n.","zh":"机械操作工"}],"senses":[{"no":"01","title":"Machines as a collective body","titleCN":"作为整体的机器","definition":"a group of machines considered together, especially in a workplace","definitionCN":"被一并看待的一组机器，尤指工作场所中的","example":"The plant bought new machinery before hiring new staff.","exampleCN":"工厂先买新机械，再招新员工。","why":"the -ery ending makes a mass noun, so the word names machines as a body rather than one machine.","whyCN":"-ery 词尾构成集合名词，因此这个词指一批机器，而不是一台机器。"},{"no":"02","title":"The working parts inside a machine","titleCN":"机器内部的运转部件","definition":"the internal parts that transmit motion in a device","definitionCN":"在装置内部传递运动的部件","example":"The clock's machinery needed oil, not a new face.","exampleCN":"这座钟的机械部件需要上油，而不是换表盘。","why":"the collective noun also covers the parts that make one machine work, since they too are a set.","whyCN":"集合名词也指使单台机器运转的那组部件，因为它们同样成组。"},{"no":"03","title":"The apparatus of an organisation","titleCN":"组织运作的机构","definition":"the people, offices and procedures that keep an institution running","definitionCN":"维持一个机构运转的人员、部门与程序","example":"Reform stalled inside the machinery of the ministry.","exampleCN":"改革在部委的机构内部停住了。","why":"an organisation works through parts that transmit decisions, exactly as gears transmit motion.","whyCN":"组织靠传递决定的部件运作，正如齿轮传递运动。"},{"no":"04","title":"A process treated as a system","titleCN":"被当作系统看待的流程","definition":"the arrangeable steps by which something is carried out","definitionCN":"完成某事时可加以安排的那些步骤","example":"The machinery of appeal is slow but predictable.","exampleCN":"申诉的运作机制缓慢，却可预期。","why":"once steps are regular enough to be described, they can be spoken of as machinery.","whyCN":"当步骤规律到可以被描述，人们就会把它说成机械装置。"},{"no":"05","title":"Farm equipment as a class","titleCN":"作为一类的农业装备","definition":"the tractors and implements used in farming, taken together","definitionCN":"农业中使用的拖拉机与农具的总和","example":"Shared machinery let small farms afford a harvester.","exampleCN":"共用机械让小农场也买得起收割机。","why":"the collective noun is the natural way to speak of a category of equipment bought and kept together.","whyCN":"集合名词是谈论「成套购买与保管」的设备类别的自然方式。"},{"no":"06","title":"Stage and studio equipment","titleCN":"舞台与演播设备","definition":"the rigging and devices that move scenery or sets","definitionCN":"移动布景或场地的吊装与装置","example":"The theatre's machinery was hidden behind the curtain.","exampleCN":"剧院的舞台机械藏在幕布之后。","why":"theatre has used hidden devices for centuries, and the collective word names them without exposure.","whyCN":"剧院使用隐蔽装置已有数百年，集合名词正好不必把它们露出来。"},{"no":"07","title":"The mechanism of an abstract force","titleCN":"抽象力量的运作机制","definition":"the system by which a large process such as war or law is conducted","definitionCN":"战争或法律等大型过程得以进行的系统","example":"The machinery of war outlived the government that built it.","exampleCN":"战争的机器比建立它的政府活得更久。","why":"the figurative use extends to anything vast, impersonal and hard to stop.","whyCN":"比喻用法延伸到一切庞大、非人格且难以停止的事物。"},{"no":"08","title":"Heavy equipment on a site","titleCN":"工地上的重型设备","definition":"the excavators and cranes that do the heavy physical work","definitionCN":"从事繁重体力作业的挖掘机与起重机","example":"Heavy machinery arrived before the surveyors finished.","exampleCN":"重型机械在测量员完工之前就进场了。","why":"on a site, the word means the class of large powered equipment, not a single tool.","whyCN":"在工地上，这个词指大型动力设备这一类别，而不是单件工具。"}],"etymology":{"intro":{"en":"Machinery is a collective noun built on machine, which comes from Greek mekhane through Latin machina and French. The -ery ending turns one device into a body of devices.","cn":"machinery 是在 machine 上构成的集合名词，而 machine 经拉丁语 machina 与法语来自希腊语 mekhane。-ery 词尾把一台装置变成一批装置。"},"items":[{"era":"GREEK MEKHANE","en":"Greek mekhane meant a device, an engine of war or a means of doing something.","cn":"希腊语 mekhane 指装置、攻城器械或做事的手段。"},{"era":"LATIN MACHINA","en":"Latin machina named a structure, scaffold or engine, and kept the Greek sense of a contrivance.","cn":"拉丁语 machina 指结构、脚手架或器械，保留了希腊语「巧妙装置」的意思。"},{"era":"FRENCH MACHINE","en":"French machine carried the word into English in the seventeenth century, at first for any structure or device.","cn":"法语 machine 在十七世纪把这个词带入英语，最初指任何结构或装置。"},{"era":"ENGLISH MACHINE","en":"English machine narrowed toward powered devices as steam and industry spread.","cn":"随着蒸汽与工业扩散，英语 machine 逐渐收窄为动力装置。"},{"era":"ENGLISH -ERY","en":"The ending -ery, from French -erie, gathers things into a mass or a trade, giving machinery, cutlery and stationery.","cn":"词尾 -ery 来自法语 -erie，把事物聚成整体或行业，形成 machinery、cutlery、stationery 这类词。"},{"era":"MODERN FIGURATIVE","en":"Bureaucracy and warfare gave the collective word its modern figurative sense of an impersonal working system.","cn":"官僚制度与战争给了这个集合词现代比喻义：非人格的运作系统。"}]},"similar":{"note":{"en":"The first group is the machine root in different shapes and counts; the second group is the neighbouring collective and system words.","cn":"第一组是「机器」词根的不同形态与单复数；第二组是相邻的集合与系统说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"machine","ipa":"/məˈʃiːn/","tag":"one count noun","definition":"A single device; machinery is the mass of such devices, so it takes no plural.","definitionCN":"指单台装置；machinery 是这类装置的整体，因此没有复数。"},{"word":"machinist","ipa":"/məˈʃiːnɪst/","tag":"the operator","definition":"The person who runs a machine; the collective noun names the equipment, not the worker.","definitionCN":"指操作机器的人；集合名词指设备，不指工人。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"one assembly","definition":"A particular arrangement of parts that produces motion; machinery is the wider set.","definitionCN":"指产生运动的某套部件组合；machinery 是更大的集合。"},{"word":"mechanical","ipa":"/məˈkænɪkl/","tag":"the adjective","definition":"Of machines or done without thought; the noun machinery carries only the equipment sense.","definitionCN":"指机器的或不假思索的；名词 machinery 只保留设备义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"equipment","ipa":"/ɪˈkwɪpmənt/","tag":"general collective","definition":"Any set of items needed for a purpose; machinery is specifically powered machines.","definitionCN":"为某目的所需的一整套物件；machinery 特指动力机器。"},{"word":"apparatus","ipa":"/əˈpærətəs/","tag":"structure and function","definition":"A set of parts working together for a function, often in science or politics.","definitionCN":"为一功能共同运作的一整套部件，常用于科学或政治语境。"},{"word":"system","ipa":"/ˈsɪstəm/","tag":"the abstract reading","definition":"An organised set of parts or steps; machinery is the concrete or institutional version.","definitionCN":"有组织的部件或步骤集合；machinery 是其具体或建制化的版本。"},{"word":"plant","ipa":"/plɑːnt/","tag":"industrial whole","definition":"The buildings and machines of an industrial site taken as one unit.","definitionCN":"把一个工业场所的建筑与机器当作一个整体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real suffix and the real collective phrases.","cn":"正常联想：来自真实词尾与真实集合搭配。"},"normal":[{"en":"The -ery ending makes a mass noun, as in cutlery and stationery.","cn":"-ery 词尾构成集合名词，如 cutlery、stationery。"},{"en":"It takes no plural: one says much machinery, not many machineries.","cn":"它没有复数：说 much machinery，而不说 many machineries。"},{"en":"Fixed phrases: heavy machinery, agricultural machinery, industrial machinery.","cn":"固定搭配：重型机械、农业机械、工业机械。"},{"en":"The figurative sense needs a system: the machinery of government, the machinery of justice.","cn":"比喻义要接一个体系：政府机构、司法机制。"},{"en":"One machine is a machine; a hall full of them is machinery.","cn":"一台叫 a machine，一屋子就是 machinery。"}],"abstract":[{"en":"Picture a single shaft running through a whole hall, so that every machine turns at once.","cn":"想象一根轴穿过整个车间，于是所有机器同时转动。"},{"en":"Picture an office where decisions travel along belts nobody can see.","cn":"想象一间办公室，决定沿着看不见的皮带传递。"},{"en":"Picture stage rigging moving a forest while the audience watches only the forest.","cn":"想象舞台吊装移动整片树林，而观众只看见树林。"}]},"examples":[{"en":"The mill's machinery was older than any of its workers.","cn":"这家磨坊的机械比它的任何工人都老。"},{"en":"Agricultural machinery changed the size of the average field.","cn":"农业机械改变了普通田块的大小。"},{"en":"Reform required changing the machinery, not just the minister.","cn":"改革需要更换机构本身，而不只是换部长。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「马（ma）先（chine）瑞（ry）」——马先拉动的这一整套东西，就是机械","word":"machinery"},"root":"希腊 mekhane「装置」→ 拉丁 machina → 法语 machine → 英语 machine；加集合词尾 -ery（法语 -erie）构成 machinery，指成套机器，后引申指机构与运作体系。","sensesIntro":{"en":"Eight senses move from machines as a body to the parts inside one, then to organisational apparatus, processes, farm equipment, stage rigging, abstract systems and site equipment.","cn":"八个义项从成套机器出发，走向单台机器内部部件，再到组织机构、流程、农业装备、舞台吊装、抽象体系与工地设备。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of machines coupled to one shaft, belts turning together until the floor trembles.","cn":"核心意象：一排机器接到同一根轴上，皮带一齐转动，地板微微发颤。"},"chain":["MACHINES","WORKING PARTS","TRANSMISSION","APPARATUS","PROCESS","IMPERSONAL POWER"],"branches":[{"senses":"01 · 05 · 08","en":"EQUIPMENT CLASSES: machines in general, farm equipment, and heavy site plant.","cn":"设备类别：泛指的机器、农业装备，以及工地重型设备。"},{"senses":"02","en":"INNER PARTS: the set of parts that makes one device move.","cn":"内部部件：使单台装置运动的那组零件。"},{"senses":"03","en":"INSTITUTIONAL APPARATUS: offices, staff and procedures that keep an organisation running.","cn":"机构装置：维持组织运转的部门、人员与程序。"},{"senses":"04","en":"PROCESS AS SYSTEM: regular steps that can be described and rearranged.","cn":"作为系统的流程：可被描述与重排的规律步骤。"},{"senses":"06 · 07","en":"HIDDEN AND VAST: stage rigging behind a curtain, and the mechanism of war or law.","cn":"隐蔽与庞大：幕后的舞台吊装，以及战争或法律的运作机制。"}]},"affixes":{"intro":{"en":"Machinery is machine with a collective ending; the base itself came into English through French from Latin.","cn":"machinery 是 machine 加集合词尾；其词基本身经法语从拉丁语进入英语。"},"latinIntro":{"en":"Latin machina is the direct source of French machine; the collective ending -ery came separately through French -erie.","cn":"拉丁语 machina 是法语 machine 的直接来源；集合词尾 -ery 另经法语 -erie 而来。"},"items":[{"word":"mekhane","structure":"mekhane (Greek noun)","meaning":"device, engine, means","meaningCN":"装置；器械；手段","example":"The Greek noun starts the chain of borrowings.","exampleCN":"这个希腊名词开启了一连串借入。"},{"word":"machina","structure":"machina (Latin noun)","meaning":"structure, engine, contrivance","meaningCN":"结构；器械；巧妙装置","example":"Latin passed the word to French unchanged in sense.","exampleCN":"拉丁语几乎原样把词义传给法语。"},{"word":"machine","structure":"machine (English noun from French)","meaning":"a powered device","meaningCN":"动力装置","example":"The base is a count noun and takes a plural.","exampleCN":"这个词基是可数名词，有复数。"},{"word":"-ery","structure":"-ery (collective ending from French -erie)","meaning":"a body or trade of things","meaningCN":"事物的整体或行业","example":"The ending gathers many machines into one mass.","exampleCN":"这个词尾把许多机器聚成一个整体。"},{"word":"-ist","structure":"-ist (agent ending from Greek)","meaning":"one who works with","meaningCN":"从事……的人","example":"The ending names the person who runs the equipment.","exampleCN":"这个词尾指操作设备的人。"},{"word":"-ism","structure":"-ism (noun ending from Greek)","meaning":"arrangement or system","meaningCN":"结构或体系","example":"The ending builds the word for one assembly of parts.","exampleCN":"这个词尾构成「一套部件组合」的词。"},{"word":"mechan-","structure":"mechan- (Greek bound base)","meaning":"machine","meaningCN":"机器","example":"The base appears across the whole technical family.","exampleCN":"这个词基出现在整个技术词族中。"},{"word":"-ical","structure":"-ical (adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending produces the related adjective.","exampleCN":"这个词尾产生相关形容词。"}],"latinEntries":[{"word":"machina","structure":"machina, machinae (n., first declension, from Greek)","meaning":"engine, structure, device","meaningCN":"器械、结构、装置"}],"derivatives":[{"word":"machine","pos":"n./v.","zh":"机器；机械加工"},{"word":"machinist","pos":"n.","zh":"机械操作工"},{"word":"mechanic","pos":"n.","zh":"技工"},{"word":"mechanism","pos":"n.","zh":"机构；机制"}]}},{"word":"machine","ipa_uk":"/məˈʃiːn/","ipa_us":"/məˈʃiːn/","definition_zh":"机器；由部件组成并做功的装置；也指计算机或组织化的运作体系；动词指机械加工","definition_en":"a device of connected parts that performs work; also a computer or an organised system, and to cut or shape with a machine tool","core_image":"一台车床夹着一段金属，刀头沿着导轨推进，铁屑卷成一圈圈落下来","scene":"车间的车床夹着一段金属，刀头沿导轨推进，铁屑卷成一圈圈落下。The machine cut the shaft to within a hair of the required size.","sceneCN":"这里 machine 指由部件组成并做功的装置（第 1 个义项：机器这一装置）；句意：这台机器把轴削到与要求尺寸相差不到一根头发。","pos":[{"tag":"n.","zh":"机器；计算机；运作体系"},{"tag":"v.","zh":"用机床加工；机械切削"}],"collocations":[{"phrase":"machine tool","zh":"机床"},{"phrase":"washing machine","zh":"洗衣机"},{"phrase":"machine learning","zh":"机器学习"},{"phrase":"party machine","zh":"政党机器"},{"phrase":"machine parts","zh":"机器零件"},{"phrase":"machine shop","zh":"机械加工车间"},{"phrase":"state machine","zh":"国家机器"}],"forms":[{"label":"复数","form":"machines"},{"label":"第三人称单数","form":"machines"},{"label":"过去式","form":"machined"},{"label":"过去分词","form":"machined"},{"label":"现在分词","form":"machining"}],"derivatives":[{"word":"machinery","pos":"n.","zh":"机械（总称）"},{"word":"machinist","pos":"n.","zh":"机械操作工"},{"word":"machining","pos":"n.","zh":"机械加工"},{"word":"mechanical","pos":"adj.","zh":"机械的"}],"senses":[{"no":"01","title":"A device that performs work","titleCN":"做功的装置","definition":"an assembly of connected parts that uses power to carry out a task","definitionCN":"由相连部件构成、使用动力完成任务的组合体","example":"The machine lifts the load with a single lever.","exampleCN":"这台机器只用一个手柄就抬起货物。","why":"the Greek noun named any contrivance, so the first sense is the broad one of a built device.","whyCN":"希腊名词原指任何巧妙装置，因此第一个义项就是「人造装置」这一宽泛含义。"},{"no":"02","title":"A computer","titleCN":"计算机","definition":"the computing hardware that executes stored instructions","definitionCN":"执行已存指令的计算硬件","example":"The machine rebooted before the backup finished.","exampleCN":"备份还没完成，机器就重启了。","why":"computers became the most common machine in daily life, and speakers shortened the name.","whyCN":"计算机成了日常最常见的机器，说话者就把名称缩短了。"},{"no":"03","title":"A household or workshop appliance","titleCN":"家用或车间器具","definition":"a named device for one task, as in a washing or sewing machine","definitionCN":"为单一任务命名的装置，如洗衣机或缝纫机","example":"The sewing machine has outlived three owners.","exampleCN":"那台缝纫机已经比三位主人活得都久。","why":"a device is named by its task plus this general word, which is how the compound names spread.","whyCN":"装置以「任务＋这个总称」命名，这类复合名称就是这样扩散的。"},{"no":"04","title":"A machine tool","titleCN":"机床","definition":"a powered tool that cuts or shapes metal and other materials","definitionCN":"切削或成型金属等材料的动力工具","example":"The new machine holds a tolerance of a hundredth of a millimetre.","exampleCN":"这台新机床能保持百分之一毫米的公差。","why":"in a workshop, the general word often means the tool that makes other parts.","whyCN":"在车间里，这个总称常指制造其他零件的工具。"},{"no":"05","title":"To cut or shape by machine","titleCN":"用机床切削成型","definition":"to remove material or form a part with a powered tool","definitionCN":"用动力工具去除材料或成型零件","example":"They machined the block in two passes.","exampleCN":"他们分两道工序加工了那块坯料。","why":"the noun became a verb the moment the tool's action needed a name.","whyCN":"当工具的动作需要一个名称时，名词就变成了动词。"},{"no":"06","title":"A political organisation","titleCN":"政党或政治组织","definition":"the permanent staff and structure that win elections or hold power","definitionCN":"赢得选举或维持权力的常设人员与结构","example":"The party machine decided the candidate before the vote.","exampleCN":"政党机器在投票之前就决定了候选人。","why":"an organisation that runs without sentiment is described by the most impersonal noun available.","whyCN":"不带感情运转的组织，就用最非人格的名词来描述。"},{"no":"07","title":"An impersonal system of rule","titleCN":"非人格的统治体系","definition":"the administrative apparatus of a state or large institution","definitionCN":"国家或大型机构的行政装置","example":"The state machine ground down every small request.","exampleCN":"国家机器把每一个小请求都磨掉了。","why":"the image of interlocking parts describes bureaucracy better than any abstract word.","whyCN":"「咬合的部件」这一意象，比任何抽象词都更能描述官僚体系。"},{"no":"08","title":"A person who acts automatically","titleCN":"像机器一样行动的人","definition":"a person treated as incapable of independent thought","definitionCN":"被视为无法独立思考的人","example":"They turned him into a machine that answered tickets.","exampleCN":"他们把他变成一台只回答工单的机器。","why":"calling a person a machine denies judgement, which is the insult the word carries here.","whyCN":"把人叫作机器就是否认其判断力，这正是这个词在此处的贬义。"},{"no":"09","title":"Automated by computation","titleCN":"由计算自动完成的","definition":"used before a noun for processes carried out by computers","definitionCN":"用在名词前，指由计算机完成的过程","example":"Machine translation improved, but it still misses tone.","exampleCN":"机器翻译进步了，却仍抓不住语气。","why":"as a modifier, the word marks the shift from human to computed action.","whyCN":"作修饰语时，这个词标记从人工到计算动作的转移。"},{"no":"10","title":"The power unit of a vehicle","titleCN":"车辆的动力机组","definition":"the engine and its housing in a boat, train or vehicle","definitionCN":"船、火车或车辆中的发动机及其外壳","example":"The fire machine kept its pump running for nine hours.","exampleCN":"消防车的泵持续运转了九个小时。","why":"early industrial English called a powered vehicle a machine, and the usage survives in a few names.","whyCN":"早期工业英语把动力车辆叫作 machine，这种用法在少数名称里留存下来。"}],"etymology":{"intro":{"en":"Machine came from Greek mekhane through Latin machina and French. It meant any contrivance long before it meant a powered device, and its computing and organisational senses are later extensions.","cn":"machine 经拉丁语 machina 与法语来自希腊语 mekhane。它很久以前指任何巧妙装置，之后才指动力装置；计算机义与组织义是更晚的延伸。"},"items":[{"era":"GREEK MEKHANE","en":"Greek mekhane named a device, especially a stage crane or a siege engine, and also a means or expedient.","cn":"希腊语 mekhane 指装置，尤指舞台吊机或攻城器械，也指手段与办法。"},{"era":"LATIN MACHINA","en":"Latin machina meant a structure, scaffold or engine, and the phrase deus ex machina came from the stage crane.","cn":"拉丁语 machina 指结构、脚手架或器械，短语 deus ex machina 就来自舞台吊机。"},{"era":"FRENCH MACHINE","en":"French machine entered English in the seventeenth century and covered any constructed device, not only powered ones.","cn":"法语 machine 在十七世纪进入英语，指任何建造出来的装置，而不只是动力装置。"},{"era":"INDUSTRIAL NARROWING","en":"Steam and factory work narrowed machine toward devices with moving parts driven by power.","cn":"蒸汽与工厂作业把 machine 收窄为由动力驱动、带运动部件的装置。"},{"era":"COMPUTING AND POLITICS","en":"The twentieth century added the computer and the party machine, both built on the image of parts working together.","cn":"二十世纪加上计算机与政党机器两义，二者都建立在「部件协同运转」的意象上。"},{"era":"VERB USE","en":"Machining arose in workshops as the verb for what a machine tool does to metal.","cn":"machining 在车间里产生，指机床对金属所做的加工。"}]},"similar":{"note":{"en":"The first group is the machine family in other shapes; the second group is the neighbouring words for devices and systems.","cn":"第一组是 machine 词族的其他形态；第二组是装置与体系的相邻说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"machinery","ipa":"/məˈʃiːnəri/","tag":"the collective","definition":"Machines as a mass; one machine is countable, machinery is not.","definitionCN":"指机器的整体；一台机器可数，machinery 不可数。"},{"word":"machinist","ipa":"/məˈʃiːnɪst/","tag":"the operator","definition":"A person who operates or makes machines; the noun names the equipment.","definitionCN":"指操作或制造机器的人；名词指设备。"},{"word":"mechanic","ipa":"/məˈkænɪk/","tag":"the repairer","definition":"A person who repairs machines; a machine is the thing repaired.","definitionCN":"指修理机器的人；machine 是被修的东西。"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","tag":"the arrangement","definition":"The set of parts that produces a motion; a machine contains one or more mechanisms.","definitionCN":"指产生运动的那组部件；一台机器包含一个或多个机构。"}]},{"heading":"NEAR MEANING","entries":[{"word":"device","ipa":"/dɪˈvaɪs/","tag":"general term","definition":"Any constructed thing made for a purpose, often small; a machine usually has moving parts and power.","definitionCN":"为某目的造的任何东西，常指小型；machine 通常有运动部件与动力。"},{"word":"engine","ipa":"/ˈendʒɪn/","tag":"the power source","definition":"A machine that converts energy into motion; it is a part of many machines.","definitionCN":"把能量转成运动的机器；它是许多机器的一个部件。"},{"word":"tool","ipa":"/tuːl/","tag":"held by hand","definition":"An implement a person holds and guides; a machine supplies its own motion.","definitionCN":"由人握持与引导的器具；machine 自己提供运动。"},{"word":"apparatus","ipa":"/əˈpærətəs/","tag":"set of parts","definition":"A set of equipment working as one, often for an experiment or an institution.","definitionCN":"作为整体工作的一整套设备，常用于实验或机构。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations from the real Greek source and the real noun-verb pair.","cn":"正常联想：来自真实希腊语来源与真实名词动词成对关系。"},"normal":[{"en":"Mekhane meant a stage crane, so a machine is first a thing that lifts and moves.","cn":"mekhane 原指舞台吊机，所以 machine 首先是能吊起与移动东西的装置。"},{"en":"The verb forms are regular: machines, machined, machined, machining.","cn":"动词形式规则：machines、machined、machined、machining。"},{"en":"Task names build on it: washing machine, sewing machine, machine tool.","cn":"任务名称在它之上构成：洗衣机、缝纫机、机床。"},{"en":"The computing sense is simply the shortened name of the most common machine.","cn":"计算机义不过是「最常用机器」的简称。"},{"en":"Two objects split the verb: machine a part, machine a surface.","cn":"两类宾语分开动词：加工一个零件，加工一个表面。"}],"abstract":[{"en":"Picture a crane on a stage lowering a god who is only a painted board.","cn":"想象舞台上的吊机放下一个神，而那神不过是一块画板。"},{"en":"Picture a lathe turning a shaft until the metal is exactly the size of an idea.","cn":"想象车床削一根轴，直到金属恰好等于一个想法的尺寸。"},{"en":"Picture an office where every request disappears into a slot and comes out stamped.","cn":"想象一间办公室，每个请求都落进一个槽口，再盖着章出来。"}]},"examples":[{"en":"The machine does the lifting, but a person still chooses where.","cn":"机器负责起吊，但选择吊到哪里仍由人决定。"},{"en":"They machined the replacement part overnight.","cn":"他们连夜加工了那只替换零件。"},{"en":"The party machine had chosen the nominee months earlier.","cn":"政党机器几个月前就已定下候选人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「马（ma）身（chine）」——马拉着的一副身架，就是最早干活的机器","word":"machine"},"root":"希腊 mekhane「装置、舞台吊机」→ 拉丁 machina「结构、器械」→ 法语 machine → 英语 machine；先泛指装置，工业时代收窄为动力装置，二十世纪扩展出计算机与组织体系义，动词指机床加工。","sensesIntro":{"en":"Ten senses run from the general device to the computer, the appliance, the machine tool, the verb, the party machine, the state apparatus, the dehumanised person, computed processes and the vehicle's power unit.","cn":"十个义项从泛指的装置出发，经过计算机、家用器具、机床、动词用法、政党机器、国家机器、被机械化的人、计算化流程，最后到车辆动力机组。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lathe holding a metal shaft while a cutter advances and curls off chips.","cn":"核心意象：车床夹着一段金属轴，刀头推进，铁屑卷曲落下。"},"chain":["PARTS","MOTION","WORK DONE","TOOL THAT MAKES","SYSTEM OF PARTS","CONTROL"],"branches":[{"senses":"01 · 03","en":"DEVICES: any working assembly, and the named appliance built on that pattern.","cn":"装置：任何做功的组合体，以及按此模式命名的器具。"},{"senses":"02 · 09","en":"COMPUTATION: the computer itself, and processes carried out by computed action.","cn":"计算：计算机本身，以及由计算动作完成的过程。"},{"senses":"04 · 05","en":"TOOL AND ACTION: the machine tool, and the verb for what it does to metal.","cn":"工具与动作：机床，以及它对金属所做加工的动词。"},{"senses":"06 · 07","en":"ORGANISED POWER: the party machine, and the administrative apparatus of a state.","cn":"组织化的权力：政党机器，以及国家的行政装置。"},{"senses":"08 · 10","en":"THE MECHANICAL FIGURE: a person reduced to a machine, and a vehicle's engine unit.","cn":"机械化的形象：被降为机器的人，以及车辆的动力机组。"}]},"affixes":{"intro":{"en":"Machine is a borrowed noun with no living affix; its family adds -ery, -ist, -ing and compound forms.","cn":"machine 是借入名词，本身没有能产的词缀；其词族另加 -ery、-ist、-ing 与复合形式。"},"latinIntro":{"en":"Latin machina is the direct source of the French and English forms; the Greek noun mekhane stands behind it.","cn":"拉丁语 machina 是法语与英语形式的直接来源，其背后是希腊名词 mekhane。"},"items":[{"word":"mekhane","structure":"mekhane (Greek noun)","meaning":"device, stage crane, means","meaningCN":"装置；舞台吊机；手段","example":"The Greek noun carries both the machine and the trick.","exampleCN":"这个希腊名词兼有「机器」与「计策」两面。"},{"word":"machina","structure":"machina (Latin noun)","meaning":"engine, scaffold, structure","meaningCN":"器械；脚手架；结构","example":"Latin widened the noun to any built structure.","exampleCN":"拉丁语把这个名词扩大到任何建造的结构。"},{"word":"machine","structure":"machine (English noun and verb)","meaning":"device; to cut with a tool","meaningCN":"装置；用工具切削","example":"English uses the same form for the object and the action.","exampleCN":"英语用同一形式指对象与动作。"},{"word":"-ery","structure":"-ery (collective ending)","meaning":"a mass of","meaningCN":"成批的","example":"The ending produces the uncountable collective.","exampleCN":"这个词尾产生不可数的集合名词。"},{"word":"-ist","structure":"-ist (agent ending)","meaning":"one who works with","meaningCN":"从事……的人","example":"The ending names the operator.","exampleCN":"这个词尾指操作者。"},{"word":"-ing","structure":"-ing (English gerund ending)","meaning":"the activity of","meaningCN":"……的活动","example":"The ending names the cutting work itself.","exampleCN":"这个词尾指切削工作本身。"},{"word":"-able","structure":"-able (English adjective ending)","meaning":"able to be","meaningCN":"可以被……的","example":"The ending marks what a device can read or do.","exampleCN":"这个词尾标记装置能读或能做的事。"},{"word":"-ism","structure":"-ism (noun ending)","meaning":"arrangement","meaningCN":"结构","example":"The ending names one arrangement of moving parts.","exampleCN":"这个词尾指一套运动部件的组合。"}],"latinEntries":[{"word":"machina","structure":"machina, machinae (n., first declension, from Greek)","meaning":"engine, structure, device","meaningCN":"器械、结构、装置"}],"derivatives":[{"word":"machinery","pos":"n.","zh":"机械（总称）"},{"word":"machinist","pos":"n.","zh":"机械操作工"},{"word":"machining","pos":"n.","zh":"机械加工"},{"word":"mechanism","pos":"n.","zh":"机构"}]}}]);
